import{n as e,t}from"./helpers-0sYvox5E.js";var n=[t({id:`cache-pavilion-001`,postGuide:[`elasticache-valkey`],postGuideKey:[`elasticache-valkey`],building:`cache-pavilion`,bullets:[`3.3-K2`],d:2,stem:`A gaming company stores player profiles in Amazon Aurora. Its leaderboard queries are slow, so the company wants a managed in-memory store that keeps player rankings in sorted sets, keeps a replica of the data, and fails over automatically when a node is lost. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create an Amazon ElastiCache for Valkey cache with a replica and automatic failover for the rankings`,`The Valkey engine supports sorted sets, replication and automatic failover, and ElastiCache manages the nodes for the company.`],wrong:[[`Create an Amazon ElastiCache for Memcached cluster with several nodes spread across Availability Zones`,`The Memcached engine has no replication, no automatic failover and no sorted sets, so it fails every named requirement.`],[`Place an Amazon DynamoDB Accelerator (DAX) cluster in front of the Aurora database to serve the ranking reads`,`DAX is a caching service that is compatible with DynamoDB only, so it cannot sit in front of an Aurora database.`],[`Add Aurora Replicas to the cluster and send the ranking queries to the cluster reader endpoint`,`Aurora Replicas are relational read-only database instances rather than an in-memory store with sorted sets, so the ranking queries stay slow.`]],slot:1,evidence:[`elasticache-engines|High availability (replication) No Yes Yes Automatic failover No Optional Required Pub/Sub capabilities No Yes Yes Sorted sets No Yes Yes`,`dax|DAX is a DynamoDB-compatible caching service that enables you to benefit from fast in-memory performance for demanding applications.`]}),t({id:`cache-pavilion-002`,postGuide:[`elasticache-valkey`],building:`cache-pavilion`,bullets:[`3.3-K2`],d:1,stem:`A company caches rendered page fragments that it reads from its database. The cached values are simple objects. The company wants the simplest possible caching model, large nodes with multiple cores, and the ability to add and remove nodes as demand changes. Replication is not needed. Which choice is the SIMPLEST fit for these requirements?`,correct:[`Amazon ElastiCache for Memcached`,`Memcached is the engine to choose for the simplest model, large multi-core nodes, scaling out and in by adding and removing nodes, and caching objects.`],wrong:[[`Amazon ElastiCache for Valkey with cluster mode enabled and replica nodes in every shard`,`It adds replication and shard management that the company does not need, so it is not the simplest model that fits the requirements.`],[`Amazon ElastiCache for Redis OSS with a replication group and required automatic failover`,`Replication groups with failover add complexity the company did not ask for, so the model is not the simplest possible.`],[`Amazon DynamoDB Accelerator (DAX) with a cluster of several nodes in front of the database`,`DAX caches only DynamoDB tables, and the company is caching reads from its own database, so it cannot serve here.`]],slot:3,evidence:[`elasticache-engines|Choose Memcached if the following apply for you: You need the simplest model possible. You need to run large nodes with multiple cores or threads. You need the ability to scale out and in, adding and removing nodes as demand on your system increases and decreases. You need to cache objects.`]}),t({id:`cache-pavilion-003`,building:`cache-pavilion`,bullets:[`3.3-K2`],d:1,stem:`A company needs an in-memory cache for a session store. The cache must survive the loss of a node or an Availability Zone with only a brief interruption, and the company wants AWS to manage the nodes. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create an ElastiCache for Redis OSS replication group with a replica in another Availability Zone and Multi-AZ`,`If the primary node fails, ElastiCache promotes a replica and propagates its DNS name, so writes resume quickly with no servers to manage.`],wrong:[[`Create a single-node Amazon ElastiCache for Redis OSS cluster with no replicas`,`There is no replica to promote, so losing the node or its Availability Zone loses the cache and interrupts the application.`],[`Create an Amazon ElastiCache for Memcached cluster with nodes in one Availability Zone`,`The Memcached engine is the simplest model, without replica promotion, and one Availability Zone offers no protection against its loss.`],[`Run a self-managed Redis server on Amazon EC2 instances in an Auto Scaling group`,`The team would install, patch and fail over the cache itself, which is the opposite of the LEAST operational overhead.`]],slot:0,evidence:[`elasticache-autofailover|This replacement results in some downtime for the cluster, but if Multi-AZ is enabled, the downtime is minimized.`,`elasticache-autofailover|This failover and replica promotion ensure that you can resume writing to the new primary as soon as promotion is complete.`]}),t({id:`cache-pavilion-004`,building:`cache-pavilion`,bullets:[`3.3-S5`],d:2,stem:`A company runs four applications on Amazon DynamoDB and plans to add a DAX cluster for only one of them. Which application is the BEST candidate for DAX?`,correct:[`A product page service that reads the same few popular items many times per second and accepts eventually consistent reads`,`DAX suits applications that read a small number of items more often than others and can use eventually consistent reads from the cache.`],wrong:[[`A ledger service that must always read the latest committed balance by using strongly consistent reads`,`DAX passes strongly consistent reads through to DynamoDB, and it is not ideal for applications that cannot tolerate eventually consistent reads.`],[`A telemetry service that writes millions of new items per hour and almost never reads the same item twice`,`DAX is not ideal for write-intensive applications or for applications without many repeated reads.`],[`A nightly job that scans the whole table once and writes a summary report to Amazon S3`,`A single scan has no repeated reads to serve from the cache, so DAX adds cost without improving the job.`]],slot:2,evidence:[`dax|Applications that read a small number of items more frequently than others.`,`dax|Applications that require strongly consistent reads (or that cannot tolerate eventually consistent reads).`,`dax|Applications that are write-intensive.`]}),t({id:`cache-pavilion-005`,building:`cache-pavilion`,bullets:[`3.3-S5`],d:3,stem:`An application reads product items from Amazon DynamoDB through a DAX cluster that uses the default item cache settings. A third-party batch tool that the company cannot modify writes price updates directly to the DynamoDB table, and shoppers see old prices for several minutes after each batch. New prices must appear within about 30 seconds, and the company still wants repeated reads served from the cache. Which solution meets these requirements with the LEAST change?`,correct:[`Create a custom DAX parameter group that sets the item cache TTL to 30 seconds and use it for the cluster`,`The TTL of the item cache is set through a parameter group, and items expire after that TTL, so each item is re-read from DynamoDB within 30 seconds while other reads still hit the cache.`],wrong:[[`Change the batch tool to send its price updates through the DAX cluster endpoint instead of DynamoDB`,`Writes through DAX are written through to the cache, but the batch tool cannot be modified, so this change is not possible.`],[`Have the application request strongly consistent reads for every product read through the DAX client`,`Strongly consistent reads are passed through to DynamoDB, so the cache would no longer serve the repeated reads the company wants.`],[`Move the DAX cluster to a larger node type so that it can hold more items in its item cache`,`Node size changes how many items fit but not how long an item stays, so old prices still remain until the default TTL expires.`]],slot:1,evidence:[`dax-concepts|The item cache has a Time to Live (TTL) setting, which is 5 minutes by default.`,`dax-concepts|An item expires if it has remained in the cache for longer than the TTL setting.`,`dax-cluster-mgmt|You can use a parameter group to specify cache TTL behavior.`,`dax-cluster-mgmt|If you want to use different TTL settings, you can launch a DAX cluster using a custom parameter group.`,`dax-concepts|If the request specifies strongly consistent reads, DAX passes the request through to DynamoDB.`]}),e({id:`cache-pavilion-006`,building:`cache-pavilion`,bullets:[`3.3-K2`],d:3,stem:`A company is adding caching in two places. A ticketing application reads inventory from an Amazon DynamoDB table by using eventually consistent reads, and the company wants the LEAST application change there. A reporting dashboard re-runs the same queries against an Amazon RDS for PostgreSQL database all day. Which TWO solutions meet these requirements? (Choose two.)`,correct:[[`Add a DAX cluster in front of the DynamoDB table and use the DAX client`,`DAX is API-compatible with DynamoDB, so it needs only minimal functional changes to an existing application.`],[`Add an Amazon ElastiCache cache between the dashboard and the RDS database`,`ElastiCache is an in-memory store that sits between the application and the database, so repeated queries can be answered from memory.`]],wrong:[[`Add a DAX cluster in front of the RDS for PostgreSQL database for the dashboard queries`,`DAX is compatible with DynamoDB only, so it cannot cache queries to an RDS database.`],[`Add an ElastiCache for Memcached cluster in front of the DynamoDB table and write the lazy-loading code in the ticketing application`,`It works as a cache but requires new caching logic in the application, so it is not the LEAST application change.`],[`Add an RDS read replica and point the ticketing application at it for the inventory reads`,`The inventory is in DynamoDB, which has no RDS read replica, so this does nothing for the ticketing application.`]],slots:[0,3],evidence:[`dax|DAX reduces operational and application complexity by providing a managed service that is API-compatible with DynamoDB.`,`dax|Therefore, it requires only minimal functional changes to use with an existing application.`,`elasticache-strategies|Amazon ElastiCache is an in-memory key-value store that sits between your application and the data store (database) that it accesses.`]}),t({id:`cache-pavilion-007`,building:`cache-pavilion`,bullets:[`3.3-S5`],d:2,stem:`A company runs a read-heavy product catalog on Amazon RDS. Reads of the same items repeat constantly, and the database is the bottleneck. The team wants lower read latency and less database load, and can change the application code. Which solution BEST meets these requirements?`,correct:[`Add Amazon ElastiCache and use lazy loading so reads go to the cache first`,`Lazy loading loads only requested data into the cache, and repeated reads are answered from memory instead of the database.`],wrong:[[`Add a DAX cluster in front of the RDS database to hold the hottest items`,`DAX is a caching service for DynamoDB tables and cannot sit in front of an RDS database.`],[`Place an Amazon CloudFront distribution in front of the database endpoint`,`CloudFront caches web content at edge locations and cannot serve queries directly from an RDS database.`],[`Move the database to a larger instance class and keep reading every item from the database`,`It adds capacity but every read still reaches the database, so the repeated reads are not offloaded.`]],slot:3,evidence:[`elasticache-strategies|lazy loading is a caching strategy that loads data into the cache only when necessary.`]}),e({id:`cache-pavilion-008`,building:`cache-pavilion`,bullets:[`3.3-S5`],d:2,stem:`A company caches customer records from Amazon RDS in Amazon ElastiCache by using write-through: each change is written to the database and to the cache. After a failed cache node was replaced, reads for records that had not changed since then missed the cache because the new node started empty. Most records are never read after they are written, so the cache is also full of unused data. Which TWO changes fix both problems with the LEAST redesign? (Choose two.)`,correct:[[`Add lazy loading so the application writes a record to the cache whenever a read misses`,`Lazy loading fills the empty node on demand, which removes the missing data that write-through alone leaves behind.`],[`Set a time to live (TTL) value on every record written to the cache`,`The TTL expires records that are never read, so unused data no longer fills the cache.`]],wrong:[[`Replace the cache with a DAX cluster that caches the RDS queries`,`DAX is compatible with DynamoDB only, so it cannot cache an RDS database.`],[`Move to a larger cache node type so that more unused records fit in memory`,`More memory leaves the empty-node misses unsolved and just stores more unread data.`],[`Add an RDS read replica and send all of the reads to the replica`,`It does not repopulate the cache or remove unused data from it, so neither problem is fixed.`]],slots:[1,4],evidence:[`elasticache-strategies|If you spin up a new node, whether due to a node failure or scaling out, there is missing data.`,`elasticache-strategies|You can minimize this by implementing lazy loading with write-through.`,`elasticache-strategies|By adding a time to live (TTL) value, you can minimize wasted space.`]}),t({id:`cache-pavilion-009`,building:`cache-pavilion`,bullets:[`3.3-K2`],d:2,tags:[`mock-reserve`],stem:`A company is building a chat feature. Application servers must publish messages to channels and subscribe to them through a managed in-memory service, which must also keep a replica of the data and fail over automatically. Which solution BEST meets these requirements?`,correct:[`An Amazon ElastiCache for Redis OSS replication group with automatic failover`,`The Redis OSS engine supports Pub/Sub, replication and automatic failover, and ElastiCache manages the in-memory nodes.`],wrong:[[`An Amazon ElastiCache for Memcached cluster with nodes in several Availability Zones`,`The Memcached engine has no Pub/Sub, no replication and no automatic failover.`],[`An Amazon DynamoDB Accelerator (DAX) cluster placed between the application servers`,`DAX is a cache for DynamoDB tables and does not provide channels for publishing and subscribing between application servers.`],[`An Amazon SNS topic with a subscription for each application server`,`SNS is a messaging service, not an in-memory data service with a replica and failover of cached data, so the data requirement is not met.`]],slot:0,evidence:[`elasticache-engines|High availability (replication) No Yes Yes Automatic failover No Optional Required Pub/Sub capabilities No Yes Yes Sorted sets No Yes Yes`]})],r=[t({id:`container-yard-001`,building:`container-yard`,bullets:[`3.2-K5`],d:1,tags:[`placement-eligible`],stem:`An AWS Lambda function writes to an Amazon RDS database instance that accepts a limited number of connections. During traffic spikes the function scales out, uses every connection and causes errors. The company wants to cap how many copies of the function run at once, with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Set reserved concurrency on the function to a value the database can support`,`Reserved concurrency also acts as an upper bound, which prevents overwhelming downstream resources such as database connections.`],wrong:[[`Configure provisioned concurrency on the function equal to the connection limit`,`Pre-initialized environments reduce cold starts, and the function can still scale beyond them on standard concurrency.`],[`Request an increase of the account concurrency quota in the Region`,`A higher quota lets even more copies run at once, which would use more database connections.`],[`Increase the memory that is configured for the function to its maximum`,`Memory sizing changes how fast each invocation runs and does not set a ceiling on concurrent invocations.`]],slot:2,evidence:[`lambda-reserved|Additionally, reserved concurrency can be used for limiting concurrency to prevent overwhelming downstream resources, like database connections.`,`lambda-reserved|Reserved concurrency acts as both a lower and upper bound - it reserves the specified capacity exclusively for your function while also preventing it from scaling beyond that limit.`,`lambda-provisioned|After this, the Event Function can continue to scale on standard, unreserved concurrency if you haven't reached your account concurrency limit.`]}),e({id:`container-yard-002`,postGuide:[`lambda-snapstart`],building:`container-yard`,bullets:[`3.2-K5`],d:3,tags:[`placement-eligible`],stem:`Many AWS Lambda functions in one Region share the account concurrency limit. During sales events an order-lookup function is throttled because other functions use up the shared pool, and the total demand of all functions also exceeds the Regional limit. The company wants the order-lookup function to keep running. Which TWO actions will BEST meet these requirements? (Choose two.)`,correct:[[`Reserve concurrency for the order-lookup function`,`Once concurrency is dedicated to a function, no other function can use it, so the pool cannot be exhausted by neighbours.`],[`Request a quota increase for the account concurrency limit`,`A quota increase raises the Regional ceiling, so the total demand of all functions can be met without throttling.`]],wrong:[[`Enable SnapStart on the order-lookup function`,`SnapStart shortens start-up latency and does not give the function any more concurrency.`],[`Set the reserved concurrency of the order-lookup function to 0`,`A reserved concurrency of 0 stops the function from processing any events.`],[`Increase the ephemeral storage that is configured for the order-lookup function`,`Storage size has no effect on how many concurrent executions the function can use.`]],slots:[0,2],evidence:[`lambda-concurrency|When you dedicate reserved concurrency to an Event Function, no other Event Function can use that concurrency.`,`lambda-concurrency|To support your specific account needs, you can request a quota increase and configure function-level concurrency controls so that your critical Event Functions don't experience throttling.`,`lambda-reserved|To intentionally throttle an Event Function, set its reserved concurrency to 0.`]}),e({id:`container-yard-003`,building:`container-yard`,bullets:[`3.2-K5`],d:2,tags:[`placement-eligible`],stem:`A company runs five AWS Lambda functions. Provisioned concurrency incurs additional charges, so the company wants to configure it only for the functions that benefit MOST from it. Which TWO functions should receive provisioned concurrency? (Choose two.)`,correct:[[`A checkout API function that web shoppers call and wait on`,`Interactive workloads are the most sensitive to latency, so they benefit most from pre-initialized environments.`],[`A sign-in function that a mobile app calls on every launch`,`Mobile applications are interactive and sensitive to cold start latency.`]],wrong:[[`A nightly job that builds sales reports from a schedule`,`Nobody waits on it, and asynchronous work is usually not latency sensitive, so the extra charge buys little.`],[`A function that reads batches of messages from an Amazon SQS queue`,`It is an asynchronous data processing workload, which does not usually need provisioned concurrency.`],[`A function that compacts files when they land in an Amazon S3 bucket`,`It runs in the background after an upload and no user waits on its response.`]],slots:[1,4],evidence:[`lambda-provisioned|Generally, interactive workloads benefit the most from the feature.`,`lambda-provisioned|Asynchronous workloads, such as data processing pipelines, are often less latency sensitive and so do not usually need provisioned concurrency.`,`lambda-provisioned|Configuring provisioned concurrency incurs additional charges to your AWS account.`]}),t({id:`container-yard-004`,building:`container-yard`,bullets:[`3.2-K5`],d:3,tags:[`placement-eligible`],stem:`A latency-sensitive API runs on an AWS Lambda function that uses the Java 17 managed runtime. The function mounts an Amazon EFS file system, and a large framework makes initialization take several seconds, so the first request in each new execution environment is slow. Traffic is predictable, and the company needs execution environments to be already initialized when requests arrive, without changing the function code. Which solution meets these requirements?`,correct:[`Configure provisioned concurrency on an alias of a published version, sized to the expected peak`,`Provisioned concurrency keeps pre-initialized execution environments ready, which reduces cold start latencies.`],wrong:[[`Raise the reserved concurrency of the function to the expected peak`,`Reserved concurrency sets the maximum concurrency and Lambda might terminate idle environments, so it does not pre-initialize them.`],[`Raise the function timeout to its maximum value`,`The timeout limits how long one invocation can run and does not initialize any environment before a request arrives.`],[`Rewrite the API as containers that run in an Amazon ECS service on AWS Fargate`,`This is a re-platforming effort that changes the code and the way the API is run and billed.`]],slot:0,evidence:[`lambda-provisioned|Provisioned concurrency – This is the number of pre-initialized execution environments allocated to your Event Function.`,`lambda-provisioned|Provisioned concurrency – This is the number of pre-initialized execution environments allocated to your Event Function.`,`lambda-concurrency|In contrast, when using reserved concurrency, Lambda might completely terminate an environment after a period of inactivity.`]}),t({id:`container-yard-005`,building:`container-yard`,bullets:[`3.2-K5`],d:2,tags:[`placement-eligible`],stem:`A page-view counter is kept in a variable inside an AWS Lambda function behind Amazon API Gateway. Under load the totals are wrong, because many concurrent execution environments each hold their own copy of the count. The company wants correct totals while the function keeps scaling, with the LEAST change. Which solution meets these requirements?`,correct:[`Keep the counter in an Amazon DynamoDB table and increment it with an atomic update`,`Each invocation has no shared state, so the count must live in a store that all environments share; an atomic counter avoids interference between writes.`],wrong:[[`Keep the counter in a file in the /tmp directory of the function`,`Ephemeral storage is temporary and unique to each execution environment, so every environment would again hold its own copy.`],[`Set the reserved concurrency of the function to 1 so that one copy handles every request`,`This serializes all requests through one environment and gives up the horizontal scaling the company wants to keep.`],[`Raise the memory configured for the function so that the variable survives longer`,`Memory size does not make separate execution environments share a variable.`]],slot:3,evidence:[`lambda-welcome|Each invocation runs independently with no shared state, scaling horizontally to match demand.`,`lambda-ephemeral|This storage is temporary and unique to each execution environment.`,`dynamodb-atomic-counters|You can use the UpdateItem operation to implement an atomic counter—a numeric attribute that is incremented, unconditionally, without interfering with other write requests.`]}),t({id:`container-yard-006`,building:`container-yard`,bullets:[`3.2-K5`],d:2,tags:[`placement-eligible`],stem:`A software provider runs containerized jobs for many customers on Amazon ECS. Security requires that jobs of different customers do not share a kernel, CPU, memory or network interface, and the provider does not want to manage Amazon EC2 instances. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Run each job as a task on AWS Fargate, where every task has its own isolation boundary`,`A Fargate task does not share its kernel, CPU, memory or network interface with another task, and there are no instances to manage.`],wrong:[[`Run the jobs as tasks on a shared pool of Amazon EC2 container instances`,`Tasks placed on one instance run on its host, and the provider would have to patch and scale the instances.`],[`Run the jobs as pods on one self-managed Kubernetes cluster built on Amazon EC2 instances`,`Pods on shared worker nodes run on the nodes' hosts, and the company would operate the cluster and its nodes.`],[`Run all jobs in one large container on a single Amazon EC2 instance with separate processes`,`Processes in one container share the kernel and resources, and the provider still manages the instance.`]],slot:1,evidence:[`fargate-ecs|Each Fargate task has its own isolation boundary and does not share the underlying kernel, CPU resources, memory resources, or elastic network interface with another task.`,`fargate-ecs|This removes the need to choose server types, decide when to scale your clusters, or optimize cluster packing.`]}),t({id:`container-yard-007`,building:`container-yard`,bullets:[`3.2-K6`],d:2,tags:[`placement-eligible`],stem:`A containerized API runs as an Amazon ECS service. When average CPU utilization passes 60 percent the team wants two tasks added, and when it passes 85 percent the team wants ten tasks added at once, with tasks removed as load falls. Which solution BEST meets these requirements?`,correct:[`Create a step scaling policy for the service with step adjustments tied to CloudWatch alarms`,`Step scaling lets the team define the thresholds and how many tasks to add or remove when each threshold is crossed.`],wrong:[[`Create a target tracking policy for the service with a target of 60 percent CPU utilization`,`It holds a metric near a target value, and the team cannot set how many tasks each threshold adds.`],[`Create scheduled actions that set the number of tasks at fixed times of day`,`Spiky traffic does not follow a schedule, so fixed times would miss the spikes.`],[`Create an Amazon EC2 Auto Scaling group policy that adds instances when CPU utilization rises`,`EC2 Auto Scaling changes the number of instances, and the number of ECS tasks is scaled through Application Auto Scaling.`]],slot:2,evidence:[`ecs-autoscaling|With step scaling you can more quickly react to changes in demand, because you define the specific thresholds for your scaling metrics, and how many tasks to add or remove when the thresholds are crossed.`,`ecs-autoscaling|Amazon ECS leverages the Application Auto Scaling service to provide this functionality.`,`ecs-autoscaling|Use predefined increments based on CloudWatch alarms to scale Amazon ECS services— Increase or decrease the number of tasks that your service runs based on a set of scaling adjustments, known as step adjustments, that vary based on the size of the alarm breach.`]}),t({id:`container-yard-008`,building:`container-yard`,bullets:[`3.2-K6`],d:3,tags:[`placement-eligible`],postGuide:[`ecs-min-capacity-0`],postGuideKey:[`ecs-min-capacity-0`],stem:`Worker tasks of an Amazon ECS service on AWS Fargate consume messages from an Amazon SQS queue. The company wants the number of tasks to follow the backlog of messages and to fall to zero when the queue is empty, with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Scale the ECS service automatically on a backlog-per-task metric, with a minimum capacity of 0`,`The backlog per task reflects the queue, and a minimum capacity of 0 lets the task count scale to zero.`],wrong:[[`Scale the service with a target tracking policy on average CPU utilization`,`CPU utilization does not measure the messages waiting in the queue, so the task count would not follow the backlog.`],[`Use scheduled actions that change the number of tasks at the start of every hour`,`A schedule is not tied to the queue, so tasks run when the queue is empty and are missing when it is long.`],[`Use an Amazon EC2 Auto Scaling group policy that adds instances when the queue grows`,`EC2 Auto Scaling scales instances, and the ECS service itself is scaled through Application Auto Scaling.`]],slot:0,evidence:[`ecs-autoscaling|Scale Amazon ECS services based on an Amazon SQS queue—Increase or decrease the number of tasks that your service runs based on the backlog of messages in an Amazon SQS queue, using a backlog per task custom metric.`,`ecs-autoscaling|If you want your task count to scale to zero when there's no work to be done, set a minimum capacity of 0.`]}),t({id:`container-yard-009`,building:`container-yard`,bullets:[`3.2-K6`],d:2,stem:`A company runs Kubernetes workloads on Amazon EKS. At peak times new pods cannot be scheduled for lack of node capacity, and some pods need GPU instances. The company wants EC2 nodes launched just in time, sized to the pending pods' compute and acceleration requirements, within about a minute. The team accepts installing and operating open-source autoscaling software in the cluster. Which solution meets these requirements?`,correct:[`Install Karpenter in the cluster`,`Karpenter launches right-sized compute resources in response to changing application load in under a minute, based on workload requirements.`],wrong:[[`Turn on Amazon ECS service auto scaling for the Kubernetes workloads`,`ECS service auto scaling changes the number of ECS tasks and does not add nodes to an EKS cluster.`],[`Ask an engineer to resize the node group by hand before and after each peak`,`Manual changes need a person for every peak and cannot react within a minute.`],[`Create a larger fixed-size node group sized for the peak and keep it running`,`This does not match capacity to the pods that are pending and leaves nodes idle after peaks, which wastes cost.`]],slot:3,evidence:[`eks-autoscaling|Karpenter launches right-sized compute resources (for example, Amazon EC2 instances) in response to changing application load in under a minute.`,`eks-autoscaling|Karpenter automatically provisions new compute resources based on the specific requirements of cluster workloads.`,`eks-autoscaling|These include compute, storage, acceleration, and scheduling requirements.`,`eks-autoscaling|Karpenter is open-source software which AWS customers are responsible for installing, configuring, and managing in their Kubernetes clusters.`]}),t({id:`container-yard-010`,building:`container-yard`,bullets:[`3.2-K6`],d:1,stem:`A team runs an Amazon ECS service that serves employees only. The number of tasks should drop each evening at 19:00 and rise again at 07:00 every day, and nobody should have to make the changes. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create scheduled scaling actions for the ECS service`,`Scheduled actions increase or decrease the number of tasks of the service based on the date and time (the service uses Application Auto Scaling for this).`],wrong:[[`Create scheduled actions in an Amazon EC2 Auto Scaling group`,`EC2 Auto Scaling scheduled actions change instance capacity, and the task count of the service is scaled through Application Auto Scaling.`],[`Create a step scaling policy that responds to a CloudWatch alarm on CPU utilization`,`An alarm on CPU follows load and not the clock, so tasks would not change at 19:00 and 07:00.`],[`Ask an engineer to update the desired count of the service each evening and morning`,`A manual change depends on a person every day, where a schedule runs automatically.`]],slot:1,evidence:[`ecs-autoscaling|Use scheduled actions to scale Amazon ECS services—Increase or decrease the number of tasks that your service runs based on the date and time.`,`ecs-autoscaling|Amazon ECS leverages the Application Auto Scaling service to provide this functionality.`]}),t({id:`container-yard-011`,building:`container-yard`,bullets:[`3.2-K5`],d:3,tags:[`mock-reserve`],stem:`A latency-sensitive AWS Lambda function uses the Java 17 managed runtime and mounts an Amazon EFS file system for shared reference data. The team set reserved concurrency on the function, but the first requests after quiet periods are still slow because new execution environments start slowly. Strict response times are required. Which change BEST meets these requirements?`,correct:[`Configure provisioned concurrency on an alias, sized for the expected load`,`Pre-initialized environments are ready to respond immediately, which reduces cold start latencies.`],wrong:[[`Raise the reserved concurrency of the function to the expected peak`,`Lambda might completely terminate an environment after a period of inactivity, so slow starts would still occur.`],[`Request an increase of the account-level concurrency quota`,`A higher quota allows more concurrent executions but does not pre-initialize any environment.`],[`Invoke the function asynchronously instead of synchronously`,`The invocation type does not change whether an execution environment is already initialized.`]],slot:2,evidence:[`lambda-provisioned|Provisioned concurrency – This is the number of pre-initialized execution environments allocated to your Event Function.`,`lambda-provisioned|Provisioned concurrency – This is the number of pre-initialized execution environments allocated to your Event Function.`,`lambda-concurrency|In contrast, when using reserved concurrency, Lambda might completely terminate an environment after a period of inactivity.`]}),t({id:`container-yard-012`,building:`container-yard`,bullets:[`3.2-K6`],d:2,tags:[`mock-reserve`],stem:`An Amazon ECS service on AWS Fargate has load that changes unpredictably through the day. The team wants the average CPU utilization of the service kept near a chosen value, with tasks added and removed automatically and the LEAST configuration effort. Which solution meets these requirements?`,correct:[`Attach a target tracking scaling policy on average CPU utilization to the service`,`Target tracking adjusts the task count to keep the metric near the target value, and it is the easiest scaling mode to use.`],wrong:[[`Attach a step scaling policy with thresholds and task counts that the team defines for each alarm`,`The team must define every threshold and the number of tasks to add or remove, which is more configuration than target tracking.`],[`Create scheduled scaling actions that set the task count for each part of the day`,`A schedule follows the clock, not the load, so it cannot keep CPU near a value when the load is unpredictable.`],[`Set the desired task count to the largest number of tasks ever needed`,`The service would run peak capacity around the clock and nothing adjusts the count to the CPU value.`]],slot:0,evidence:[`ecs-autoscaling|Target tracking is the easiest mode to use.`,`ecs-autoscaling|With step scaling you can more quickly react to changes in demand, because you define the specific thresholds for your scaling metrics, and how many tasks to add or remove when the thresholds are crossed.`]})],i=[t({id:`data-lake-reservoir-001`,building:`data-lake-reservoir`,bullets:[`3.5-K1`],d:1,stem:`A company stores application logs as CSV files in Amazon S3. Analysts want to run ad-hoc SQL queries on the files straight away, without loading the data anywhere first and without setting up servers. Which service meets these requirements with the LEAST operational overhead?`,correct:[`Amazon Athena, with a table defined over the S3 location`,`Athena analyzes data directly in S3 using standard SQL and is serverless, so there is nothing to load or manage.`],wrong:[[`An Amazon Redshift cluster that the data is copied into before the analysts query it`,`The data must first be loaded into the cluster, and a cluster still has to be sized and managed, which the requirements rule out.`],[`An Amazon EMR cluster running Apache Spark that the analysts submit SQL jobs to`,`EMR runs big data frameworks on a cluster that the company provisions and manages, so servers remain to operate.`],[`An Amazon RDS for PostgreSQL instance that the CSV files are imported into each day`,`The files would have to be imported into a database instance that must be sized and managed, so the data is not queried in place.`]],slot:0,evidence:[`athena-what-is|Amazon Athena is an interactive query service that makes it easy to analyze data directly in Amazon Simple Storage Service (Amazon S3) using standard SQL.`,`athena-what-is|serverless, so there is no infrastructure to set up or manage`,`emr-what-is|big data frameworks, such as Apache Hadoop and Apache Spark, on AWS to process and analyze vast amounts of data`]}),t({id:`data-lake-reservoir-002`,building:`data-lake-reservoir`,bullets:[`3.5-K1`],d:2,stem:`A data lake in Amazon S3 holds a customer table with a national ID column. Finance analysts may read every column, while marketing analysts may read all columns except the national ID. Both groups query through Amazon Athena and Amazon EMR, and the security team wants to manage these rules in one place. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Register the data in AWS Lake Formation and grant each group permissions on only its allowed columns`,`Lake Formation is the single place for access control on data lake data and enforces column-level permissions across Athena and EMR.`],wrong:[[`Write IAM identity policies that allow each group to read different S3 prefixes where the data is stored`,`S3 prefix permissions control access to objects, not to individual columns inside the same files, so the national ID column cannot be hidden.`],[`Create an S3 bucket policy for each group that denies access to the objects that hold the national ID values`,`A bucket policy works on whole objects and cannot hide one column inside shared files, and a separate policy per group means rules in many places.`],[`Use an AWS Glue crawler to create separate table definitions for each analyst group over the same files`,`A crawler discovers and catalogs data and does not enforce access, so every group could still read all columns of the files.`]],slot:1,evidence:[`lake-formation|Lake Formation provides a single place to manage access controls for data in your data lake.`,`lake-formation|You can define security policies that restrict access to data at the database, table, column, row, and cell levels.`,`lake-formation|Lake Formation permissions are enforced using granular controls at the column, row, and cell-levels across AWS analytics and machine learning services, including Amazon Athena, Amazon Quick, Amazon Redshift Spectrum, Amazon EMR, and AWS Glue.`]}),t({id:`data-lake-reservoir-003`,building:`data-lake-reservoir`,bullets:[`3.5-K1`],d:3,stem:`A company has thousands of tables in its data lake, and new tables arrive every week. Each table is classified as public, internal or restricted, and users from different teams need access based on those classifications. The company wants access managed without writing a separate policy for every table, and wants new tables to follow the same rules once they are labelled. Which solution meets these requirements with the LEAST administrative effort?`,correct:[`Attach LF-Tags to tables and columns in AWS Lake Formation and grant each team permissions by tag`,`LF-Tags scale governance by replacing policy definitions for thousands of resources with a few logical tags that new tables can carry.`],wrong:[[`Create a separate IAM policy for every table and attach it to the role of each team that needs access`,`This is exactly the per-table policy writing the company wants to avoid, and every new table would need new policy statements.`],[`Copy each class of tables into its own S3 bucket and give each team a bucket policy for its classes`,`Copying data into buckets by class duplicates data and needs bucket policies to maintain, instead of labelling the tables once.`],[`Run an AWS Glue crawler every week and give the teams access to the tables it creates in the catalog`,`A crawler catalogs data but does not grant or enforce access by classification, so permissions would still be managed some other way.`]],slot:2,evidence:[`lake-formation|Use Lake Formation attribute-based access control to manage hundreds or even thousands of data permissions by creating custom labels called LF-Tags.`,`lake-formation|LF-Tags make sure that data governance can be scaled easily by replacing the policy definitions of thousands of resources with a few logical tags.`]}),t({id:`data-lake-reservoir-004`,building:`data-lake-reservoir`,bullets:[`3.5-S1`],d:2,stem:`New daily folders of data files land in an Amazon S3 data lake from several source systems. Analysts query the data with Amazon Athena and need table definitions, including new partitions, kept up to date. The company wants this done automatically with the LEAST custom code. Which solution meets these requirements?`,correct:[`Run an AWS Glue crawler on a schedule to discover the data and update the tables in the Data Catalog`,`A crawler automatically scans data sources and extracts metadata into the Data Catalog, which Athena can then query.`],wrong:[[`Write an AWS Lambda function that runs a CREATE TABLE statement in Athena whenever a file arrives`,`It keeps tables current but needs custom code to write, deploy and maintain, which the company wants to avoid.`],[`Give analysts permissions in AWS Lake Formation on the S3 location so that the tables appear in Athena`,`Lake Formation governs access to cataloged data and does not scan the files to discover tables or new partitions.`],[`Ask the source teams to email table definitions that an administrator enters into the catalog each week`,`It is a manual process that lags behind the daily data and cannot keep new partitions current automatically.`]],slot:3,evidence:[`glue-catalog|crawler, which automatically scans your data sources and extracts metadata.`,`glue-what-is|you can immediately search and query cataloged data using Amazon Athena, Amazon EMR, and Amazon Redshift Spectrum.`]}),t({id:`data-lake-reservoir-005`,building:`data-lake-reservoir`,bullets:[`3.5-K1`],d:2,stem:`A finance team runs complex SQL queries over several hundred gigabytes of data in Amazon S3. Query volume is tiny for most of the month and spikes sharply at month end, when many analysts run queries at once. The company does not want to size or manage capacity for the peak. Which solution is the SIMPLEST that meets these requirements?`,correct:[`Query the data in place with Amazon Athena, which runs queries in parallel and scales automatically`,`Athena is serverless and scales automatically by running queries in parallel, so no capacity is sized for the month-end peak.`],wrong:[[`Create an Amazon EMR cluster sized for the month-end peak and keep it running all month`,`The cluster must be sized and managed, and it sits idle for most of the month, so capacity is still planned for the peak.`],[`Import the data into an Amazon RDS for MySQL instance large enough to handle month-end concurrency`,`The data has to be imported and the instance sized for the peak, which is the capacity management the company wants to avoid.`],[`Load the data into an Amazon DynamoDB table and have the analysts write their queries against it`,`DynamoDB is not a SQL analytics engine over S3 data, so it needs a full data model and load, and it does not fit complex SQL queries.`]],slot:0,evidence:[`athena-what-is|Athena scales automatically—running queries in parallel—so results are fast, even with large datasets and complex queries.`,`athena-what-is|serverless, so there is no infrastructure to set up or manage`]}),e({id:`data-lake-reservoir-006`,building:`data-lake-reservoir`,bullets:[`3.5-S1`],d:2,stem:`A company queries 8 TB of raw CSV files in an Amazon S3 data lake with Amazon Athena. Almost every query filters on a date range and reads only a few of the 40 columns, yet each query scans all of the data and is slow. The company wants to cut the amount of data scanned and improve performance. Which TWO actions should the company take? (Choose two.)`,correct:[[`Convert the files to a columnar format such as Apache Parquet`,`Columnar formats let Athena fetch only the blocks it needs and compress by column, so queries read less data.`],[`Partition the data by date so that each query reads only the partitions in its date range`,`Partitioning restricts the amount of data each query scans, which improves performance and reduces cost.`]],wrong:[[`Store the files in a second S3 bucket in another Region and query that copy`,`A copy in another Region does not change how much data each query scans.`],[`Compress each CSV file into a single large ZIP archive and keep the files in the same layout`,`The query would still read all the data, and an archive does not provide partitions or columnar reads.`],[`Add more analysts to run the same queries in parallel from separate sessions`,`More parallel sessions do not reduce the data each query scans, so the cost and time per query stay the same.`]],slots:[0,3],evidence:[`athena-columnar|Predicate pushdown in Parquet and ORC enables Athena queries to fetch only the blocks it needs, improving query performance.`,`athena-columnar|Apache Parquet and ORC are columnar storage formats that are optimized for fast retrieval of data and used in AWS analytical applications.`,`athena-partitions|By partitioning your data, you can restrict the amount of data scanned by each query, thus improving performance and reducing cost.`]}),t({id:`data-lake-reservoir-007`,building:`data-lake-reservoir`,bullets:[`3.5-S1`],d:1,stem:`A security team is worried that a user with bucket-policy permissions might accidentally make a data lake bucket public. The team wants a control, set once for the whole AWS account, that limits public access even if a bucket policy or object permission would allow it. Which solution BEST meets these requirements?`,correct:[`Turn on Amazon S3 Block Public Access settings for the account`,`The settings override bucket policies and permissions so that public access to these resources is limited.`],wrong:[[`Write a bucket policy on each data lake bucket that denies public principals and review the policies monthly`,`Users can modify bucket policies to allow public access again, so this is not a control that overrides them across the account.`],[`Enable server-side encryption with an AWS KMS key as the default for every data lake bucket`,`Encryption protects data at rest and does not stop a policy or permission from granting public access to the objects.`],[`Enable Amazon S3 Versioning on every data lake bucket so that changes to objects can be rolled back`,`Versioning keeps earlier object versions and does not limit public access in the first place.`]],slot:1,evidence:[`s3-block-public-access|S3 Block Public Access settings override these policies and permissions so that you can limit public access to these resources.`,`s3-block-public-access|users can modify bucket policies, access point policies, or object permissions to allow public access.`]}),e({id:`data-lake-reservoir-008`,building:`data-lake-reservoir`,bullets:[`3.5-S1`],d:3,stem:`A central AWS account owns a data lake with tables cataloged in the AWS Glue Data Catalog. Analytics teams in 20 other AWS accounts need read access, and each team may see only certain columns. The company wants one place to manage these grants and does not want extra copies of the data. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Grant AWS Lake Formation permissions on the tables to the AWS accounts of the analytics teams`,`Lake Formation lets you share data across multiple AWS accounts with fine-grained access to the Data Catalog metadata and underlying data.`],[`Limit each team's grant to the columns that the team is allowed to see`,`Lake Formation supports column-level permissions, so each team receives only the columns it needs from the single copy.`]],wrong:[[`Add a bucket policy that allows the roles of all 20 accounts to read every object in the bucket`,`A bucket policy grants access to whole objects, so the teams could not be limited to certain columns.`],[`Use S3 replication to copy the data into a bucket in each of the 20 accounts`,`Replication creates 20 extra copies of the data, which the company does not want, and grants are then managed in 20 places.`],[`Create an IAM user for every analyst in the central account and share one set of access keys per team`,`This spreads long-lived keys and per-user management, and it gives no column-level restriction on the data.`]],slots:[2,0],evidence:[`lake-formation|Lake Formation also allows you to share data internally and externally across multiple AWS accounts, AWS organizations or directly with IAM principals in another account providing fine-grained access to the Data Catalog metadata and underlying data.`,`lake-formation|You can define security policies that restrict access to data at the database, table, column, row, and cell levels.`]}),t({id:`data-lake-reservoir-009`,building:`data-lake-reservoir`,bullets:[`3.5-S1`],d:1,stem:`A company collects relational exports from line of business applications, JSON events from mobile apps and sensor readings from IoT devices. It wants to keep all of this data as it arrives, at any scale, and decide later which analytics to run on it. Which storage choice BEST meets these requirements?`,correct:[`Store the data as-is in Amazon S3 as the storage layer of a data lake`,`A data lake stores structured and unstructured data as-is at any scale, and S3 is used for data lakes.`],wrong:[[`Load all of the data into tables in a single Amazon RDS for MySQL database`,`A relational database needs the data structured into tables first, which does not suit JSON events and sensor readings kept as they arrive.`],[`Load all of the data into Amazon Redshift tables before running any analytics`,`Redshift stores tabular data, so the data would have to be structured and loaded first, not kept as-is.`],[`Write all of the data into one Amazon DynamoDB table with a single partition key`,`A key-value table needs a key design chosen up front and is not a store for keeping raw data of any form to analyze later.`]],slot:2,evidence:[`what-is-data-lake|A data lake is a centralized repository that allows you to store all your structured and unstructured data at any scale.`,`what-is-data-lake|You can store your data as-is, without having to first structure the data`,`s3-what-is|Customers of all sizes and industries can use Amazon S3 to store and protect any amount of data for a range of use cases, such as data lakes`]}),t({id:`data-lake-reservoir-010`,building:`data-lake-reservoir`,bullets:[`3.5-S4`],d:2,stem:`A retailer's dashboards query a customer table in an Amazon S3 data lake through Amazon Athena. The table is cataloged in the AWS Glue Data Catalog and registered with AWS Lake Formation. Every dashboard query runs under one IAM role that the dashboard service assumes, whichever employee views the dashboard. No dashboard may expose the customer email column. Which solution meets this requirement with the LEAST effort?`,correct:[`Grant that IAM role Lake Formation permissions on the table that exclude the email column`,`Lake Formation permissions apply to the IAM role that runs the queries and can be limited to columns, so the shared role never reads the email column.`],wrong:[[`Grant each employee who views the dashboards Lake Formation permissions that exclude the email column`,`The queries run under the shared role, so grants made to the viewers are not the permissions evaluated for the dashboard queries.`],[`Leave the shared role with access to the whole table and hide the email column in each dashboard visual`,`Hiding a field in a visual is not an access control, and the role can still read the email column through Athena.`],[`Attach an IAM policy to the shared role that denies reads of the email column in the S3 objects`,`IAM policies for Amazon S3 apply to objects, not to a column inside the files, so the column cannot be denied this way.`]],slot:3,evidence:[`lake-formation|You can define security policies that restrict access to data at the database, table, column, row, and cell levels.`,`lake-formation|These policies apply to IAM users and roles, and to users and groups when federating through an external identity provider.`]}),t({id:`data-lake-reservoir-011`,building:`data-lake-reservoir`,bullets:[`3.5-S4`],d:3,stem:`Executive dashboards show daily totals per product, computed from 4 TB of order events in a Parquet table that is queried through Amazon Athena. Each dashboard load re-runs the aggregation over the whole table and is slow. The table receives new data only once a night. The company wants fast dashboards with the LEAST data scanned per load. Which solution meets these requirements?`,correct:[`Store the daily totals in a summary table with an Athena CTAS query after each nightly load, and point the dashboards at it`,`The aggregate is computed once and the dashboards read the small result table, instead of repeatedly querying the raw data set.`],wrong:[[`Create an Athena view that holds the aggregation and point the dashboards at the view`,`The query that defines a view runs each time the view is referenced, so every load still aggregates the full table.`],[`Run the aggregation on an Amazon EMR cluster each time a dashboard loads and return the result`,`This adds a cluster to start, size and manage for every load, and the raw data is still scanned on each load.`],[`Copy the order events into a second S3 bucket in the same Region and point the dashboards at it`,`The copy holds the same 4 TB in the same layout, so every dashboard load still scans all of it.`]],slot:0,evidence:[`athena-ctas-what|Create tables from query results in one step, without repeatedly querying raw data sets.`,`athena-views|The query that defines a view runs each time the view is referenced in a query.`]}),t({id:`data-lake-reservoir-012`,postGuide:[`athena-query-result-reuse`],postGuideKey:[`athena-query-result-reuse`],building:`data-lake-reservoir`,bullets:[`3.5-S4`],d:2,stem:`Hundreds of employees open the same sales dashboard throughout the day. Each open runs the identical SQL query in Amazon Athena against a table that is refreshed only once an hour, so the same data is scanned again and again and results are slow. The company wants repeated opens within the hour to avoid new scans, with the LEAST change. Which solution meets these requirements?`,correct:[`Enable Athena query result reuse for the dashboard query with a maximum age of one hour`,`Athena returns the stored result of a matching earlier run that is not older than the specified age, which cuts bytes scanned and improves performance.`],wrong:[[`Raise the dashboard auto-refresh to every minute so that the data on screen stays current`,`More frequent refreshes run the same query even more often, so they increase the repeated scans instead of avoiding them.`],[`Copy the table into a second S3 bucket in the same Region and point the dashboard at the copy`,`The copy holds the same data in the same layout, so each open still scans all of it.`],[`Create an Amazon Redshift cluster, load the table into it, and move the dashboard to the cluster`,`This adds a cluster to size and load when the problem is identical queries over data that changes hourly, which result reuse already handles.`]],slot:1,evidence:[`athena-reuse|When you re-run a query in Athena, you can optionally choose to reuse the last stored query result.`,`athena-reuse|This option can increase performance and reduce costs in terms of the number of bytes scanned.`,`athena-reuse|Athena uses the stored result as long as it is not older than the age that you specify.`]}),e({id:`data-lake-reservoir-013`,building:`data-lake-reservoir`,bullets:[`3.5-S1`],d:3,tags:[`mock-reserve`],stem:`A company is securing a new data lake in Amazon S3. Analysts must see the customer table without its personal data columns, and the company must guard against any bucket or object being made public by mistake. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Grant analysts AWS Lake Formation permissions on the table limited to the columns without personal data`,`Lake Formation enforces column-level permissions on data lake data, so the personal data columns stay hidden.`],[`Turn on S3 Block Public Access for the buckets of the data lake`,`The settings override policies and permissions so that public access to the buckets and objects is limited.`]],wrong:[[`Enable Amazon S3 Versioning on the data lake buckets`,`Versioning keeps earlier object versions and neither hides columns nor limits public access.`],[`Turn on server access logging for the data lake buckets`,`Logging records requests after they occur and does not prevent public access or hide columns.`],[`Set the default encryption of the buckets to SSE-S3`,`Encryption protects data at rest and does not limit which columns analysts see or stop objects from being made public.`]],slots:[1,4],evidence:[`lake-formation|You can define security policies that restrict access to data at the database, table, column, row, and cell levels.`,`s3-block-public-access|S3 Block Public Access settings override these policies and permissions so that you can limit public access to these resources.`]}),t({id:`data-lake-reservoir-014`,building:`data-lake-reservoir`,bullets:[`3.5-S4`],d:2,tags:[`mock-reserve`],stem:`Thousands of employees open the company's executive dashboards at the same time each morning. The dashboards query tables that are already loaded in an Amazon Redshift cluster, and the queries queue during the morning peak. The company wants consistently fast performance for the concurrent users without resizing the cluster by hand. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Turn on concurrency scaling for the cluster so that it adds capacity automatically during the peak`,`Concurrency scaling supports thousands of concurrent users and queries by automatically adding cluster capacity when queries increase.`],wrong:[[`Resize the cluster to a larger node configuration and keep it at that size all day`,`This is a manual resize, and capacity sized for the morning peak stays in place when the load is low.`],[`Export the tables to Amazon S3 each night and have the dashboards query the files through an Amazon EMR cluster`,`This adds an export process and a cluster to manage, and it moves the data away from the warehouse that already holds it.`],[`Create a second Amazon Redshift cluster for each department and load the tables into all of them`,`Each department cluster holds a copy of the data that must be loaded and kept current, which adds work instead of removing it.`]],slot:2,evidence:[`redshift-concurrency|With the Concurrency Scaling feature, you can support thousands of concurrent users and concurrent queries, with consistently fast query performance.`,`redshift-concurrency|When you turn on concurrency scaling, Amazon Redshift automatically adds additional cluster capacity to process an increase in both read and write queries.`]})],a=[t({id:`database-registry-001`,postGuide:[`dms-schema-conversion`],building:`database-registry`,bullets:[`3.3-K6`],d:1,stem:`A company runs a PostgreSQL database on premises and wants to move it to Amazon RDS for PostgreSQL. The source database must stay in use until cutover, and downtime at cutover must be minimal. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Use AWS DMS to migrate the data and replicate ongoing changes until the cutover`,`AWS DMS supports migrations that keep the same engine and can replicate ongoing changes to keep the source and target in sync.`],wrong:[[`Use DMS Schema Conversion to convert the schema first and then copy the data once with a one-time load`,`The engine does not change, so conversion is unnecessary, and a one-time load leaves the target behind the live source.`],[`Export the database to a dump file each weekend and import it into RDS during a maintenance window`,`Each import is a one-time copy that needs a long outage and leaves the target out of date until the next one.`],[`Use AWS DataSync to copy the database files to Amazon S3 and restore them into the RDS instance`,`DataSync moves file data and does not replicate database changes, and RDS cannot restore raw database files from S3.`]],slot:0,evidence:[`dms-what-is|Conversely, if you want to migrate away from old infrastructure but continue to use the same database engine, AWS DMS also supports that process.`,`dms-what-is|You can perform one-time migrations or replicate ongoing changes to keep sources and targets in sync.`]}),t({id:`database-registry-002`,postGuide:[`dms-schema-conversion`],postGuideKey:[`dms-schema-conversion`],building:`database-registry`,bullets:[`3.3-K6`],d:2,stem:`A company will migrate an on-premises Oracle database that contains many tables, views, triggers and stored procedures to Amazon Aurora PostgreSQL. The company wants the converted schema and code objects created on the target before any data is copied. Which solution meets these requirements with the LEAST manual effort?`,correct:[`Use DMS Schema Conversion to convert the schema and code objects, apply them to Aurora, and then use AWS DMS to migrate the data`,`Schema conversion assesses and converts the source schema and code to the new target engine, and AWS DMS then moves the data.`],wrong:[[`Run an AWS DMS task alone and let it create the target tables and primary keys before the data is copied`,`DMS creates tables and primary keys but does not convert the triggers and stored procedures that the company needs on the target.`],[`Copy the Oracle data files to Amazon S3 with AWS DataSync and load them into Aurora with SQL scripts`,`DataSync copies files and does no schema or code conversion, so the Oracle code objects would not work on PostgreSQL.`],[`Rewrite every trigger and stored procedure by hand in PostgreSQL syntax and then run AWS DMS for the data`,`It works, but the manual rewrite is the effort that DMS Schema Conversion automates, so it is not the LEAST manual effort.`]],slot:1,evidence:[`dms-what-is|To migrate to a different database engine, you can use DMS Schema Conversion.`,`dms-what-is|This service automatically assesses and converts your source schemas to a new target engine.`,`dms-what-is|AWS DMS creates the tables and associated primary keys if they don't exist on the target.`,`dms-what-is|Or you can use DMS Schema Conversion to create some or all of the target tables, indexes, views, triggers, and so on.`]}),e({id:`database-registry-003`,postGuide:[`dms-schema-conversion`],postGuideKey:[`dms-schema-conversion`],building:`database-registry`,bullets:[`3.3-K6`],d:2,stem:`A company is moving a production MySQL database from its data center to Amazon RDS for PostgreSQL. The application keeps running against the source database for two weeks of testing, and the target must stay in sync until the final cutover. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Convert the source schema to the PostgreSQL engine with DMS Schema Conversion and apply it to the target`,`The engine changes from MySQL to PostgreSQL, so the schema must be converted for the new target engine before the data is migrated.`],[`Run an AWS DMS task that replicates ongoing changes from the source to the target`,`Ongoing replication keeps the target in sync with the live source until the cutover.`]],wrong:[[`Create an RDS for PostgreSQL read replica that uses the on-premises MySQL database as its source`,`A read replica is created from an RDS DB instance and cannot use an on-premises database of another engine as its source.`],[`Run a one-time AWS DMS migration at the start of testing and stop the application until the copy ends`,`A one-time copy leaves the target behind the live source during the two weeks, and the outage is not needed.`],[`Use AWS DataSync to copy the database files to Amazon S3 each night for the PostgreSQL target`,`DataSync copies files and cannot convert the schema or keep a different database engine in sync.`]],slots:[1,3],evidence:[`dms-what-is|To migrate to a different database engine, you can use DMS Schema Conversion.`,`dms-what-is|You can perform one-time migrations or replicate ongoing changes to keep sources and targets in sync.`,`rds-read-replicas|The following information doesn't apply to setting up replication with an instance that is running on an Amazon EC2 instance or that is on-premises.`]}),t({id:`database-registry-004`,building:`database-registry`,bullets:[`3.3-S3`],d:1,tags:[`trap:aurora-vs-rds`],stem:`A company's application runs on MariaDB and depends on MariaDB-specific behavior. The company wants a fully managed relational database with the LEAST change to the application. Which solution meets these requirements?`,correct:[`Amazon RDS for MariaDB`,`MariaDB is one of the engines that Amazon RDS offers as a managed database, so the application keeps its engine.`],wrong:[[`Amazon Aurora MySQL-Compatible Edition`,`Aurora is compatible with MySQL and PostgreSQL, and MariaDB is not an Aurora engine, so the application would have to change.`],[`Amazon Aurora PostgreSQL-Compatible Edition`,`It is a PostgreSQL-compatible engine, so the MariaDB-specific application would need a migration and code changes.`],[`Amazon DynamoDB with on-demand capacity`,`It is a NoSQL database with a different data model, so the relational MariaDB application would be rewritten.`]],slot:2,evidence:[`database-decision|The Amazon RDS engines include PostgreSQL, MySQL, MariaDB, SQL Server, Oracle, and Db2.`,`database-decision|The Amazon Aurora engines include Amazon Aurora with PostgreSQL-Compatible Edition, Amazon Aurora MySQL-Compatible Edition, and Amazon Aurora DSQL.`]}),t({id:`database-registry-005`,building:`database-registry`,bullets:[`3.3-S3`],d:2,tags:[`trap:aurora-vs-rds`],stem:`A company is modernizing an on-premises MySQL application whose query patterns are hard to predict. It wants a managed MySQL-compatible database whose storage keeps copies of the data across three Availability Zones, and it wants to reuse its existing MySQL tools and drivers. Which solution BEST meets these requirements?`,correct:[`Amazon Aurora MySQL-Compatible Edition`,`Aurora keeps cluster volume copies across three Availability Zones, works with existing MySQL tools, and suits modernizing workloads with less predictable queries.`],wrong:[[`Amazon RDS for MySQL with a Multi-AZ DB instance deployment`,`Its data sits on the primary and one standby in a second Availability Zone, so it does not keep copies across three Availability Zones.`],[`Amazon RDS for MariaDB with a Multi-AZ DB instance deployment`,`MariaDB is a different engine from MySQL and also keeps only a primary and a standby, not copies across three zones.`],[`MySQL installed on Amazon EC2 instances with Amazon EBS volumes`,`The company would manage the database itself, and EBS volumes do not keep copies of the data across three Availability Zones.`]],slot:3,evidence:[`aurora-storage|A cluster volume consists of copies of the data across three Availability Zones in a single AWS Region.`,`aurora-overview|The code, tools, and applications you use today with your existing MySQL and PostgreSQL databases can be used with Aurora.`,`database-decision|Amazon Aurora Relational Use when you're migrating or modernizing an on-premises relational workload, or if your workload has less predictable query patterns.`]}),t({id:`database-registry-006`,postGuide:[`dms-schema-conversion`],building:`database-registry`,bullets:[`3.3-S3`],d:2,tags:[`trap:aurora-vs-rds`],stem:`A company must migrate an application that its vendor supports only on Microsoft SQL Server. The company wants to cut database administration, needs automatic failover to a second Availability Zone, and will not change the database engine. Which solution BEST meets these requirements?`,correct:[`Amazon RDS for SQL Server in a Multi-AZ deployment`,`RDS offers SQL Server as a managed engine, and a Multi-AZ deployment adds the standby in another Availability Zone with automatic failover.`],wrong:[[`Amazon Aurora PostgreSQL-Compatible Edition after converting the schema with DMS Schema Conversion`,`It changes the engine from SQL Server to PostgreSQL, which the vendor does not support and the company ruled out.`],[`Amazon Aurora MySQL-Compatible Edition after a heterogeneous migration with AWS DMS`,`Aurora has no SQL Server engine, so this also changes the engine and breaks the vendor support.`],[`SQL Server on Amazon EC2 instances with Always On availability groups across two Availability Zones`,`It keeps the engine, but the company would patch, back up and operate the servers itself instead of cutting administration.`]],slot:0,evidence:[`database-decision|The Amazon RDS engines include PostgreSQL, MySQL, MariaDB, SQL Server, Oracle, and Db2.`,`rds-multi-az-instance|Microsoft SQL Server DB instances use SQL Server Database Mirroring (DBM) or Always On Availability Groups (AGs).`,`rds-multi-az-instance|In a Multi-AZ DB instance deployment, Amazon RDS automatically provisions and maintains a synchronous standby replica in a different Availability Zone.`]}),t({id:`database-registry-007`,postGuide:[`elasticache-valkey`],building:`database-registry`,bullets:[`3.3-K8`],d:1,stem:`A company's e-commerce database handles customer orders. Analysts now run complex queries over many terabytes of historical sales data, and these queries slow the order system. The orders database must keep serving orders. Which service should hold the data for the analytical queries?`,correct:[`Amazon Redshift`,`Redshift is a data warehousing service designed for large-scale analytics workloads, so the analysts stop competing with the order system.`],wrong:[[`Amazon DynamoDB`,`It is a key-value NoSQL database for transactional access by key, and it is not built for complex analytical queries over large data.`],[`Amazon ElastiCache for Valkey`,`It is an in-memory cache that sits in front of a data store and cannot serve as a warehouse for terabytes of history.`],[`Amazon Neptune`,`It is a graph database for highly connected data such as social networks, not a warehouse for analytics.`]],slot:1,evidence:[`database-decision|If you need to store and analyze massive amounts of data quickly and efficiently (a requirement that is typically met by an OLAP application), AWS offers Amazon Redshift.`,`database-decision|Amazon Redshift is a fully managed, cloud-based data warehousing service that is designed to handle large-scale analytics workloads.`]}),t({id:`database-registry-008`,postGuide:[`dynamodb-price-cut-2024`],building:`database-registry`,bullets:[`3.3-S4`],d:2,tags:[`placement-eligible`],stem:`A start-up is launching a mobile app whose data lives in an Amazon DynamoDB table accessed by user ID. Traffic is unknown and could jump or fall sharply after each marketing campaign. The team wants no capacity planning and wants to pay only for the requests that the app makes. Which throughput setting meets these requirements with the LEAST operational overhead?`,correct:[`On-demand capacity mode`,`On-demand mode needs no capacity planning, monitoring or scaling policies, and it bills per request so the team pays for what it uses.`],wrong:[[`Provisioned capacity mode with read and write capacity sized for the forecast campaign peak`,`The team would have to forecast capacity, and it is charged for the provisioned capacity whether or not the app consumes it.`],[`Provisioned capacity mode with auto scaling and minimum and maximum limits chosen by the team`,`The team must still pick limits and a target utilization from guesses about traffic, which is the capacity planning it wants to avoid.`],[`Provisioned capacity mode with a fixed low capacity that the team raises by hand after each campaign`,`Requests above the low capacity are throttled until someone raises it, and the manual changes add operational work.`]],slot:2,evidence:[`dynamodb-capacity|DynamoDB on-demand enables you to create a table without worrying about capacity planning, monitoring usage, and configuring scaling policies.`,`dynamodb-capacity|DynamoDB on-demand offers pay-per-request pricing for read and write requests so that you only pay for what you use.`,`dynamodb-provisioned|To configure auto scaling in DynamoDB, you set the minimum and maximum levels of read and write capacity in addition to the target utilization percentage.`]}),t({id:`database-registry-009`,building:`database-registry`,bullets:[`3.3-S4`],d:3,tags:[`placement-eligible`],stem:`A company's order-history service uses a DynamoDB table with traffic that grows slowly and follows a daily curve. The team knows the curve well, wants capacity to follow the known curve between a floor and a ceiling that the team sets, and does not want to pay for unused capacity in the quiet hours. Which throughput configuration BEST meets these requirements?`,correct:[`Provisioned mode with DynamoDB auto scaling, using minimum and maximum capacity set from the daily curve`,`Provisioned mode suits workloads with a known traffic pattern, and auto scaling lowers capacity when the workload decreases.`],wrong:[[`Provisioned mode at a fixed level sized for the daily peak with no auto scaling`,`The table is charged for the provisioned throughput through the quiet hours, so the company pays for unused capacity.`],[`Provisioned mode at the average daily level with no auto scaling`,`Traffic above the average would exceed the provisioned capacity at the daily peak, so requests would be throttled.`],[`On-demand capacity mode, which accepts whatever traffic arrives`,`On-demand mode runs without capacity planning. The floor and ceiling in the stem are the auto scaling minimum and maximum levels that DynamoDB sets for provisioned mode, which AWS points to for a workload whose capacity can be planned in advance.`]],slot:3,evidence:[`dynamodb-provisioned|To configure auto scaling in DynamoDB, you set the minimum and maximum levels of read and write capacity in addition to the target utilization percentage.`,`dynamodb-capacity|This helps you govern your DynamoDB use to stay at or below a defined request rate in order to obtain cost predictability.`,`dynamodb-provisioned|When the workload decreases, DynamoDB auto scaling can decrease the throughput so that you don't pay for unused provisioned capacity.`,`dynamodb-ondemand|automatically scales to accommodate the most demanding workloads without capacity planning.`,`dynamodb-capacity|You can choose to use provisioned capacity if you have steady workloads with predictable growth, and if you can reliably forecast capacity requirements for your application.`]}),t({id:`database-registry-010`,postGuide:[`elasticache-valkey`],building:`database-registry`,bullets:[`3.3-S4`],d:2,tags:[`placement-eligible`],stem:`A company is building an invoicing system. Finance staff run ad hoc SQL queries that join customers, invoices and payments, and the data is highly structured. Developers propose Amazon DynamoDB for the system. Which database BEST fits the invoicing system?`,correct:[`Amazon Aurora PostgreSQL-Compatible Edition`,`The invoicing data is structured business objects that finance joins with SQL, which is the case for a relational database such as Aurora.`],wrong:[[`Amazon DynamoDB with on-demand capacity`,`NoSQL databases have different access patterns than relational databases, and it is not possible to join tables, so the ad hoc SQL joins would have to be redesigned.`],[`Amazon ElastiCache for Valkey as the primary data store`,`ElastiCache is an in-memory key-value store that sits between the application and the database it accesses, so it caches data for a database rather than serving as the store for the invoices.`],[`Amazon Redshift as the primary transactional database`,`Redshift is a data warehouse for large-scale analytics, and the invoicing system needs a transactional database.`]],slot:0,evidence:[`msa-data-store|Relational databases are still very popular to store structured data and business objects.`,`msa-data-store|It is important to understand that NoSQL databases have different access patterns than relational databases.`,`database-decision|Amazon Redshift is a fully managed, cloud-based data warehousing service that is designed to handle large-scale analytics workloads.`,`msa-data-store|For example, it's not possible to join tables.`,`elasticache-strategies|Amazon ElastiCache is an in-memory key-value store that sits between your application and the data store (database) that it accesses.`,`database-decision|Relational databases support complex queries through joins.`]}),t({id:`database-registry-011`,building:`database-registry`,bullets:[`3.3-S4`],d:3,tags:[`placement-eligible`],stem:`A ride-hailing company keeps driver status on an Amazon Aurora MySQL cluster. Every access reads or updates one driver's row by driver ID. Request rates are growing toward very high levels and swing widely during events, and the single writer instance is the bottleneck. The company wants to remove the bottleneck and the capacity management with the LEAST ongoing effort. Which solution BEST meets these requirements?`,correct:[`Move the driver status data to an Amazon DynamoDB table in on-demand mode`,`Key-by-ID access fits a key-value database, and on-demand mode scales to very high request rates without capacity management.`],wrong:[[`Add more Aurora Replicas and send both reads and updates to the cluster reader endpoint`,`Aurora Replicas are read-only, and write operations are managed by the primary instance, so the writer bottleneck remains.`],[`Scale the Aurora writer to the largest available DB instance class and keep the schema`,`There is still one writer whose capacity is chosen and changed by hand, so neither the bottleneck nor the capacity work goes away.`],[`Put an Amazon ElastiCache for Memcached cluster in front of Aurora and send the updates through it`,`A cache serves repeated reads, and every update still has to reach the Aurora writer, so the write bottleneck stays.`]],slot:1,evidence:[`aurora-replication|Aurora Replicas work well for read scaling because they are fully dedicated to read operations on your cluster volume.`,`aurora-replication|Write operations are managed by the primary instance.`,`database-decision|Key-value databases can scale to large amounts of data and extremely high throughput of requests, while servicing millions of simultaneous users through distributed processing and storage.`,`dynamodb-ondemand|On-demand mode is the default and recommended throughput option because it simplifies building modern, serverless applications that can start small and scale to millions of requests per second.`]}),t({id:`database-registry-012`,building:`database-registry`,bullets:[`3.3-K6`],d:3,tags:[`placement-eligible`],stem:`A company's on-premises MySQL database holds a large device-state table that applications only read and update by device ID. The table has outgrown its server. The company wants to move it to a fully managed AWS database that needs no capacity planning, and it must keep the on-premises table in sync with the target during a two-week test before cutover. Which solution meets these requirements?`,correct:[`Use AWS DMS to migrate the table to an Amazon DynamoDB on-demand table and replicate ongoing changes during the test`,`DMS can migrate to a NoSQL target such as DynamoDB, replicates ongoing changes, and on-demand mode needs no capacity planning.`],wrong:[[`Use AWS DMS to migrate the table to Amazon RDS for MySQL on a larger DB instance class`,`The data fits a key lookup pattern, but the company would still choose and resize an instance, which is the capacity planning it wants to avoid.`],[`Export the table to CSV files and load them into a DynamoDB table once with a script before the cutover`,`A single load does not keep the target in sync with the live on-premises table during the two-week test.`],[`Use AWS DataSync to copy the MySQL data files to Amazon S3 and have the applications read them there`,`DataSync copies files, does not replicate database changes, and S3 objects cannot replace key lookups and updates.`]],slot:2,evidence:[`dms-what-is|Or it can help you move to the managed data warehouse service provided by Amazon Redshift, NoSQL platforms like Amazon DynamoDB, or low-cost storage platforms like Amazon Simple Storage Service (Amazon S3).`,`dms-what-is|You can perform one-time migrations or replicate ongoing changes to keep sources and targets in sync.`,`dynamodb-capacity|DynamoDB on-demand enables you to create a table without worrying about capacity planning, monitoring usage, and configuring scaling policies.`]}),e({id:`database-registry-013`,building:`database-registry`,bullets:[`3.3-K8`,`3.3-S4`],d:3,tags:[`placement-eligible`],stem:`A company is designing a subscription platform on AWS. Order management needs a relational model with SQL joins across customers, plans and invoices. The user-preference service reads and writes one small record per user by user ID, with traffic that is hard to predict and no need for joins. Which TWO choices BEST fit these requirements? (Choose two.)`,correct:[[`Store the order management data in an Amazon Aurora cluster`,`Structured business objects that need SQL joins fit a relational database such as Aurora.`],[`Store the user preferences in an Amazon DynamoDB table in on-demand mode`,`Lookups by user ID fit a key-value database, and on-demand mode absorbs unpredictable traffic without capacity planning.`]],wrong:[[`Store the order management data in an Amazon DynamoDB table and rebuild the joins in application code`,`NoSQL databases have different access patterns than relational ones, so the joins would be rebuilt by hand.`],[`Store the order management data in Amazon Redshift and run the order transactions there`,`Redshift is a data warehouse for large-scale analytics and not a transactional database for order processing.`],[`Store the user preferences in Amazon Aurora on one large writer instance sized for the peak`,`The writer would be sized by guesswork for traffic that is hard to predict, and it sits idle in quiet periods.`]],slots:[2,4],evidence:[`msa-data-store|Relational databases are still very popular to store structured data and business objects.`,`database-decision|Amazon DynamoDB Key-value Use for workloads such as session stores or shopping carts.`,`dynamodb-capacity|DynamoDB on-demand enables you to create a table without worrying about capacity planning, monitoring usage, and configuring scaling policies.`]}),t({id:`database-registry-014`,building:`database-registry`,bullets:[`3.3-K8`],d:2,tags:[`placement-eligible`],stem:`A company collects readings from several device models. Each model reports different attributes, new attributes appear every few weeks, and the application only fetches records by device ID. Traffic is highly variable. Which database BEST fits this workload?`,correct:[`Amazon DynamoDB, a NoSQL database that does not enforce a strict schema`,`NoSQL databases typically do not enforce a strict schema, and DynamoDB scales for key-based access under variable traffic.`],wrong:[[`Amazon Aurora MySQL-Compatible Edition with a schema change for every new attribute`,`A relational schema must be altered each time a device model adds attributes, which makes the changing data shape costly.`],[`Amazon RDS for SQL Server on a fixed DB instance class sized for the busiest day`,`It has the same fixed-schema cost, and a fixed instance class is sized by guesswork for highly variable traffic.`],[`Amazon Redshift with a table for each device model`,`Redshift is a data warehouse for analytics and not built for fetching individual records by device ID at variable rates.`]],slot:3,evidence:[`msa-data-store|One important element of NoSQL databases is that they typically don’t enforce a strict schema.`,`database-decision|Amazon DynamoDB Key-value Use for workloads such as session stores or shopping carts.`]}),t({id:`database-registry-015`,building:`database-registry`,bullets:[`3.3-S4`],d:2,tags:[`placement-eligible`],stem:`A company runs a public lookup API on a DynamoDB table. Traffic is unpredictable, with long idle periods and sudden bursts. The company wants no capacity planning and wants to pay only for the requests it makes. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`On-demand capacity mode`,`On-demand mode needs no capacity planning, accommodates bursts automatically and bills per request, so idle periods cost nothing for capacity.`],wrong:[[`Provisioned mode with read and write capacity sized for the expected peak`,`The company would have to plan capacity, and it is charged for provisioned throughput whether or not requests arrive.`],[`Provisioned mode with auto scaling and a target utilization chosen by the team`,`The company still has to choose minimum and maximum levels and a target, and scaling lags behind sudden bursts.`],[`Provisioned mode with reserved capacity purchased for the average request rate`,`It commits the company to capacity it must size in advance, and bursts above the commitment are throttled.`]],slot:0,evidence:[`dynamodb-ondemand|With pay-per-request pricing, you don’t have to worry about idle capacity because you only pay for the throughput you actually use.`,`dynamodb-capacity|DynamoDB on-demand enables you to create a table without worrying about capacity planning, monitoring usage, and configuring scaling policies.`]}),t({id:`database-registry-016`,building:`database-registry`,bullets:[`3.3-K6`],d:2,tags:[`mock-reserve`],stem:`A company is moving a production Oracle database that has views and triggers the application depends on to Amazon Aurora PostgreSQL-Compatible Edition. The source and target use different database engines, and the source must stay online and in sync until the cutover. Which solution meets these requirements?`,correct:[`Convert the schema with AWS SCT, then migrate with an AWS DMS replication instance that replicates ongoing changes`,`The engines differ, so the schema is converted first and then AWS DMS migrates the data and replicates ongoing changes to keep source and target in sync.`],wrong:[[`Run AWS DMS with a replication instance alone and apply no converted schema to the target`,`AWS DMS creates the tables and primary keys, but the views and triggers the application needs come from a converted schema, so this option leaves them missing.`],[`Convert the schema with the AWS Schema Conversion Tool and stop there`,`The tool converts source schemas, but it does not move the data or keep the source and target in sync until cutover.`],[`Create an AWS DataSync task from the Oracle database to the Aurora cluster`,`DataSync copies data between storage systems such as file servers and object stores, and databases are not among its supported locations.`]],slot:1,evidence:[`dms-what-is|Alternatively, you can download the AWS Schema Conversion Tool (AWS SCT) to your local PC to convert your source schemas.After you convert your source schemas and apply the converted code to your target database, you can use AWS DMS to migrate your data.`,`dms-what-is|AWS DMS creates the tables and associated primary keys if they don't exist on the target.`,`dms-what-is|Or you can use DMS Schema Conversion to create some or all of the target tables, indexes, views, triggers, and so on.`,`dms-what-is|You can perform one-time migrations or replicate ongoing changes to keep sources and targets in sync.`]}),t({id:`database-registry-017`,building:`database-registry`,bullets:[`3.3-S3`],d:1,tags:[`mock-reserve`,`trap:aurora-vs-rds`],stem:`A company has standardized on Amazon Aurora for its relational workloads. A new application uses standard PostgreSQL drivers and tools. Which Aurora edition BEST fits the application?`,correct:[`Amazon Aurora PostgreSQL-Compatible Edition`,`It is the Aurora engine compatible with PostgreSQL, so the existing drivers, tools and code keep working.`],wrong:[[`Amazon Aurora MySQL-Compatible Edition`,`It is compatible with MySQL rather than PostgreSQL, so the PostgreSQL drivers, tools and queries would have to change.`],[`Amazon RDS for MariaDB`,`It is an RDS engine rather than an Aurora edition, and it is a different engine from PostgreSQL.`],[`Amazon RDS for Oracle with a Multi-AZ deployment`,`It is an RDS engine rather than an Aurora edition, and the application would have to be rewritten for Oracle.`]],slot:2,evidence:[`database-decision|The Amazon Aurora engines include Amazon Aurora with PostgreSQL-Compatible Edition, Amazon Aurora MySQL-Compatible Edition, and Amazon Aurora DSQL.`,`aurora-overview|The code, tools, and applications you use today with your existing MySQL and PostgreSQL databases can be used with Aurora.`]})],o=[t({id:`edge-link-terminal-001`,building:`edge-link-terminal`,bullets:[`3.4-K1`],d:2,tags:[`placement-eligible`,`trap:cloudfront-vs-global-accelerator`],stem:`A news company serves article images from an Amazon S3 bucket and JSON article lists from an Application Load Balancer in one Region. Readers worldwide see slow page loads, and the article lists are identical for every reader for 60 seconds at a time. The company wants lower latency worldwide and LESS load on the load balancer, with the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Create an Amazon CloudFront distribution that uses the S3 bucket and the load balancer as origins`,`CloudFront caches static and dynamic content at edge locations close to readers, so repeated requests are served without reaching the load balancer.`],wrong:[[`Create an AWS Global Accelerator standard accelerator with the Application Load Balancer as the endpoint for all readers`,`Global Accelerator proxies packets to the endpoint and does not cache, so every request still reaches the load balancer and its load does not fall.`],[`Deploy the application in several more Regions and use Amazon Route 53 latency routing to send readers to the nearest one`,`This lowers distance to the application but caches nothing, so each Region carries full load, and it adds far more to operate than a distribution.`],[`Add an Amazon ElastiCache cluster in the load balancer's Region and cache the article lists in that cluster for 60 seconds`,`The cache sits in the one Region, so readers on other continents still travel the full distance and the worldwide latency requirement is not met.`]],slot:0,evidence:[`ga-faq|CloudFront improves performance for both cacheable content (such as images and videos) and dynamic content (such as API acceleration and dynamic site delivery).`,`cloudfront-what-is|If the content is already in the edge location with the lowest latency, CloudFront delivers it immediately.`,`ga-faq|Global Accelerator improves performance for a wide range of applications over TCP or UDP by proxying packets at the edge to applications running in one or more AWS Regions.`]}),t({id:`edge-link-terminal-002`,building:`edge-link-terminal`,bullets:[`3.4-K1`],d:1,tags:[`placement-eligible`,`trap:cloudfront-vs-global-accelerator`],stem:`A company runs a real-time multiplayer game whose servers receive UDP traffic on Network Load Balancers in two AWS Regions. Some players connect from networks whose firewalls allow traffic only to specific IP addresses. The company wants players sent to the closest healthy Region over the AWS network. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create an AWS Global Accelerator standard accelerator with an endpoint group for each Regional load balancer`,`The accelerator gives players static anycast IP addresses to allow-list, accepts UDP, and routes to the optimal healthy Regional endpoint.`],wrong:[[`Create an Amazon CloudFront distribution with the Network Load Balancer of each Region as a custom origin`,`CloudFront speeds up distribution of web content, so it is not the service for UDP game traffic and it adds no fixed UDP entry points.`],[`Create Amazon Route 53 latency records that point to the Network Load Balancer in each Region for the game hostname`,`DNS answers hand out each Region's own addresses, so there is no single set of fixed entry points to allow-list, and routing depends on DNS caching.`],[`Assign Elastic IP addresses to proxy instances on Amazon EC2 in each Region and let the game client choose a Region`,`Clients, not the service, would pick a Region, so there is no health-based routing to the closest healthy Region and the company runs the proxies itself.`]],slot:1,evidence:[`ga-faq|Global Accelerator is a good fit for non-HTTP use cases, such as gaming (UDP), IoT (MQTT), or Voice over IP, as well as for HTTP use cases that specifically require static IP addresses or deterministic, fast regional failover.`,`ga-listeners|Listeners support TCP and UDP protocols.`,`ga-how|The static IP addresses provided by AWS Global Accelerator serve as single fixed entry points for your clients.`]}),t({id:`edge-link-terminal-003`,building:`edge-link-terminal`,bullets:[`3.4-K4`],d:1,tags:[`trap:direct-connect-vs-vpn`],stem:`A company needs an encrypted connection between its data center and its VPC within a few days. The connection will carry moderate traffic for a pilot, and the company has no dedicated network circuit to AWS. Which solution meets these requirements with the LOWEST setup effort?`,correct:[`Create an AWS Site-to-Site VPN connection between the VPC and the customer gateway device in the data center`,`Site-to-Site VPN uses IPsec connections over the internet, so it needs no new circuit and can be set up quickly.`],wrong:[[`Order a dedicated AWS Direct Connect connection and wait for the network circuit to be installed at a Direct Connect location`,`A dedicated connection needs network circuits between a Direct Connect location and the data center, which is not possible within a few days, and it is not encrypted by default.`],[`Create an AWS PrivateLink endpoint service in the VPC and connect the data center network to that service`,`PrivateLink gives private access to a service, not a network-to-network connection between a data center and a VPC.`],[`Set up AWS Client VPN and have each administrator connect from a laptop to reach the VPC from the data center`,`Client VPN is a client-based service for individual users and does not connect the whole data center network to the VPC.`]],slot:2,evidence:[`s2s-vpn|Site-to-Site VPN supports Internet Protocol security (IPsec) VPN connections.`,`s2s-vpn|You can enable access to your remote devices from your VPC by creating an AWS Site-to-Site VPN (Site-to-Site VPN) connection, and configuring routing to pass traffic through the connection.`,`dx-encryption|AWS Direct Connect does not encrypt your traffic that is in transit by default.`]}),t({id:`edge-link-terminal-004`,building:`edge-link-terminal`,bullets:[`3.4-S3`],d:1,tags:[`placement-eligible`],stem:`A manufacturer runs control software for factory machines that must get responses from compute within a few milliseconds. The data must be processed locally in the factory, and the company wants the same APIs and tools it uses in its Region, with AWS managing the infrastructure. Which solution BEST meets these requirements?`,correct:[`Install AWS Outposts at the factory and run the control software on Amazon EC2 instances on the Outpost`,`Outposts extends AWS infrastructure, services, APIs and tools to customer premises, so compute runs locally with the same APIs and AWS manages the hardware.`],wrong:[[`Run the control software in an AWS Local Zone in the nearest large metropolitan area`,`A Local Zone is AWS-operated infrastructure near population centers, not at the factory, so the data is not processed locally on the premises.`],[`Run the control software in the nearest Region and put an Amazon CloudFront distribution in front of the factory network`,`CloudFront caches web content at edge locations and runs no control software, and the Region adds round-trip latency to every machine response.`],[`Extend the VPC into an AWS Wavelength Zone and run the control software on Amazon EC2 instances in that zone`,`Wavelength Zones are in communications service providers' networks for mobile devices, not on the factory premises.`]],slot:3,evidence:[`outposts-what-is|AWS Outposts is a fully managed service that extends AWS infrastructure, services, APIs, and tools to customer premises.`,`outposts-what-is|By providing local access to AWS managed infrastructure, AWS Outposts enables customers to build and run applications on premises using the same programming interfaces as in AWS Regions, while using local compute and storage resources for lower latency and local data processing needs.`]}),t({id:`edge-link-terminal-005`,building:`edge-link-terminal`,bullets:[`3.4-K1`],d:2,tags:[`placement-eligible`],stem:`A company serves a static website through an Amazon CloudFront distribution with an Amazon S3 origin. Each release changes the CSS and JavaScript files, and visitors must get the new files right after a release without waiting for cached copies to expire. The company wants to keep a long cache duration and avoid sending invalidation requests on every release. Which solution meets these requirements?`,correct:[`Put a version identifier in the file names and have the pages reference the new names with each release`,`New names are new objects, so CloudFront fetches them at once, while a long cache duration stays in place for the unchanged names.`],wrong:[[`Set the cache duration of every object to 0 seconds so that CloudFront checks the origin for each request`,`This gives up the long cache duration and sends far more requests to the origin, which a longer duration would otherwise reduce.`],[`Create an invalidation for the changed file paths as part of every release and keep the same file names`,`It works, but the requirement is to avoid sending invalidation requests on every release, which versioned names make unnecessary.`],[`Create a new CloudFront distribution for each release and change the DNS record to point to the newest distribution`,`It serves the new files, but it empties the cache for every release and adds a distribution and DNS change to manage each time.`]],slot:0,evidence:[`cloudfront-versioning|To update existing content that CloudFront is set up to distribute for you, we recommend that you use a version identifier in file names or in folder names.`,`cloudfront-versioning|With versioning, you don't have to wait for an object to expire before CloudFront begins to serve a new version of it`,`cloudfront-expiration|A longer duration also reduces the load on your origin.`]}),e({id:`edge-link-terminal-006`,building:`edge-link-terminal`,bullets:[`3.4-K4`],d:2,tags:[`trap:direct-connect-vs-vpn`],stem:`A company has one AWS Direct Connect connection from its data center. On-premises servers must now also reach VPCs in two Regions by private IP addresses, using only that one connection. The company does not want to order a connection for each Region. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create a Direct Connect gateway and associate the virtual private gateway of each VPC with it`,`A Direct Connect gateway can connect to any Region globally, and it is associated with a virtual private gateway for each VPC.`],[`Create a private virtual interface on the connection and attach it to the Direct Connect gateway`,`A private virtual interface is the one used to reach VPC resources by private IP addresses.`]],wrong:[[`Order a second Direct Connect connection at a location in the other Region and keep one connection per Region`,`This needs a connection for each Region, which the company wants to avoid, because a Direct Connect gateway reaches any Region.`],[`Create a public virtual interface on the connection and reach the VPC addresses through it`,`A public virtual interface reaches AWS public services by public IP addresses, not the private addresses of a VPC.`],[`Create a Site-to-Site VPN connection from the data center to each VPC over the internet`,`This does not use the existing Direct Connect connection, and it sends the traffic over the internet.`]],slots:[0,2],evidence:[`dx-gateway|You can connect to any Region globally using a Direct Connect gateway.`,`dx-gateway|You associate a Direct Connect gateway with any of the following: A Transit Gateway when you have multiple VPCs in the same Region A virtual private gateway`,`dx-what-is|A private virtual interface enables access to your VPC.`,`dx-what-is|A public virtual interface enables access to public services, such as Amazon S3.`]}),t({id:`edge-link-terminal-007`,building:`edge-link-terminal`,bullets:[`3.4-S3`],d:2,tags:[`placement-eligible`],stem:`A visual-effects studio has artists in a large metropolitan area that has no AWS Region. The artists run interactive rendering workstations on Amazon EC2 and need low-latency access to them. The studio does not want to install or manage hardware in its own buildings. Which solution BEST meets these requirements?`,correct:[`Run the workstations on Amazon EC2 instances in an AWS Local Zone in that metropolitan area`,`A Local Zone places compute close to large population centers, so artists get low latency with no hardware to install.`],wrong:[[`Install AWS Outposts racks in the studio's buildings and run the workstations on the Outposts instances`,`Outposts puts AWS infrastructure on customer premises, which means installing equipment in the studio's buildings.`],[`Extend the VPC to an AWS Wavelength Zone and run the workstations on Amazon EC2 instances in that zone`,`Wavelength Zones are in communications service providers' networks for mobile devices, not for artists in a metropolitan area.`],[`Run the workstations in the nearest Region and place an Amazon CloudFront distribution in front of them`,`CloudFront caches content at edge locations and does not run interactive workstations, so the artists still reach compute in the distant Region.`]],slot:2,evidence:[`local-zones|AWS Local Zones places compute, storage, database, and other select AWS resources close to large population and industry centers.`,`local-zones|You can use Local Zones to provide your users with low-latency access to your applications.`,`outposts-what-is|AWS Outposts is a fully managed service that extends AWS infrastructure, services, APIs, and tools to customer premises.`]}),t({id:`edge-link-terminal-008`,building:`edge-link-terminal`,bullets:[`3.4-K1`],d:3,tags:[`placement-eligible`,`trap:cloudfront-vs-global-accelerator`],stem:`A company hosts live multiplayer matches on individual Amazon EC2 instances in a VPC. Each match runs on one specific instance and port, and the matchmaking service must send the players of a match to exactly that instance and port. Players are worldwide, and the company wants their traffic to use the AWS global network. Which solution BEST meets these requirements?`,correct:[`Create a Global Accelerator custom routing accelerator and map each player to the match instance and port`,`A custom routing accelerator maps users to a specific destination among many, so each player lands on the right instance and port.`],wrong:[[`Create a Global Accelerator standard accelerator with a Network Load Balancer endpoint in front of the instances`,`A standard accelerator routes to the optimal endpoint by health, location and policy, so it cannot pick the specific instance and port of a match.`],[`Create an Amazon CloudFront distribution that has a custom origin for each match instance and port`,`CloudFront delivers web content and caches it at edge locations; it does not map each player to one specific instance and port.`],[`Create Amazon Route 53 weighted records for the instances and return one record to each player`,`Weighted DNS records spread players by weight across records, so a player is not deterministically sent to the instance and port of one match.`]],slot:3,evidence:[`ga-what-is|With a custom routing accelerator, you can map one or more users to a specific destination among many destinations.`,`ga-product|Low-latency gaming and media workloads Use custom routing to deterministically route traffic to a fleet of EC2 instances.`,`ga-how|For standard accelerators, traffic is routed to the optimal AWS endpoint based on several factors, including the user’s location, the health of the endpoint, and the endpoint weights that you configure.`]}),t({id:`edge-link-terminal-009`,building:`edge-link-terminal`,bullets:[`3.4-K4`],d:3,tags:[`trap:direct-connect-vs-vpn`],stem:`A company's branch office in Asia reaches a VPC in us-east-1 through an AWS Site-to-Site VPN connection that ends on a virtual private gateway. Traffic crosses the public internet and users see network disruptions. The company must keep IPsec VPN connectivity, must not wait for a dedicated circuit, and wants traffic to use the AWS global network as much as possible. Which solution meets these requirements?`,correct:[`Create a transit gateway, attach the VPC to it, and create a new Site-to-Site VPN attachment with acceleration enabled`,`An accelerated VPN connection routes traffic to the closest edge location over the AWS network, and acceleration is supported only for VPN attachments on a transit gateway.`],wrong:[[`Enable acceleration on the existing Site-to-Site VPN connection that ends on the virtual private gateway`,`Virtual private gateways do not support accelerated VPN connections, so the setting cannot be used on this connection.`],[`Add a second Site-to-Site VPN connection to the same virtual private gateway to get more tunnels`,`More tunnels add capacity and failover, but the traffic still crosses the public internet and the disruptions remain.`],[`Order a dedicated AWS Direct Connect connection and use it in place of the VPN`,`A dedicated connection waits for a network circuit, which the company cannot do, and it is not encrypted by default.`]],slot:0,evidence:[`vpn-accelerated|An accelerated Site-to-Site VPN connection (accelerated VPN connection) uses AWS Global Accelerator to route traffic from your on-premises network to an AWS edge location that is closest to your customer gateway device.`,`vpn-accelerated|Acceleration is only supported for Site-to-Site VPN connections that are attached to a transit gateway.`,`vpn-accelerated|Virtual private gateways do not support accelerated VPN connections.`]}),t({id:`edge-link-terminal-010`,building:`edge-link-terminal`,bullets:[`3.4-S3`],d:2,tags:[`placement-eligible`],stem:`An augmented-reality game streams scene data to players on 5G smartphones. The game servers run on Amazon EC2 and must reach the players' mobile devices with the LOWEST possible latency across a carrier network. Which solution meets these requirements?`,correct:[`Extend the VPC to a Wavelength Zone in the carrier network and run the game servers on Amazon EC2 there`,`Wavelength deploys standard AWS compute at the edge of communications service providers' networks to give low latency to mobile devices.`],wrong:[[`Run the game servers on Amazon EC2 instances in an AWS Local Zone near the largest city in the players' country`,`A Local Zone is close to population centers but is not inside the carrier network, so mobile traffic still travels farther before it reaches the servers.`],[`Install AWS Outposts servers at the players' homes and run the game servers on the Outposts instances`,`Outposts extends AWS infrastructure to customer premises, which would mean hardware at every player's home.`],[`Run the game servers in the nearest Region behind an Amazon CloudFront distribution to cache the scene data`,`CloudFront caches content at edge locations, but live game-server compute still runs in the Region, away from the carrier network.`]],slot:1,evidence:[`wavelength-what-is|AWS Wavelength enables developers to build applications that require edge computing infrastructure to deliver low latency to mobile devices and end users or increase the resiliency of their existing edge applications.`,`wavelength-what-is|Wavelength deploys standard AWS compute and storage services to the edge of communications service providers' (CSP) networks.`]}),t({id:`edge-link-terminal-011`,building:`edge-link-terminal`,bullets:[`3.4-S3`],d:2,tags:[`placement-eligible`],stem:`A company runs identical stacks of an Application Load Balancer and Amazon EC2 instances in us-east-1 and ap-southeast-1. Users in North America and Asia receive personalised responses that cannot be cached. Each user must be sent to the Region that gives that user the best latency. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create Amazon Route 53 latency routing records that point to the load balancer in each Region`,`Latency routing is meant for resources in several Regions and sends each user to the Region with the best latency.`],wrong:[[`Create Amazon Route 53 geolocation routing records that map each continent to one Region`,`Geolocation routes by the user's location, not by measured latency, so a user is not sent to the Region with the best latency.`],[`Create Amazon Route 53 weighted records that send half of all requests to each Region`,`Weighted records split traffic by proportion and ignore user latency, so many users would reach the farther Region.`],[`Create an Amazon CloudFront distribution with both load balancers as origins and cache the responses`,`The responses are personalised and cannot be cached, so caching would not work, and CloudFront would add a layer without choosing a Region by latency.`]],slot:2,evidence:[`route53-routing|Latency routing policy – Use when you have resources in multiple AWS Regions and you want to route traffic to the Region that provides the best latency.`,`route53-latency|If your application is hosted in multiple AWS Regions, you can improve performance for your users by serving their requests from the AWS Region with the lowest latency.`]}),e({id:`edge-link-terminal-012`,building:`edge-link-terminal`,bullets:[`3.4-K4`],d:3,tags:[`trap:direct-connect-vs-vpn`],stem:`A trading company's platform depends on AWS Direct Connect between its data center and a VPC. It has two dedicated connections at a single Direct Connect location, both ending on the same customer router. A failure of the router or of the location would stop trading. The company wants the HIGHEST resiliency, protecting against both failures. Which TWO actions should the company take? (Choose two.)`,correct:[[`Order dedicated connections at more than one Direct Connect location`,`Connections in more than one location keep the link up if one location fails.`],[`End the connections on separate customer routers instead of a single shared router`,`Separate connections that terminate on separate devices remove the single device as a point of failure.`]],wrong:[[`Add a third dedicated connection at the same Direct Connect location, ending on the same customer router`,`The new connection still depends on one location and one router, so either failure stops trading.`],[`Enable MAC Security on the existing dedicated connections to protect the links`,`MACsec encrypts the link at Layer 2 and does nothing to keep the connection up if the router or location fails.`],[`Raise the port speed of the existing dedicated connections to 100 Gbps`,`More capacity does not add a second router or location, so either failure still stops trading.`]],slots:[1,3],evidence:[`dx-resiliency|You can achieve maximum resiliency for critical workloads by using separate connections that terminate on separate devices in more than one location`,`dx-resiliency|Development and test: This model provides you a way to achieve development and test resiliency for non-critical workloads, by using separate connections that terminate on separate devices in one location.`,`dx-macsec|MACsec provides Layer 2 point-to-point encryption over the cross-connect to AWS`]}),e({id:`edge-link-terminal-013`,building:`edge-link-terminal`,bullets:[`3.4-K1`],d:3,tags:[`mock-reserve`],stem:`A company serves private PDF manuals from an Amazon S3 bucket through an Amazon CloudFront distribution. Viewers must always use HTTPS, and the objects must be reachable only through the distribution, never by direct S3 URLs. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Set the viewer protocol policy of the cache behavior to require HTTPS`,`The viewer protocol policy of a cache behavior can require HTTPS between viewers and CloudFront.`],[`Use an origin access identity on the S3 origin, with a bucket policy that grants read access only to that identity`,`The bucket policy gives the identity permission to read the bucket, and no one else, so direct S3 URLs are refused.`]],wrong:[[`Turn off S3 Block Public Access and add a bucket policy that allows public reads of the objects`,`Public reads make the objects reachable by direct S3 URLs, which the requirement forbids.`],[`Enable default encryption with an AWS KMS key on the S3 bucket`,`Encryption at rest neither forces viewers to use HTTPS nor stops direct access through S3 URLs.`],[`Attach an AWS WAF web ACL to the distribution with a rate-based rule`,`A rate-based rule limits request rates but does not force HTTPS or stop direct requests to the bucket.`]],slots:[0,2],evidence:[`cf-viewer-https|you change the Viewer Protocol Policy setting for one or more cache behaviors to require HTTPS communication.`,`cf-oac|When you create an OAI or add one to a distribution with the CloudFront console, you can automatically update the Amazon S3 bucket policy to give the OAI permission to access your bucket.`]}),t({id:`edge-link-terminal-014`,building:`edge-link-terminal`,bullets:[`3.4-K4`],d:2,tags:[`mock-reserve`,`trap:direct-connect-vs-vpn`],stem:`A company has two 10 Gbps dedicated AWS Direct Connect connections to the same Direct Connect endpoint and needs about 20 Gbps of throughput. The company wants to manage the two connections as one logical connection. Which solution BEST meets these requirements?`,correct:[`Create a link aggregation group and add both existing connections to it`,`A link aggregation group aggregates multiple dedicated connections at a single Direct Connect endpoint into one logical connection.`],wrong:[[`Request a hosted connection with a port speed of 20 Gbps from a Direct Connect Partner and retire the two connections`,`Hosted connections are offered only at specific port speeds, and 20 Gbps is not one of them.`],[`Create a Direct Connect gateway and attach a private virtual interface to each connection`,`A Direct Connect gateway connects virtual interfaces to VPCs, but it does not combine the two connections into one logical connection.`],[`Order a third connection at a different Direct Connect location and use the three separately`,`This adds location diversity, but the connections stay separate rather than becoming one logical connection.`]],slot:3,evidence:[`connectivity-dx|For dedicated connections, you can also use a link aggregation group (LAG) to aggregate multiple connections at a single AWS Direct Connect endpoint.`,`dx-hosted|Port speed For hosted connections, the possible values are 50 Mbps, 100 Mbps, 200 Mbps, 300 Mbps, 400 Mbps, 500 Mbps, 1 Gbps, 2 Gbps, 5 Gbps, 10 Gbps, and 25 Gbps.`]})],s=[t({id:`engine-works-001`,building:`engine-works`,bullets:[`3.2-K1`],d:1,stem:`A company stores several hundred terabytes of clickstream logs in Amazon S3. Data engineers want to run Apache Spark jobs that transform and analyze the logs on a managed cluster platform, with the LEAST effort to install and configure the framework. Which service meets these requirements?`,correct:[`Amazon EMR with a managed cluster that runs the Apache Spark framework`,`EMR is a managed cluster platform that simplifies running big data frameworks such as Apache Spark to process and analyze vast amounts of data.`],wrong:[[`AWS Batch with a job queue that runs the transformation scripts`,`Batch runs batch computing jobs and is not a managed platform for big data frameworks such as Apache Spark.`],[`AWS Lambda with one function that processes each log file`,`A function runs for a limited time per invocation, and Lambda is not a cluster platform for running Apache Spark.`],[`Amazon EC2 instances on which the engineers install Apache Spark themselves`,`The engineers would install, configure and operate the framework themselves, which the company wants to avoid.`]],slot:0,evidence:[`emr-what-is|Amazon EMR, which was previously called Amazon Elastic MapReduce, is a managed cluster platform that simplifies running big data frameworks, such as Apache Hadoop and Apache Spark, on AWS to process and analyze vast amounts of data.`,`batch-what-is|AWS Batch helps you to run batch computing workloads on the AWS Cloud.`,`lambda-quotas|Code can run for up to 15 minutes in a single invocation`]}),t({id:`engine-works-002`,building:`engine-works`,bullets:[`3.2-K1`],d:2,tags:[`placement-eligible`],stem:`A company runs nightly data-validation tasks packaged as containers. Each task runs for about three hours and can be restarted safely if it is interrupted. The company wants the MOST cost-effective option that does not require managing any Amazon EC2 instances. Which solution meets these requirements?`,correct:[`Run the tasks on Amazon ECS with AWS Fargate Spot capacity so no instances are managed`,`Fargate runs containers without servers to manage, and Fargate Spot runs interruption-tolerant tasks at a discounted rate.`],wrong:[[`Run each task as an AWS Lambda function that uses the container image and the maximum memory`,`Lambda limits how long a single invocation can run, and that limit is shorter than a three-hour task.`],[`Run the tasks on Amazon ECS with a cluster of Amazon EC2 instances that the company launches and patches`,`The company would launch, manage and patch the EC2 instances, which it wants to avoid.`],[`Run the tasks on Amazon ECS with AWS Fargate On-Demand capacity for the whole night`,`This avoids instance management but does not use the discounted rate for interruption-tolerant tasks, so it costs more than Fargate Spot.`]],slot:1,evidence:[`fargate-ecs|AWS Fargate is a technology that you can use with Amazon ECS to run containers without having to manage servers or clusters of Amazon EC2 instances.`,`fargate-ecs|Run interruption tolerant Amazon ECS tasks at a discounted rate compared to the AWS Fargate price.`,`lambda-quotas|Code can run for up to 15 minutes in a single invocation`]}),t({id:`engine-works-003`,building:`engine-works`,bullets:[`3.2-K1`],d:2,tags:[`placement-eligible`],stem:`A company must run a licensed application that installs a custom kernel module and requires its administrators to configure the operating system and the network settings of the server. The application runs continuously. Which compute option BEST meets these requirements?`,correct:[`Amazon EC2 instances that the company configures and manages itself`,`EC2 provides resizable virtual servers, and it suits cases where granular control over the compute environment is necessary.`],wrong:[[`AWS Lambda functions that run the application code on demand`,`Lambda performs all the administration of the compute resources, including operating system maintenance, so administrators cannot configure the server.`],[`Amazon ECS tasks on AWS Fargate with the application in a container image`,`Fargate runs containers without servers for the company to manage, so there is no server operating system to configure.`],[`Amazon EMR clusters with the application installed on the core nodes of each cluster`,`EMR is a managed cluster platform for big data frameworks such as Apache Hadoop and Apache Spark, not a platform for a licensed application.`]],slot:2,evidence:[`compute-decision|However, for use cases where granular control over the compute environment is necessary, the overhead is often justified.`,`compute-decision|Lambda runs your code on a high-availability compute infrastructure and performs all of the administration of the compute resources, including server and operating system maintenance, capacity provisioning and automatic scaling, and logging.`,`fargate-ecs|AWS Fargate is a technology that you can use with Amazon ECS to run containers without having to manage servers or clusters of Amazon EC2 instances.`]}),e({id:`engine-works-004`,building:`engine-works`,bullets:[`3.2-K1`],d:3,tags:[`placement-eligible`],stem:`A studio renders 5,000 frames every night. Each frame is an independent job that runs for about three hours in a container. The studio wants the jobs to queue and run automatically, wants no idle compute between nightly runs, and does not want to manage servers. Which TWO actions meet these requirements with the LEAST operational overhead? (Choose two.)`,correct:[[`Submit each frame as a job to an AWS Batch job queue`,`Batch provisions resources in response to submitted jobs and runs them, so queued jobs start automatically without idle capacity between runs.`],[`Configure the Batch compute environment to use AWS Fargate resources`,`Batch can scale compute capacity on Fargate resources, so the studio has no servers to manage.`]],wrong:[[`Invoke an AWS Lambda function for each frame`,`Lambda limits how long one invocation can run, and that limit is shorter than a three-hour job.`],[`Run a persistent Amazon EMR cluster and submit each frame as a Spark step`,`EMR is a managed platform for big data frameworks such as Hadoop and Spark, and a persistent cluster keeps compute running between nights.`],[`Keep a fleet of Amazon EC2 instances running all day and poll a queue for frames`,`The instances must be managed and keep running even when no frames are waiting, which conflicts with the requirements.`]],slots:[1,3],evidence:[`batch-what-is|This service can efficiently provision resources in response to jobs submitted in order to eliminate capacity constraints, reduce compute costs, and deliver results quickly.`,`batch-what-is|AWS Batch is able to scale compute capacity on Amazon EC2 instances, Fargate resources, and Amazon ECS Managed Instances.`,`lambda-quotas|Code can run for up to 15 minutes in a single invocation`]}),t({id:`engine-works-005`,building:`engine-works`,bullets:[`3.2-S3`],d:2,tags:[`placement-eligible`],stem:`A company transcodes video files. Each job keeps all vCPUs of its server at near 100 percent utilization for about two hours, and memory use is low. Which compute option BEST matches this profile?`,correct:[`Compute optimized Amazon EC2 instances, which have high performance processors`,`Compute optimized instances are designed for compute intensive applications such as media transcoding that benefit from high performance processors.`],wrong:[[`Burstable performance (T) Amazon EC2 instances, which earn CPU credits while idle`,`Burstable instances provide a baseline with bursts governed by CPU credits, and AWS recommends fixed performance instances for consistently high CPU such as video encoding.`],[`Memory optimized Amazon EC2 instances, which have a high memory-to-CPU ratio`,`Memory optimized instances are designed for workloads that process large data sets in memory, and this job uses little memory.`],[`AWS Lambda functions that are configured with the maximum memory setting`,`Lambda is designed for short-lived compute tasks, and an invocation has a time limit that is shorter than a two-hour job.`]],slot:3,evidence:[`ec2-co|Compute optimized instances are designed for compute intensive applications that benefit from high performance processors.`,`ec2-co|These instances are ideal for batch processing workloads, media transcoding, high performance web servers, high performance computing (HPC), scientific modeling, dedicated gaming servers, ad server engines, and machine learning inference.`,`ec2-instance-types|If you need consistently high CPU performance for applications such as video encoding, high volume websites, or HPC applications, we recommend that you use fixed performance instances.`,`lambda-quotas|Lambda is designed for short-lived compute tasks that do not retain or rely upon state between invocations.`]}),t({id:`engine-works-006`,building:`engine-works`,bullets:[`3.2-S3`],d:1,tags:[`placement-eligible`],stem:`A company runs an in-memory analytics engine on a single server. For each run the engine loads a data set of about 300 GB into memory and then processes it. Which compute option BEST meets this requirement?`,correct:[`A memory optimized Amazon EC2 instance type with a large amount of RAM`,`Memory optimized instances are designed to deliver fast performance for workloads that process large data sets in memory.`],wrong:[[`An AWS Lambda function with the memory setting at its maximum`,`A Lambda function can use at most 10,240 MB of memory, far less than the 300 GB data set.`],[`A compute optimized Amazon EC2 instance type with many fast vCPUs`,`Compute optimized instances target compute intensive work on high performance processors, not large in-memory data sets.`],[`A storage optimized Amazon EC2 instance type with large local disks`,`Storage optimized instances target high sequential access to very large data sets on local storage, not holding the data set in memory.`]],slot:0,evidence:[`ec2-mo|Memory optimized instances are designed to deliver fast performance for workloads that process large data sets in memory.`,`lambda-quotas|a single function can use up to 10,240 MB of memory`,`ec2-so|Storage optimized instances are designed for workloads that require high, sequential read and write access to very large data sets on local storage.`]}),t({id:`engine-works-007`,building:`engine-works`,bullets:[`3.2-S3`],d:1,stem:`A company runs a self-managed NoSQL database on Amazon EC2. The database needs high sequential read and write access to a very large data set on local storage and tens of thousands of low-latency random IOPS. Which EC2 instance family BEST meets these requirements?`,correct:[`Storage optimized instances`,`Storage optimized instances target high sequential access to very large local data sets and deliver tens of thousands of low-latency random IOPS.`],wrong:[[`Compute optimized instances`,`Compute optimized instances target compute intensive work on high performance processors, and local disk I/O is the limiting resource here.`],[`General purpose instances`,`General purpose instances balance compute, memory and networking and do not target high local storage I/O.`],[`Accelerated computing instances`,`Accelerated computing instances use hardware accelerators or co-processors for functions such as graphics processing, not for local disk throughput.`]],slot:1,evidence:[`ec2-so|Storage optimized instances are designed for workloads that require high, sequential read and write access to very large data sets on local storage.`,`ec2-so|They are optimized to deliver tens of thousands of low-latency, random I/O operations per second (IOPS) to applications.`,`ec2-ac|Accelerated computing instances use hardware accelerators, or co-processors, to perform functions, such as floating point number calculations, graphics processing, or data pattern matching, more efficiently than is possible in software running on CPUs.`]}),t({id:`engine-works-008`,building:`engine-works`,bullets:[`3.2-S4`],d:2,tags:[`placement-eligible`],stem:`A company has an AWS Lambda function that downloads 6 GB video files from Amazon S3 into the /tmp directory and processes them. The function fails with a no space left on device error, although its memory use is well below the configured memory. Which change will fix the error with the LEAST change to the code?`,correct:[`Increase the ephemeral storage setting of the function above 6 GB`,`The ephemeral storage setting controls the size of the /tmp directory, and more /tmp space lets a function handle larger objects downloaded from S3.`],wrong:[[`Increase the memory setting of the function to its maximum value`,`Memory is a separate setting from ephemeral storage and does not enlarge the /tmp directory that is full.`],[`Increase the timeout setting of the function to the maximum value allowed`,`The timeout limits how long an invocation can run and does not add space to the /tmp directory.`],[`Attach a larger Amazon EBS volume to the function and mount it`,`EBS volumes attach to Amazon EC2 instances, not to Lambda functions.`]],slot:2,evidence:[`lambda-ephemeral|You can control the amount of ephemeral storage allocated to your function using the Ephemeral storage setting.`,`lambda-ephemeral|You can configure ephemeral storage between 512 MB and 10,240 MB, in 1-MB increments.`,`lambda-ephemeral|For workloads that download objects from Amazon S3 in response to S3 events, more /tmp space makes it possible to handle larger objects without using in-memory processing.`,`ebs-what-is|Amazon EBS volumes — These are storage volumes that you attach to Amazon EC2 instances.`]}),t({id:`engine-works-009`,building:`engine-works`,bullets:[`3.2-S4`],d:3,tags:[`placement-eligible`],stem:`A company runs a CPU-bound AWS Lambda function that uses the arm64 architecture. The team does not know which memory setting gives the best performance and wants a measured result from the real function across several memory values, not a guess. Which approach is the BEST fit?`,correct:[`Run the open-source AWS Lambda Power Tuning tool against the function at several memory settings`,`The tool runs concurrent versions of the function at different memory allocations and measures their performance with live calls.`],wrong:[[`Accept the memory recommendation that AWS Compute Optimizer shows for the function in the Lambda console`,`Compute Optimizer supports only functions that use the x86_64 architecture, so it has no memory recommendation for an arm64 function.`],[`Set the memory of the function to the 128 MB default because lower memory always costs less`,`The 128 MB default is recommended only for simple functions, and a CPU-bound function gets proportionally less CPU at low memory.`],[`Set the memory of the function to the 10,240 MB maximum and keep it there for every run`,`The maximum gives the most CPU but is not a measured result, and it may commit far more memory than the function needs.`]],slot:3,evidence:[`lambda-memory|You can also consider using the open source AWS Lambda Power Tuning tool. This tool uses AWS Step Functions to run multiple concurrent versions of a Lambda function at different memory allocations and measure the performance.`,`lambda-memory|Compute Optimizer supports only functions that use x86_64 architecture.`,`lambda-memory|We recommend that you only use 128 MB for simple Lambda functions, such as those that transform and route events to other AWS services.`]}),e({id:`engine-works-010`,building:`engine-works`,bullets:[`3.2-S3`,`3.2-S4`],d:3,tags:[`placement-eligible`],stem:`A company runs a CPU-intensive AWS Lambda function that encodes video clips. All of the function's dependencies are available for the arm64 architecture. The company wants faster encoding with the LEAST change to the application. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Change the instruction set architecture of the function to arm64`,`Functions on arm64 (AWS Graviton2) can achieve significantly better price and performance than the same function on x86_64, and AWS suggests arm64 for compute-intensive work such as video encoding.`],[`Increase the memory setting of the function`,`Lambda allocates CPU power in proportion to the memory configured, so more memory gives a CPU-bound function more computational power.`]],wrong:[[`Increase the timeout of the function to the maximum value`,`A timeout limits how long an invocation may run and does not give a CPU-bound function more compute power.`],[`Configure reserved concurrency for the function`,`Reserved concurrency sets the number of concurrent executions and does not change the CPU power of each execution.`],[`Move the function code into a container that runs on an Amazon EC2 instance`,`This replaces the serverless function with a server to manage and changes the application, which is more than the minimal change wanted.`]],slots:[0,2],evidence:[`lambda-arch|Lambda functions that use arm64 architecture (AWS Graviton2 processor) can achieve significantly better price and performance than the equivalent function running on x86_64 architecture.`,`lambda-arch|Consider using arm64 for compute-intensive applications such as high-performance computing, video encoding, and simulation workloads.`,`lambda-memory|Adding more memory proportionally increases the amount of CPU, increasing the overall computational power available.`]}),t({id:`engine-works-011`,building:`engine-works`,bullets:[`3.2-S4`],d:2,stem:`A company runs several Amazon EC2 instances that were sized by guesswork. The company wants rightsizing recommendations that are based on the utilization history of the instances, with the LEAST effort. Which solution meets these requirements?`,correct:[`Opt in to AWS Compute Optimizer and review its recommendations for the instances`,`Compute Optimizer analyzes configuration and utilization metrics and provides rightsizing recommendations for Amazon EC2 instances.`],wrong:[[`Move every instance to the largest instance type in its current family`,`This is not based on utilization, and it can leave resources oversized instead of rightsized.`],[`Change every instance to a burstable performance (T) instance type`,`Burstable instances suit workloads with a modest baseline, so a blanket change ignores each workload's actual utilization.`],[`Read the instance type pages in the documentation and pick a new type for each instance`,`This is a manual comparison that uses no utilization metrics, so it takes more effort and gives no measured recommendation.`]],slot:0,evidence:[`compute-optimizer|AWS Compute Optimizer is a service that analyzes your AWS resources' configuration and utilization metrics to provide you with rightsizing recommendations and identify idle resources.`,`ec2-resize|If you want a recommendation for an instance type that is best able to handle your existing workload, you can use AWS Compute Optimizer.`]}),t({id:`engine-works-012`,building:`engine-works`,bullets:[`3.2-K1`],d:2,tags:[`mock-reserve`],stem:`A data team runs Apache Spark jobs on data in Amazon S3 a few times a week. The team wants no clusters to configure, secure or operate, and wants the resources for each job to be obtained automatically and released when the job finishes. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Amazon EMR Serverless with an application that uses the Apache Spark runtime for the jobs`,`EMR Serverless runs Spark without clusters to operate and automatically gets the resources a job needs and releases them when the job finishes.`],wrong:[[`A long-running Amazon EMR cluster on Amazon EC2 instances that stays up between the jobs`,`The team would configure and operate the cluster, and it keeps running between the weekly jobs.`],[`An Amazon EC2 Auto Scaling group of instances with Apache Spark installed by the team`,`The team would install and operate the framework and the instances, which it wants to avoid.`],[`AWS Lambda functions that run the jobs one object at a time`,`Lambda runs short-lived functions rather than Apache Spark jobs, so the team would have to rewrite the jobs.`]],slot:1,evidence:[`emr-serverless|With EMR Serverless, you don't have to configure, optimize, secure, or operate clusters to run applications with these frameworks.`,`emr-serverless|EMR Serverless automatically determines the resources that the application needs, gets these resources to process your jobs, and releases the resources when the jobs finish.`]}),e({id:`engine-works-013`,building:`engine-works`,bullets:[`3.2-S3`],d:2,tags:[`mock-reserve`],stem:`A company is choosing Amazon EC2 instance types for five workloads. The company wants to use burstable performance (T) instances only where they suit the workload. Which TWO workloads are the MOST suitable for burstable performance instances? (Choose two.)`,correct:[[`A development and test environment that is mostly idle`,`The baseline of burstable instances is designed for general purpose workloads such as development and test environments.`],[`A small web server with modest average CPU use`,`The baseline of burstable instances is designed for general purpose workloads such as web servers.`]],wrong:[[`A video encoding service that keeps all vCPUs busy for hours`,`AWS recommends fixed performance instances for consistently high CPU such as video encoding.`],[`A high-performance computing job that runs on all vCPUs for days`,`AWS recommends fixed performance instances for consistently high CPU such as HPC applications.`],[`A high volume website that stays near full CPU utilization all day`,`AWS recommends fixed performance instances for consistently high CPU such as high volume websites.`]],slots:[0,4],evidence:[`ec2-instance-types|The baseline CPU is designed to meet the needs of the majority of general purpose workloads, such as large-scale micro-services, web servers, small and medium databases, data logging, code repositories, virtual desktops, and development and test environments.`,`ec2-instance-types|If you need consistently high CPU performance for applications such as video encoding, high volume websites, or HPC applications, we recommend that you use fixed performance instances.`]})],c=[t({id:`express-interchange-001`,building:`express-interchange`,bullets:[`3.4-K3`],d:1,tags:[`trap:alb-nlb-gwlb`],stem:`A company runs a website on Amazon EC2 instances behind a load balancer. Requests that arrive on port 80 must be redirected to the HTTPS address of the same page by the load balancer itself, without changing the application code. Which solution BEST meets this requirement?`,correct:[`An Application Load Balancer with a port 80 listener whose rule redirects the request to HTTPS`,`An Application Load Balancer supports redirecting requests from one URL to another, so the redirect happens at the load balancer.`],wrong:[[`A Network Load Balancer with a TCP listener on port 80 that forwards the connections to the instances`,`A Network Load Balancer works at the fourth layer, so it forwards connections and cannot issue an HTTP redirect.`],[`A Gateway Load Balancer with a target group of virtual appliances for the port 80 traffic`,`A Gateway Load Balancer works at the third layer to insert appliances and cannot issue an HTTP redirect.`],[`An Amazon Route 53 simple record that returns the address of the HTTPS site for the domain name`,`DNS answers name lookups and never rewrites an HTTP request, so clients that use port 80 are not redirected.`]],slot:0,evidence:[`alb-intro|Support for redirecting requests from one URL to another.`,`nlb-intro|A Network Load Balancer functions at the fourth layer of the Open Systems Interconnection (OSI) model.`,`gwlb-intro|A Gateway Load Balancer operates at the third layer of the Open Systems Interconnection (OSI) model, the network layer.`]}),t({id:`express-interchange-002`,building:`express-interchange`,bullets:[`3.4-K3`],d:2,tags:[`trap:alb-nlb-gwlb`],stem:`A software-as-a-service company serves www.example.com and api.example.com from the same Amazon EC2 fleet, using two target groups. The company wants a single load balancer that routes by the host name in each request and works with an AWS WAF web ACL to block malicious requests. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`An Application Load Balancer with host-based listener rules and an AWS WAF web ACL attached`,`Host conditions forward requests by the host field in the HTTP header to the right target group, and AWS WAF works with an Application Load Balancer.`],wrong:[[`A Network Load Balancer with a TCP listener that forwards traffic to both of the target groups`,`A Network Load Balancer works at the fourth layer and cannot choose a target group from the host field of the HTTP header.`],[`Two Application Load Balancers, one for each host name, each with its own web ACL attached`,`This routes correctly but uses two load balancers, while the requirement is a single load balancer that routes by host name.`],[`A Gateway Load Balancer that sends all traffic to a fleet of virtual firewall appliances`,`A Gateway Load Balancer works at the third layer to deploy virtual appliances and does not route by host name.`]],slot:1,evidence:[`alb-intro|You can configure rules for your listener that forward requests based on the host field in the HTTP header.`,`elb-what-is|AWS WAF — You can use AWS WAF with your Application Load Balancer to allow or block requests based on the rules in a web access control list (web ACL).`,`gwlb-intro|A Gateway Load Balancer operates at the third layer of the Open Systems Interconnection (OSI) model, the network layer.`]}),t({id:`express-interchange-003`,building:`express-interchange`,bullets:[`3.4-K3`],d:2,stem:`A company runs internal microservices on Amazon EC2 instances that talk to each other over gRPC. The company wants an internal load balancer that understands the requests and routes them to different target groups by path, and the targets must receive the requests as gRPC. Which solution meets these requirements?`,correct:[`An Application Load Balancer with path-based rules and target groups whose protocol version is set to gRPC`,`An Application Load Balancer routes by the content of the request, and the protocol version of a target group sends requests to targets as gRPC.`],wrong:[[`An Application Load Balancer with path-based rules and target groups that keep the default protocol version`,`By default an Application Load Balancer sends requests to targets using HTTP/1.1, so the targets would not receive gRPC.`],[`A Network Load Balancer with a TCP listener and a target group for each microservice`,`A Network Load Balancer works at the fourth layer, so it cannot route the requests to different target groups by path.`],[`A Gateway Load Balancer with a target group of virtual appliances for each microservice`,`A Gateway Load Balancer works at the third layer to insert appliances and does not route requests by path.`]],slot:2,evidence:[`alb-target-groups|By default, Application Load Balancers send requests to targets using HTTP/1.1.`,`alb-target-groups|You can use the protocol version to send requests to targets using HTTP/2 or gRPC.`,`alb-intro|This enables you to structure your application as smaller services, and route requests to the correct service based on the content of the URL.`]}),e({id:`express-interchange-004`,building:`express-interchange`,bullets:[`3.4-K3`,`3.4-S4`],d:2,tags:[`trap:alb-nlb-gwlb`],stem:`A company is choosing between an Application Load Balancer and a Network Load Balancer for a microservices platform. Which TWO requirements point to the Application Load Balancer? (Choose two.)`,correct:[[`The load balancer must forward requests to different target groups based on the URL path`,`Path conditions let an Application Load Balancer route requests to the correct service based on the content of the URL.`],[`The load balancer must authenticate users through their corporate identities before routing requests`,`User authentication before routing is listed as an Application Load Balancer capability.`]],wrong:[[`Each Availability Zone's load balancer node must have a static IP address that partners can allow-list`,`Static IP addresses for the load balancer are a Network Load Balancer capability.`],[`The load balancer must transparently insert a fleet of firewall appliances into the traffic path`,`Deploying and scaling virtual appliances behind a transparent gateway is the job of a Gateway Load Balancer.`],[`The listener must accept UDP traffic from clients`,`The listeners of an Application Load Balancer are HTTP, HTTPS and gRPC, while UDP listeners belong to the Network Load Balancer.`]],slots:[1,3],evidence:[`alb-intro|This enables you to structure your application as smaller services, and route requests to the correct service based on the content of the URL.`,`alb-intro|Support for the load balancer to authenticate users of your applications through their corporate or social identities before routing requests.`,`nlb-intro|Support for static IP addresses for the load balancer.`,`elb-features|Protocol listeners HTTP, HTTPS, gRPC TCP, UDP, TLS IP TCP, SSL/TLS, HTTP, HTTPS`]}),t({id:`express-interchange-005`,building:`express-interchange`,bullets:[`3.4-S4`],d:1,tags:[`trap:alb-nlb-gwlb`],stem:`A trading partner's firewall accepts traffic only from fixed IP addresses. A company hosts a TCP-based API on Amazon EC2 instances in two Availability Zones and must give the partner fixed load balancer addresses, with extreme performance. Which load balancer BEST meets these requirements?`,correct:[`A Network Load Balancer with one Elastic IP address associated with each enabled subnet`,`AWS recommends a Network Load Balancer when extreme performance and static IP are needed, and an internet-facing one can use one Elastic IP address per subnet.`],wrong:[[`An Application Load Balancer with host-based rules, using its DNS name in the partner's firewall`,`This fails the fixed-address requirement: the partner would have to rely on a DNS name, and AWS points to a Network Load Balancer, not an Application Load Balancer, when static IP is needed.`],[`A Gateway Load Balancer in front of a fleet of virtual appliances for the partner traffic`,`A Gateway Load Balancer is for deploying virtual appliances such as firewalls and does not serve an API directly.`],[`A Classic Load Balancer, because it supports TCP listeners for the API traffic`,`This fails the fixed-address and extreme-performance requirements: AWS names the Network Load Balancer, not the Classic Load Balancer, for static IP with extreme performance.`]],slot:3,evidence:[`elb-features|If extreme performance and static IP is needed for your application, we recommend that you use a Network Load Balancer.`,`nlb-intro|When you create an Internet-facing load balancer, you can optionally associate one Elastic IP address per subnet.`,`elb-features|If you need flexible application management, we recommend that you use an Application Load Balancer.`]}),e({id:`express-interchange-006`,building:`express-interchange`,bullets:[`3.4-S4`],d:3,tags:[`trap:alb-nlb-gwlb`],stem:`A company must inspect all traffic that enters its application VPC with a fleet of third-party firewall virtual appliances that scale with demand, and the application servers must stay unaware of the appliances. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Deploy a Gateway Load Balancer in the appliances' VPC and register the appliances in its target group`,`A Gateway Load Balancer deploys, scales and manages virtual appliances such as firewalls, and its appliances are registered in a target group.`],[`Create a Gateway Load Balancer endpoint in its own subnet of the application VPC and make it the next hop in the application subnet's route table`,`The endpoint gives private connectivity to the appliances, and route tables send traffic through it without changing the application servers.`]],wrong:[[`Place a Network Load Balancer in front of the appliances and register the application servers as its targets`,`A Network Load Balancer works at the fourth layer for client traffic and is not the transparent gateway for inserting appliances inline.`],[`Attach an AWS WAF web ACL to an Application Load Balancer and treat it as the firewall fleet`,`A web ACL filters web requests; it does not deploy and scale third-party firewall virtual appliances.`],[`Create a VPC peering connection to the appliances' VPC and route the application traffic across it`,`Peering offers no load distribution across appliances, and no flow stickiness or scaling of the appliance fleet.`]],slots:[0,4],evidence:[`gwlb-intro|Gateway Load Balancers enable you to deploy, scale, and manage virtual appliances, such as firewalls, intrusion detection and prevention systems, and deep packet inspection systems.`,`gwlb-intro|This enables you to configure the Gateway Load Balancer endpoint as the next hop in the route table for the application subnet.`,`gwlb-intro|You register the virtual appliances with a target group for the Gateway Load Balancer.`]}),t({id:`express-interchange-007`,building:`express-interchange`,bullets:[`3.4-S4`],d:3,tags:[`trap:alb-nlb-gwlb`],stem:`A company's service runs behind an Application Load Balancer whose listener rules the company wants to keep. The company must also make the service privately available to customers in other AWS accounts through AWS PrivateLink. Which solution meets these requirements?`,correct:[`Create a Network Load Balancer that targets the Application Load Balancer, and publish it as an endpoint service`,`An endpoint service requires a Network Load Balancer or Gateway Load Balancer, and a Network Load Balancer can register an Application Load Balancer as a target.`],wrong:[[`Create an endpoint service that uses the existing Application Load Balancer directly as its front end for consumers`,`Endpoint services require either a Network Load Balancer or a Gateway Load Balancer, not an Application Load Balancer.`],[`Replace the Application Load Balancer with a Gateway Load Balancer that targets the application instances`,`A Gateway Load Balancer is built for virtual appliances, and replacing the Application Load Balancer would lose its listener rules.`],[`Peer the service VPC with each customer VPC and keep the Application Load Balancer internal`,`Peering exposes the VPC networks rather than providing the PrivateLink access that was asked for, and peering needs non-overlapping CIDR blocks.`]],slot:0,evidence:[`privatelink-service|Endpoint services require either a Network Load Balancer or a Gateway Load Balancer.`,`nlb-intro|For example, you can register instance IDs, IP addresses, or an Application Load Balancer.`]}),t({id:`express-interchange-008`,building:`express-interchange`,bullets:[`3.4-S4`,`3.4-K3`],d:2,tags:[`trap:alb-nlb-gwlb`],stem:`A company runs its business logic in AWS Lambda functions and wants a single load balancer in front of them that sends /v1 requests to one function and /v2 requests to another. Which load balancer BEST meets this requirement?`,correct:[`An Application Load Balancer with path-based rules and a Lambda target group for each function`,`Application Load Balancers can register Lambda functions as targets and route by the content of the URL.`],wrong:[[`A Network Load Balancer with a TCP listener and a target group for each function`,`Network Load Balancer target types are instance, IP and Application Load Balancer, not Lambda functions, and it cannot route by URL.`],[`A Gateway Load Balancer with a target group of function instances for each version path`,`A Gateway Load Balancer targets virtual appliance instances at the third layer and cannot route by URL path.`],[`A Classic Load Balancer with one listener that forwards all requests to the functions`,`Registering Lambda functions as targets is a benefit of the Application Load Balancer over the Classic Load Balancer.`]],slot:1,evidence:[`alb-intro|Support for registering Lambda functions as targets.`,`elb-features|Target type IP, Instance, Lambda IP, Instance, Application Load Balancer IP, Instance -`,`alb-intro|You can configure listener rules to route requests to different target groups based on the content of the application traffic.`]}),t({id:`express-interchange-009`,building:`express-interchange`,bullets:[`3.4-K3`],d:2,tags:[`mock-reserve`],stem:`A company enabled three Availability Zones on a Network Load Balancer, but its target group has registered targets in only two of them. Clients that connect through the zone without targets fail. What should the architect do to MOST improve fault tolerance?`,correct:[`Register at least one target in each enabled Availability Zone for the target group`,`To increase fault tolerance, each enabled zone should have at least one target in the target group.`],wrong:[[`Switch to an Application Load Balancer so that the client DNS handling no longer matters`,`This changes the load balancer type and the supported protocols without addressing the zone that has no targets.`],[`Increase the health check interval of the target group so that checks run less often`,`The interval changes how often targets are checked, but the zone still has no target to receive traffic.`],[`Reduce the load balancer to a single Availability Zone so that every client uses one address`,`A single zone removes the fault tolerance that multiple Availability Zones provide.`]],slot:2,evidence:[`nlb-intro|To increase the fault tolerance of your applications, you can enable multiple Availability Zones for your load balancer and ensure that each target group has at least one target in each enabled Availability Zone.`,`nlb-intro|You can configure health checks on a per target group basis.`]})],l=[t({id:`express-rail-hub-001`,building:`express-rail-hub`,bullets:[`3.2-K3`],d:1,tags:[`trap:sqs-sns-eventbridge-kinesis`],stem:`The operations, security and on-call teams must each be told within seconds when a critical Amazon CloudWatch alarm fires. Notifications must reach email addresses and mobile phones by text message, and the teams do not want to poll for them. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Publish the alarm notifications to an Amazon SNS topic with email and phone subscribers`,`SNS pushes a message to every subscriber, including email and text message endpoints, so nobody has to poll.`],wrong:[[`Send the alarm notifications to an Amazon SQS queue that each team polls for new messages`,`A queue uses a polling model, so every team must check for messages instead of being notified.`],[`Write the alarm notifications to an Amazon Kinesis data stream that each team reads`,`Readers of a stream are applications that pull records, and a stream has no email or text message endpoints.`],[`Run a scheduled AWS Lambda function that checks the alarm states every minute and logs them`,`This polls on a timer, adds custom code and delivers nothing to email addresses or phones.`]],slot:1,evidence:[`sns-sqs-fanout|Amazon SNS lets applications send time-critical messages to multiple subscribers through a “push” mechanism.`,`sns-sqs-fanout|This removes the need to check or “poll” for updates.`,`sns-what-is|Subscribers to an SNS topic can receive messages through different endpoints, depending on their use case, such as: Amazon SQS Lambda HTTP(S) endpoints Email Mobile push notifications Mobile text messages (SMS)`]}),t({id:`express-rail-hub-002`,building:`express-rail-hub`,bullets:[`3.2-K3`],d:2,tags:[`trap:sqs-sns-eventbridge-kinesis`],stem:`A thumbnail service takes image jobs from a queue. Each job is idempotent, the order of jobs does not matter, and an occasional duplicate job is harmless. The company expects a very high message rate and wants the queue type with the HIGHEST throughput and the LEAST complexity. Which solution meets these requirements?`,correct:[`An Amazon SQS standard queue that the workers poll for jobs`,`Standard queues support a nearly unlimited number of API calls per second and suit work that can tolerate duplicates or reordering.`],wrong:[[`An Amazon SQS FIFO queue in which all messages share one message group ID`,`Strict ordering is designed for workloads where order is critical or duplicates cannot be tolerated, which this one does not need.`],[`An Amazon SNS topic with an HTTPS endpoint on each worker instance as a subscriber`,`A topic pushes messages and holds no backlog, so jobs are missed when workers are busy or offline.`],[`An Amazon MQ message broker that the workers connect to`,`Amazon MQ lets existing brokers migrate without rewriting code, but it adds a broker to manage, where a queue service does not.`]],slot:2,evidence:[`sqs-standard|Amazon SQS provides standard queues as the default queue type, supporting a nearly unlimited number of API calls per second for actions like SendMessage, ReceiveMessage, and DeleteMessage.`,`sqs-standard|Standard message queues are suitable for various scenarios, as long as your application can handle messages that might arrive more than once or out of order.`,`sqs-fifo|FIFO (First-In-First-Out) queues have all the capabilities of the standard queues, but are designed to enhance messaging between applications when the order of operations and events is critical, or where duplicates can't be tolerated.`]}),e({id:`express-rail-hub-003`,building:`express-rail-hub`,bullets:[`3.2-K3`],d:2,stem:`An order service sends account updates to a worker fleet through a queue. The updates for one customer must be processed in the order they were sent, but updates for different customers can be processed at the same time by many workers. The company wants no ordering code in the workers. Which TWO actions meet these requirements with the LEAST effort? (Choose two.)`,correct:[[`Use an Amazon SQS FIFO queue as the queue between the service and the workers`,`FIFO queues are designed for workloads where the order of operations and events is critical.`],[`Set the message group ID of each message to the customer ID`,`FIFO queues support multiple ordered message groups within a single queue, so each customer keeps its order while different customers proceed in parallel.`]],wrong:[[`Use an Amazon SQS standard queue and have each worker sort the updates by a sequence number`,`A standard queue can deliver messages out of order, and the sorting would be ordering code in the workers.`],[`Send every message to a FIFO queue with one fixed message group ID`,`All customers would share one ordered group, so updates for different customers could not be processed at the same time.`],[`Publish the updates to an Amazon SNS standard topic with an HTTPS endpoint on every worker`,`A standard topic gives no ordering guarantee, and it holds no backlog for busy or offline workers.`]],slots:[0,3],evidence:[`sqs-fifo|Additionally, FIFO queues support message groups that allow multiple ordered message groups within a single queue.`,`sqs-fifo|FIFO (First-In-First-Out) queues have all the capabilities of the standard queues, but are designed to enhance messaging between applications when the order of operations and events is critical, or where duplicates can't be tolerated.`]}),t({id:`express-rail-hub-004`,building:`express-rail-hub`,bullets:[`3.2-K3`,`3.2-S1`],d:3,tags:[`trap:sqs-sns-eventbridge-kinesis`],stem:`A photo platform publishes one event for every upload. A thumbnail fleet and a moderation fleet, each in its own Auto Scaling group, must both process every event. The moderation fleet is slower and scales on its own backlog, and neither fleet may lose events during upload surges or when its instances are scaled in. Which solution BEST meets these requirements?`,correct:[`Publish each event to an Amazon SNS topic and subscribe a separate Amazon SQS queue for each fleet`,`The topic copies every event to both queues, and each queue buffers events so its own fleet can scale on its own backlog.`],wrong:[[`Publish each event to one Amazon SQS queue that both fleets poll`,`A queue is typically processed by a single subscriber, so the two fleets would split the events instead of each receiving all of them.`],[`Publish each event to an Amazon SNS topic and subscribe both fleets through HTTPS endpoints on their instances`,`Nothing holds the events when instances are busy or scaled in, so they can be lost and neither fleet has a backlog to scale on.`],[`Publish each event to one Amazon SQS FIFO queue and let each fleet use its own message group`,`Message groups order messages within one queue, and each message is still delivered to only one consumer.`]],slot:3,evidence:[`sns-sqs-fanout|When you use Amazon SNS and Amazon SQS together, messages reach applications that need instant notification of an event.`,`sns-sqs-fanout|The messages also persist in an Amazon SQS queue for other applications to process later.`,`sqs-what-is|It processes messages through a single subscriber typically, ideal for workflows where order and loss prevention are critical.`,`sqs-what-is|To prevent message loss when subscribers are offline, integrating Amazon SNS with Amazon SQS queue messages ensures consistent delivery.`]}),t({id:`express-rail-hub-005`,building:`express-rail-hub`,bullets:[`3.2-S1`],d:1,stem:`A web API accepts video transcode jobs and hands them to a worker fleet on Amazon EC2. A job must not be lost if a worker instance fails, or even if an entire Availability Zone fails, before the job is processed. The company does not want to manage storage. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Have the API send each job as a message to an Amazon SQS queue that the workers poll`,`SQS stores each message redundantly in multiple Availability Zones before acknowledging it.`],wrong:[[`Keep the pending jobs in a list in the memory of the API instances for the workers to fetch`,`Memory is lost when an instance fails, so the queued jobs disappear with it.`],[`Write each job to the instance store volume of a worker instance for that worker to process`,`Instance store data does not survive the loss of the instance, so unprocessed jobs would be lost.`],[`Write each job as a file on an Amazon EBS volume in one Availability Zone that the workers read`,`A volume lives in one Availability Zone, so a zone failure makes the pending jobs inaccessible, and the company must manage it.`]],slot:0,evidence:[`sqs-standard|When you send a message using SendMessage, Amazon SQS redundantly stores the message in multiple availability zones (AZs) before acknowledging it.`,`sqs-standard|This redundancy ensures that no single computer, network, or AZ failure can render the messages inaccessible.`]}),t({id:`express-rail-hub-006`,building:`express-rail-hub`,bullets:[`3.2-S1`],d:3,stem:`Worker instances in an Amazon EC2 Auto Scaling group each process one message from an Amazon SQS queue at a time, and a job can run for about 40 minutes. When the queue drains, the group scales in and terminates workers in the middle of jobs, so the work is repeated. The company wants scaling in to continue but wants to avoid ending a worker that is busy, with the LEAST change to the design. Which solution meets these requirements?`,correct:[`Have each worker enable instance scale-in protection while it processes a job`,`Scale-in protection gives control over which queue workers are terminated, so busy workers are kept.`],wrong:[[`Raise the visibility timeout of the queue to the length of the longest job`,`The message would stay hidden, but the terminated worker would still lose its job and the work would be repeated later.`],[`Replace the scaling policy with scheduled actions that remove workers at the end of each day`,`Scheduled actions can still terminate a worker that is busy at the scheduled time.`],[`Set the minimum size of the group equal to its maximum size`,`The group would stop scaling in at all, so idle workers keep running and the cost stays high.`]],slot:1,evidence:[`asg-sqs|For applications where long running tasks are performed, you can optionally use instance scale-in protection to have control over which queue workers are terminated when your Auto Scaling group scales in.`,`asg-sqs|Messages that have not been processed at the time an instance is terminated are returned to the SQS queue where they can be processed by another instance that is still running.`]}),t({id:`express-rail-hub-007`,building:`express-rail-hub`,bullets:[`3.2-S1`,`3.2-K3`],d:2,stem:`Order workers read from an Amazon SQS queue. Some messages fail only because a downstream service is briefly unavailable, and other messages are malformed and can never succeed. The company wants the malformed messages set aside for engineers, and the temporary failures retried several times first. Which solution BEST meets these requirements?`,correct:[`Add a dead-letter queue with a maxReceiveCount that allows several retries`,`Messages that are not processed successfully move to the dead-letter queue after enough receives to cover temporary failures.`],wrong:[[`Configure a dead-letter queue with a redrive policy whose maxReceiveCount is 1`,`A single failed receive would move a message that failed only temporarily, so it would not be retried.`],[`Have the workers delete a message when processing fails so that it is not received again`,`Deleting removes the failed messages, so engineers cannot examine them and temporary failures are not retried.`],[`Leave the queue unchanged so that failed messages keep returning until they succeed`,`Malformed messages would be received again and again, and nothing isolates them for debugging.`]],slot:2,evidence:[`sqs-dlq|Amazon SQS supports dead-letter queues (DLQs), which source queues can target for messages that are not processed successfully.`,`sqs-dlq|To ensure that your system is resilient against errors, set the maxReceiveCount high enough to allow for sufficient retries.`,`sqs-dlq|For example, if the maxReceiveCount is set to a low value such as 1, one failure to receive a message would cause the message to move to the dead-letter queue.`]}),t({id:`express-rail-hub-008`,building:`express-rail-hub`,bullets:[`3.2-S1`],d:2,stem:`During flash sales, a checkout API writes every order straight to a relational database that is sized for average load. Bursts exhaust database connections and orders fail. Customers can be told their order is received before it is fully processed, and the company wants order processing to scale separately from the API. Which solution BEST meets these requirements?`,correct:[`Have the API put each order on an Amazon SQS queue and let a consumer fleet write to the database at its own pace`,`The queue absorbs spikes and decouples the API from the processing tier, which can then scale on its own.`],wrong:[[`Resize the database instance permanently to the size needed for the highest burst`,`The API stays directly coupled to the database, and capacity for the burst is paid for around the clock.`],[`Add more API instances so that more orders are written to the database at once`,`More writers send even more simultaneous connections to the same database, which makes the overload worse.`],[`Have the API publish each order to an Amazon SNS topic that pushes it to an HTTPS endpoint of the database writer`,`A topic pushes messages as they arrive and does not buffer a burst for a writer that is overloaded.`]],slot:3,evidence:[`sqs-what-is|Scalability – Amazon SQS can process each buffered request independently, scaling transparently to handle any load increases or spikes without any provisioning instructions.`,`sns-sqs-fanout|It decouples sending and receiving components—without requiring each component to be available at the same time.`]}),t({id:`express-rail-hub-009`,building:`express-rail-hub`,bullets:[`3.2-K3`],d:2,tags:[`mock-reserve`,`trap:sqs-sns-eventbridge-kinesis`],stem:`When a purchase is completed, a notification service must be told instantly, and a nightly billing job must also process the same purchase later, in batches. The nightly job must not miss purchases that happen while it is not running. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Publish each purchase to an Amazon SNS topic with the notification endpoint and an Amazon SQS queue for billing`,`The topic pushes to the notification endpoint at once and also sends each message to a queue where it persists for later processing.`],wrong:[[`Publish each purchase to an Amazon SNS topic and subscribe both the notification endpoint and the billing job as endpoints`,`The billing job would miss purchases that arrive while it is offline, because the topic holds no backlog.`],[`Send each purchase to one Amazon SQS queue that both the notification service and the billing job poll`,`The two consumers would split the messages, and the notification would depend on polling rather than an instant push.`],[`Send each purchase to the notification service and have it forward the data to the billing job`,`This couples the services together, and the billing job still needs a place where messages wait until it runs.`]],slot:0,evidence:[`sns-sqs-fanout|When you use Amazon SNS and Amazon SQS together, messages reach applications that need instant notification of an event.`,`sns-sqs-fanout|The messages also persist in an Amazon SQS queue for other applications to process later.`]}),e({id:`express-rail-hub-010`,building:`express-rail-hub`,bullets:[`3.2-S1`,`3.2-K3`],d:3,tags:[`mock-reserve`],stem:`A document pipeline has three stages on Amazon EC2: extract, enrich and index. The enrich stage is the slowest, and when it falls behind, the extract stage overloads it because the stages call each other directly. The company wants each stage to scale independently and wants a slow stage to stop affecting the others. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Put an Amazon SQS queue between each pair of stages so that each stage reads work from its own queue`,`Each queue buffers work and removes the need for the stages to be available at the same time.`],[`Run each stage in its own Auto Scaling group and scale it with a target tracking policy on a backlog per instance metric`,`Each group follows the backlog of its own queue, so a slow stage gets more capacity without resizing the others.`]],wrong:[[`Run all three stages on the same instances and scale that one group on average CPU utilization`,`The stages remain coupled and cannot be scaled on their own backlogs.`],[`Raise the maximum size of the extract stage group so that it can send work to the enrich stage faster`,`This pushes more work into the stage that is already overloaded.`],[`Put an Application Load Balancer between each pair of stages and keep the synchronous calls`,`Synchronous calls keep the stages coupled, so a slow stage still holds up the caller.`]],slots:[1,4],evidence:[`sns-sqs-fanout|It decouples sending and receiving components—without requiring each component to be available at the same time.`,`asg-sqs|To scale your Auto Scaling group in proportion to the work waiting in your queue, use a backlog per instance metric.`,`asg-sqs|If you use a target tracking scaling policy based on a custom Amazon SQS queue metric, dynamic scaling can adjust to the demand curve of your application more effectively.`]})],u=[t({id:`freight-depot-001`,building:`freight-depot`,bullets:[`3.1-K1`],d:1,tags:[`placement-eligible`],stem:`A company's on-premises applications read and write files over NFS to a storage appliance that is almost full. The company wants the files stored as objects in Amazon S3 without changing the applications, and wants recently used files to stay available with low latency on premises. Which solution BEST meets these requirements?`,correct:[`Deploy an Amazon S3 File Gateway on premises and mount its NFS file shares on the application servers`,`The gateway presents NFS file shares that store the files as S3 objects and keeps recently used data in a local cache, so the applications stay unchanged.`],wrong:[[`Deploy a Volume Gateway on premises and present its volumes to the application servers over iSCSI connections`,`Volume Gateway presents iSCSI block volumes, not NFS file shares, so the applications would have to change.`],[`Deploy a Tape Gateway on premises and have the applications write their files to virtual tapes each night`,`Tape Gateway provides virtual tape storage for archiving backup data, so the applications cannot read and write files over NFS to it.`],[`Mount an Amazon EFS file system on the application servers over a private network connection to AWS`,`EFS keeps data in its own file system, not as S3 objects, and every request crosses the network with no local cache.`]],slot:0,evidence:[`sgw-file-s3|You can store and retrieve files directly using the NFS version 3 or 4.1 protocol.`,`sgw-file-s3|The gateway provides access to objects in S3 as files or file share mount points.`,`sgw-file-s3|It also provides low-latency access to data through transparent local caching.`]}),t({id:`freight-depot-002`,building:`freight-depot`,bullets:[`3.1-K1`],d:1,stem:`A company backs up its servers with software that writes to a physical tape library and ships tapes to an offsite vault. The company wants to stop handling physical tapes and to durably archive the backups in AWS, with the LEAST change to its tape-based backup jobs. Which solution meets these requirements?`,correct:[`Deploy a Tape Gateway and let the backup software write to its virtual tape library`,`Tape Gateway provides cloud-backed virtual tape storage that archives backup data in S3 Glacier storage classes and removes the physical tape infrastructure.`],wrong:[[`Deploy an Amazon S3 File Gateway and change the backup jobs to write to an NFS file share`,`File Gateway exposes file shares, not a virtual tape library, so every tape-based backup job would have to be rewritten.`],[`Deploy a Volume Gateway and change the backup jobs to write to iSCSI block volumes`,`Volume Gateway provides block volumes rather than virtual tapes, so the tape-based jobs would have to change.`],[`Use AWS DataSync to copy the backup data to Amazon S3 on a schedule after each job finishes`,`DataSync transfers file or object data and does not present a tape library to the backup software, so the jobs would change.`]],slot:1,evidence:[`sgw-tape|Tape Gateway provides cloud-backed virtual tape storage.`,`sgw-tape|With Tape Gateway, you can cost-effectively and durably archive backup data in S3 Glacier Flexible Retrieval or S3 Glacier Deep Archive.`,`sgw-tape|Tape Gateway provides a virtual tape infrastructure that scales seamlessly with your business needs and eliminates the operational burden of provisioning, scaling, and maintaining a physical tape infrastructure.`]}),t({id:`freight-depot-003`,building:`freight-depot`,bullets:[`3.1-K1`],d:3,stem:`A company runs a latency-sensitive application on premises that stores its data on iSCSI block volumes. The application needs low-latency access to its entire dataset, and the company also wants point-in-time backups of that data kept durably in AWS. Which solution BEST meets these requirements?`,correct:[`Deploy a Volume Gateway with stored volumes that keep all data locally and asynchronously back up snapshots to Amazon S3`,`Stored volumes keep the entire dataset on premises for low-latency access and asynchronously back up point-in-time snapshots to S3.`],wrong:[[`Deploy a Volume Gateway with cached volumes that keep the data in Amazon S3 and retain only frequently accessed subsets locally`,`Cached volumes hold the primary data in S3 and keep only frequently accessed subsets locally, so low latency for the entire dataset is not provided.`],[`Deploy an Amazon S3 File Gateway and present its NFS file shares to the application servers`,`S3 File Gateway provides NFS or SMB file shares, but the application stores its data on iSCSI block volumes.`],[`Deploy a Tape Gateway and write the application data to virtual tapes every hour`,`Tape Gateway provides virtual tape storage for archiving backups and does not serve iSCSI block volumes to a running application.`]],slot:2,evidence:[`sgw-volume|Volume Gateway provides cloud-backed storage volumes that you can mount as Internet Small Computer System Interface (iSCSI) devices from your on-premises application servers.`,`sgw-volume|If you need low-latency access to your entire dataset, first configure your on-premises gateway to store all your data locally.`,`sgw-volume|Then asynchronously back up point-in-time snapshots of this data to Amazon S3.`,`sgw-volume|You store your data in Amazon Simple Storage Service (Amazon S3) and retain a copy of frequently accessed data subsets locally.`]}),e({id:`freight-depot-004`,building:`freight-depot`,bullets:[`3.1-K1`],d:2,stem:`A company wants to retire two on-premises systems: a file server that Linux clients mount over NFS, and a physical tape library that its backup software writes to every night. Both data sets must be stored in AWS, and the company wants the LEAST change to the clients and the backup software. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Deploy an Amazon S3 File Gateway for the NFS file shares`,`The gateway lets the Linux clients keep using NFS while the files are stored in Amazon S3.`],[`Deploy a Tape Gateway for the backup software`,`The backup software keeps writing to virtual tapes, which are archived durably in S3 Glacier storage classes.`]],wrong:[[`Deploy a Volume Gateway and present iSCSI volumes to the clients and the backup software`,`iSCSI block volumes are neither NFS file shares nor virtual tapes, so both the clients and the backup software would change.`],[`Attach Amazon EBS volumes to the Linux clients and copy the file server data onto them`,`EBS volumes attach to Amazon EC2 instances, not to on-premises clients, and they do not replace the tape library.`],[`Move the Linux clients to Amazon EC2 instances and mount an Amazon EFS file system on them`,`This changes the clients themselves, and it does nothing for the backup software that writes to tapes.`]],slots:[1,4],evidence:[`sgw-file-s3|You can store and retrieve files directly using the NFS version 3 or 4.1 protocol.`,`sgw-tape|Tape Gateway provides cloud-backed virtual tape storage.`,`sgw-tape|With Tape Gateway, you can cost-effectively and durably archive backup data in S3 Glacier Flexible Retrieval or S3 Glacier Deep Archive.`]}),t({id:`freight-depot-005`,building:`freight-depot`,bullets:[`3.1-K2`],d:2,tags:[`placement-eligible`,`trap:ebs-efs-fsx`],stem:`A company runs a content-management application on Linux Amazon EC2 instances in an Auto Scaling group across three Availability Zones. Editors upload files that every instance must read and write through standard file system calls with POSIX permissions, and the application code cannot be changed. The storage must grow automatically without capacity planning. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Mount a Regional Amazon EFS file system on every instance and store all of the files on it`,`EFS provides shared NFS file storage with POSIX permissions across Availability Zones and grows and shrinks automatically as files are added and removed.`],wrong:[[`Store the files in an Amazon S3 bucket and have every instance read and write them through the S3 API`,`S3 is accessed through an API rather than standard file system calls, so the application code would have to change.`],[`Attach an Amazon EBS volume to each instance and synchronize the volumes with a custom script`,`An EBS volume is attached to one instance in one Availability Zone and must be sized in advance, and the script is extra operational work.`],[`Keep the files on the instance store volumes and copy them between instances on a schedule`,`Instance store data is lost when an instance stops, and its capacity is fixed by the instance type.`]],slot:3,evidence:[`efs-what-is|Amazon EFS also supports controlling access to your file systems through Portable Operating System Interface (POSIX) permissions.`,`efs-what-is|Amazon EFS is built to scale on demand to petabytes without disrupting applications, growing and shrinking automatically as you add and remove files.`,`efs-what-is|Regional file systems (recommended) store data redundantly across multiple geographically separated Availability Zones within the same AWS Region.`,`storage-decision|Object storage provides easy access to data through an application programming interface (API) over the internet`]}),t({id:`freight-depot-006`,building:`freight-depot`,bullets:[`3.1-K2`,`3.1-S1`],d:2,tags:[`placement-eligible`,`trap:ebs-efs-fsx`],stem:`A research company keeps 300 TB of genomic data in Amazon S3. For each analysis run, hundreds of Linux compute instances must process the data through a POSIX file system with sub-millisecond latencies and very high throughput, and the results must go back to the S3 bucket. Which solution BEST meets these requirements?`,correct:[`Create an Amazon FSx for Lustre file system linked to the S3 bucket and mount it on the instances`,`FSx for Lustre is a POSIX-compliant, high-performance file system with sub-millisecond latencies that can be linked to data repositories on S3.`],wrong:[[`Create an Amazon EFS file system, copy the data into it and mount it on all of the compute instances`,`EFS Standard has first-byte read latencies as low as 1 millisecond, not sub-millisecond, and the data would have to be copied out of S3.`],[`Attach one Amazon EBS volume with Multi-Attach enabled to all of the compute instances in the cluster`,`Multi-Attach supports up to 16 Nitro-based instances in one Availability Zone, so it cannot serve hundreds of instances.`],[`Create an Amazon FSx for Windows File Server file system and mount it on the instances over SMB`,`FSx for Windows File Server is a native Windows file system for SMB clients, not the high-speed POSIX file system these Linux jobs need.`]],slot:0,evidence:[`fsx-lustre|It provides sub-millisecond latencies, up to multiple TBps of throughput and up to millions of IOPS.`,`fsx-lustre|FSx for Lustre is POSIX-compliant, so you can use your current Linux-based applications without having to make any changes.`,`fsx-lustre|You can link FSx for Lustre file systems to data repositories on Amazon S3 or to on-premises data stores.`,`ebs-multi-attach|Multi-Attach enabled volumes can be attached to up to 16 instances built on the Nitro System that are in the same Availability Zone.`,`efs-performance|This storage class provides first-byte latencies as low as 1 millisecond for reads and 2.7 milliseconds for writes.`]}),t({id:`freight-depot-007`,building:`freight-depot`,bullets:[`3.1-K2`],d:3,tags:[`trap:ebs-efs-fsx`],stem:`A company runs stateful pods on Amazon EKS with worker nodes in three Availability Zones. A group of pods that can be scheduled onto nodes in any zone must read and write the same files at the same time, and the files must stay available if one Availability Zone fails. The company wants the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Use the Amazon EFS CSI driver to mount a Regional Amazon EFS file system into the pods`,`EFS provides shared file storage that nodes in every Availability Zone can mount, and a Regional file system stays available when one zone fails.`],wrong:[[`Use the Amazon EBS CSI driver to attach one Amazon EBS volume to all of the pods`,`An EBS volume must be in the same Availability Zone as its instance and normally attaches to a single instance, so pods in other zones cannot share it.`],[`Use the Amazon EBS CSI driver to give each pod a volume and replicate the data between the volumes`,`The volumes stay bound to their own zones, and the replication process is extra work for the company to build and operate.`],[`Use the instance store volume of each worker node and copy the files between nodes on a schedule`,`Instance store data is lost when a node stops, and the copy job is extra work that leaves the pods with different data.`]],slot:1,evidence:[`storage-decision|Attach file and block storage through Container Storage Interface (CSI) drivers, such as the Amazon EFS CSI driver and the Amazon EBS CSI driver.`,`efs-what-is|Storing data across multiple Availability Zones provides continuous availability to the data, even when one or more Availability Zones in an AWS Region are unavailable.`,`ebs-volumes|The volume and instance must be in the same Availability Zone.`]}),t({id:`freight-depot-008`,building:`freight-depot`,bullets:[`3.1-K2`,`3.1-S2`],d:2,tags:[`placement-eligible`],stem:`A photo-sharing company serves user-uploaded photos directly to web and mobile clients over HTTPS. The collection grows unpredictably and is expected to reach several hundred terabytes. The company does not want to provision storage capacity or run servers just to serve the files. Which storage solution BEST meets these requirements?`,correct:[`Store the photos as objects in Amazon S3 and give web and mobile clients access over HTTPS`,`S3 stores any amount of data, grows without provisioning, and gives clients access to objects over the internet through an API.`],wrong:[[`Store the photos on an Amazon EFS file system that the web and mobile clients mount over NFS`,`EFS is a file system that compute resources mount over NFS, so web and mobile clients cannot read it directly over the internet.`],[`Store the photos on Amazon EBS volumes attached to a fleet of web servers that serve them`,`EBS volumes need provisioned capacity with a defined maximum size and servers to serve the files, both of which the company wants to avoid.`],[`Store the photos on the instance store volumes of a fleet of web servers that serve them`,`Instance store capacity is fixed by the instance type and its data is lost when an instance stops, and servers are needed to serve the files.`]],slot:2,evidence:[`storage-decision|Well-suited for scenarios where data needs to be stored, accessed, and distributed globally over the internet.`,`s3-what-is|Customers of all sizes and industries can use Amazon S3 to store and protect any amount of data for a range of use cases, such as data lakes, websites, mobile applications, backup and restore, archive, enterprise applications, IoT devices, and big data analytics.`,`ebs-volume-types|Volume size 1 GiB - 64 TiB 1 GiB - 16 TiB 4 GiB - 64 TiB 4 GiB - 16 TiB`]}),t({id:`freight-depot-009`,building:`freight-depot`,bullets:[`3.1-K3`],d:1,stem:`A company must store billions of scanned documents. Each document is addressed by a unique identifier, carries descriptive metadata, and is retrieved as a whole through an API over the internet. Which storage type and service BEST fit this workload?`,correct:[`Object storage with Amazon S3`,`Object storage manages data as objects, each tagged with a unique identifier and carrying metadata, and it is accessed through an API over the internet.`],wrong:[[`Block storage with Amazon EBS`,`Block storage is attached to a compute instance like a local disk and is not retrieved by identifier through an API over the internet.`],[`File storage with Amazon EFS`,`File storage is a hierarchy of files and folders that clients mount over NFS, not objects addressed by an identifier through an API.`],[`File storage with Amazon FSx for Windows File Server`,`FSx for Windows File Server serves SMB file shares from a native Windows file system, not objects retrieved through an API.`]],slot:3,evidence:[`storage-decision|Each object is tagged with a unique identifier and contains metadata that describes the underlying content.`,`storage-decision|Object storage provides easy access to data through an application programming interface (API) over the internet and is well-suited to read-heavy workloads (such as streaming applications and services).`]}),t({id:`freight-depot-010`,building:`freight-depot`,bullets:[`3.1-K3`],d:2,tags:[`trap:instance-store-vs-ebs`],stem:`A company runs a database on an Amazon EC2 instance and keeps its data files on a block storage volume. Operations stops the instance every night to save cost and starts it again each morning, and the data files must still be there. Which storage option is the BEST choice for the data files?`,correct:[`An Amazon EBS volume that is attached to the instance`,`EBS volumes persist independently from the running life of an instance, so the data files survive the nightly stop and start.`],wrong:[[`The instance store volumes of a storage optimized instance`,`Instance store data does not persist when the instance is stopped, so the data files would be lost every night.`],[`An Amazon EFS file system mounted on the instance`,`EFS is shared file storage, not the block storage volume on which the database keeps its data files.`],[`An Amazon S3 bucket used as the database data volume`,`S3 is object storage reached through an API, not a block volume that a database can use for its data files.`]],slot:0,evidence:[`instance-store-lifetime|The data on an instance store volume persists even if the instance is rebooted. However, the data does not persist if the instance is stopped, hibernated, or terminated.`,`ebs-volumes|EBS volumes persist independently from the running life of an EC2 instance.`]}),t({id:`freight-depot-011`,building:`freight-depot`,bullets:[`3.1-K3`],d:3,tags:[`trap:ebs-efs-fsx`],stem:`A company runs a Linux application on two Amazon EC2 instances that are in different Availability Zones. Both instances must read and write the same files at the same time through standard file system calls. A developer proposes an Amazon EBS volume with Multi-Attach enabled. Which solution BEST meets the requirements?`,correct:[`Mount a Regional Amazon EFS file system on both instances and use it as shared storage`,`EFS is shared file storage that instances in different Availability Zones can mount and use at the same time.`],wrong:[[`Create an io2 volume with Multi-Attach enabled and attach it to both instances`,`Multi-Attach attaches a volume only to instances in the same Availability Zone, so it cannot serve instances in two zones.`],[`Create an EBS volume in each Availability Zone and copy snapshots between them every minute`,`Snapshots are point-in-time backups, not a live shared file system, so the instances would not see each other's writes at the same time.`],[`Store the files in an Amazon S3 bucket and have both instances call the S3 API`,`S3 is accessed through an API, not through standard file system calls, so the application would have to change.`]],slot:1,evidence:[`ebs-multi-attach|Amazon EBS Multi-Attach enables you to attach a single Provisioned IOPS SSD (io1 or io2) volume to multiple instances that are in the same Availability Zone.`,`storage-decision|Applications and workloads requiring shared read and write access across multiple Amazon EC2 instances or containers, or from multiple on-premises servers`,`efs-what-is|Regional file systems (recommended) store data redundantly across multiple geographically separated Availability Zones within the same AWS Region.`]}),t({id:`freight-depot-012`,building:`freight-depot`,bullets:[`3.1-S1`],d:2,tags:[`placement-eligible`],stem:`An analytics application on Amazon EC2 reads millions of small objects from one Amazon S3 bucket, and all the objects share a single key prefix. At peak the application needs a much higher GET request rate than a single prefix supports and receives HTTP 503 Slow Down responses. Which change will raise the achievable read request rate the MOST?`,correct:[`Spread the objects across multiple prefixes in the bucket and read from the prefixes in parallel`,`S3 request rates apply per partitioned prefix and a bucket can have any number of prefixes, so reading from several prefixes in parallel multiplies the read rate.`],wrong:[[`Enable S3 Transfer Acceleration on the bucket and use the accelerated endpoint for all of the reads`,`Transfer Acceleration speeds up transfers over long distances between a client and a bucket and does not raise the per-prefix request rate.`],[`Add more EC2 instances so that each instance reads the same prefix over its own connection`,`The request rate is defined per partitioned prefix, so more instances reading one prefix still share that one prefix.`],[`Use multipart upload for every object so that the reads are split into several parts`,`Multipart upload applies to uploading objects, so it does not raise the GET request rate that a prefix supports.`]],slot:2,evidence:[`s3-performance|For example, your application can achieve at least 3,500 PUT/COPY/POST/DELETE or 5,500 GET/HEAD requests per second per partitioned Amazon S3 prefix.`,`s3-performance|There are no limits to the number of prefixes in a bucket.`,`s3-performance|For example, if you create 10 prefixes in an Amazon S3 bucket to parallelize reads, you could scale your read performance to 55,000 read requests per second.`]}),t({id:`freight-depot-013`,building:`freight-depot`,bullets:[`3.1-S1`],d:2,tags:[`placement-eligible`],stem:`Field technicians upload video files of 8 GB or more to an Amazon S3 bucket over unreliable cellular connections. A dropped connection currently forces the whole upload to restart. The company wants a dropped connection to cost the LEAST re-sent data and wants each upload to use the available bandwidth in parallel. Which solution meets these requirements?`,correct:[`Upload each file with S3 multipart upload and retry only the parts that fail to upload`,`Multipart upload sends parts independently and in parallel, and a failed part can be retransmitted without affecting the other parts.`],wrong:[[`Upload each file with a single PUT request and retry the whole request when it fails`,`A single PUT sends the object in one operation, so a dropped connection restarts the whole upload and nothing runs in parallel.`],[`Enable S3 Transfer Acceleration and keep uploading each file with a single PUT request`,`Transfer Acceleration shortens the network path over long distances, but each file is still one request that restarts after a dropped connection.`],[`Add an S3 Lifecycle rule that aborts failed uploads after one day on the bucket`,`A lifecycle rule only cleans up incomplete multipart uploads; it does not resume a transfer or reduce the data that is re-sent.`]],slot:3,evidence:[`s3-multipart|You can upload these object parts independently, and in any order.`,`s3-multipart|If transmission of any part fails, you can retransmit that part without affecting other parts.`,`s3-multipart|It's a best practice to use multipart upload for objects that are 100 MB or larger instead of uploading them in a single operation.`]}),t({id:`freight-depot-014`,building:`freight-depot`,bullets:[`3.1-S1`],d:2,tags:[`placement-eligible`],stem:`A company collects several terabytes of media files every week from offices in Asia, Europe and South America. All files are uploaded to one Amazon S3 bucket in the us-east-1 Region, and the long-distance uploads use only a fraction of the available bandwidth. Which change will MOST improve upload speed with the LEAST operational overhead?`,correct:[`Enable S3 Transfer Acceleration on the bucket and have the offices upload through the accelerate endpoint`,`Transfer Acceleration routes uploads through nearby edge locations and an optimized network path, which suits regular multi-terabyte transfers across continents.`],wrong:[[`Create a bucket in each office Region and replicate the contents of every bucket into the central bucket`,`This adds buckets and replication to manage, and files reach the central bucket only after replication completes.`],[`Spread the uploaded files across many key prefixes in the central bucket so each office has its own`,`Prefixes raise the request rate that a bucket supports, but they do not shorten the network path between a distant office and the bucket.`],[`Change the bucket to the S3 One Zone-IA storage class and keep uploading the files as before`,`A storage class changes how objects are stored, not the network path that long-distance uploads take to the bucket.`]],slot:0,evidence:[`s3-perf-guidelines|Transfer Acceleration is ideal for transferring gigabytes to terabytes of data regularly across continents.`,`s3-perf-guidelines|As the data arrives at an edge location, it is routed to Amazon S3 over an optimized network path.`,`s3-transfer-acceleration|You can't use all of your available bandwidth over the internet when uploading to Amazon S3.`]}),e({id:`freight-depot-015`,building:`freight-depot`,bullets:[`3.1-S1`],d:3,tags:[`placement-eligible`],stem:`A data-processing application on Amazon EC2 instances downloads objects of several gigabytes from an Amazon S3 bucket. Each object is read with a single GET request on one connection, and throughput is low. The instances currently run in a different AWS Region from the bucket, and nothing ties them to that Region. Which TWO actions will MOST improve the aggregate download throughput? (Choose two.)`,correct:[[`Fetch different byte ranges of each object over concurrent connections by using the Range header`,`Concurrent byte-range fetches of the same object give higher aggregate throughput than a single whole-object request.`],[`Run the instances in the same AWS Region as the bucket`,`AWS recommends accessing the bucket from Amazon EC2 instances in the same AWS Region to optimize performance.`]],wrong:[[`Spread the few large objects across additional key prefixes in the bucket`,`Prefixes raise the request rate that the bucket supports, but each large object would still download over one connection.`],[`Move the objects to the S3 Standard-IA storage class`,`A storage class does not change how many connections fetch an object, so the download throughput stays the same.`],[`Enable server-side encryption with AWS KMS keys on the bucket`,`Encryption protects data at rest and adds no parallelism to a download, and AWS KMS request quotas can limit the request rate.`]],slots:[0,3],evidence:[`s3-perf-guidelines|You can use concurrent connections to Amazon S3 to fetch different byte ranges from within the same object. This helps you achieve higher aggregate throughput versus a single whole-object request.`,`s3-perf-guidelines|To optimize performance, we recommend that you access the bucket from Amazon EC2 instances in the same AWS Region when possible.`]}),t({id:`freight-depot-016`,building:`freight-depot`,bullets:[`3.1-S1`],d:2,stem:`A company runs a mission-critical transactional database on an Amazon EC2 instance. The database needs consistent sub-millisecond latency and sustained IOPS from its data volume. Which Amazon EBS volume type BEST meets these requirements?`,correct:[`A Provisioned IOPS SSD (io2 Block Express) volume with enough IOPS provisioned`,`io2 Block Express is intended for workloads that need consistent sub-millisecond latency and sustained IOPS performance.`],wrong:[[`A General Purpose SSD (gp3) volume with the maximum IOPS and throughput provisioned`,`gp3 provides single-digit millisecond latency, which does not meet the sub-millisecond requirement.`],[`A Throughput Optimized HDD (st1) volume that is sized for the whole data set`,`st1 is an HDD type optimized for large streaming workloads where throughput, not latency or IOPS, is the dominant attribute.`],[`A Cold HDD (sc1) volume set with the data files spread over several volumes`,`sc1 is an HDD type for infrequently accessed data where the lowest storage cost matters, not for a transactional database.`]],slot:1,evidence:[`ebs-volume-types|Consistent sub-millisecond latency with average latency under 500 microseconds`,`ebs-gp|gp3 volumes provide single-digit millisecond latency and 99.8 percent to 99.9 percent volume durability`,`ebs-volume-types|HDD-backed volumes are optimized for large streaming workloads where the dominant performance attribute is throughput.`]}),t({id:`freight-depot-017`,building:`freight-depot`,bullets:[`3.1-S1`],d:3,stem:`A media company renders images on Linux Amazon EC2 instances that read and write a shared Amazon EFS file system. The file system holds a small amount of data, but the workload drives a steady, known level of throughput that is high compared with the stored data. The workload needs the lowest per-operation latency. Which EFS configuration is the BEST fit?`,correct:[`General Purpose mode with Provisioned throughput`,`Provisioned throughput suits workloads whose performance requirements are known, and General Purpose mode has the lowest per-operation latency.`],wrong:[[`General Purpose mode with Bursting throughput`,`Bursting throughput scales with the amount of storage in the file system, which is small here, so it cannot deliver the steady high throughput.`],[`Max I/O mode with Provisioned throughput`,`Max I/O mode has higher per-operation latencies than General Purpose, and the workload needs the lowest latency.`],[`Max I/O mode with Bursting throughput`,`Max I/O mode has higher per-operation latencies, and Bursting throughput scales with the small amount of stored data.`]],slot:2,evidence:[`efs-performance|Provisioned throughput – Use Provisioned throughput if you know your workload's performance requirements, or when your application drives throughput at an average-to-peak ratio of 5% or more.`,`efs-performance|Bursting throughput – Use Bursting throughput when you want throughput that scales with the amount of storage in your file system.`,`efs-performance|Important Max I/O performance mode has higher per-operation latencies than General Purpose performance mode.`,`efs-performance|General Purpose mode has the lowest per-operation latency and is the default performance mode for file systems.`]}),t({id:`freight-depot-018`,building:`freight-depot`,bullets:[`3.1-S2`],d:1,stem:`A media company lets customers upload photos that browsers fetch directly over HTTPS. The collection will grow for years and could reach many petabytes, and no one can predict the growth rate. The company does not want to resize storage, add volumes or re-architect as the collection grows. Which storage service meets these requirements with the LEAST operational overhead?`,correct:[`Amazon S3, with the photos stored as objects in a bucket`,`S3 is object storage built for scalability, so the collection can grow without resizing or provisioning anything.`],wrong:[[`A single Amazon EBS General Purpose SSD volume that is enlarged with Elastic Volumes as needed`,`The volume has a defined size that someone must increase by hand, and one volume cannot grow without limit.`],[`The instance store volumes of a storage-optimized Amazon EC2 instance type`,`Instance store capacity is fixed by the instance type and its data is lost when the instance stops.`],[`Additional Amazon EBS volumes attached to a growing fleet of instances, with an index of where each photo lives`,`Every new volume must be provisioned and tracked, which is the capacity management the company wants to avoid.`]],slot:3,evidence:[`s3-what-is|Amazon Simple Storage Service (Amazon S3) is an object storage service that offers industry-leading scalability, data availability, security, and performance.`,`ebs-modify|You must increase the volume size.`]}),e({id:`freight-depot-019`,building:`freight-depot`,bullets:[`3.1-S2`],d:2,stem:`A production database runs on Amazon EC2 with its data files on a 500 GiB General Purpose SSD (gp3) volume that is almost full. The database must stay online during business hours, and the company wants to add capacity with the LEAST disruption. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Increase the size of the volume with Amazon EBS Elastic Volumes while it stays attached`,`Elastic Volumes can increase the volume size without detaching the volume or restarting the instance, if the instance supports it.`],[`Extend the partition and file system on the instance once the volume is in the optimizing state`,`After a size increase the partition and file system must be extended to the new, larger size before the database can use the space.`]],wrong:[[`Stop the database, create a larger volume from a snapshot and swap the volumes`,`This causes downtime during the swap, which the database cannot tolerate during business hours.`],[`Add an instance store volume to the running instance and move the data files onto it`,`Instance store volumes can be attached only at launch, and their data does not persist when the instance stops.`],[`Change the instance to a larger instance type so that the volume grows with it`,`Changing the instance type resizes the compute, not the attached volume, and it needs a stop that interrupts the database.`]],slots:[2,4],evidence:[`ebs-modify|With Amazon EBS Elastic Volumes, you can increase the volume size, change the volume type, or adjust the performance of your EBS volumes.`,`ebs-modify|If your instance supports Elastic Volumes, you can do so without detaching the volume or restarting the instance.`,`ebs-extend-fs|After you increase the size of an EBS volume, you must extend the partition and file system to the new, larger size.`,`instance-store-lifetime|Instance store volumes are attached only at instance launch.`]}),e({id:`freight-depot-020`,building:`freight-depot`,bullets:[`3.1-K2`,`3.1-K3`],d:2,tags:[`mock-reserve`,`trap:ebs-efs-fsx`],stem:`A company is moving a Windows-based file-sharing workload to AWS. Windows Amazon EC2 instances must mount the shared storage over SMB, and the company wants fully managed file storage with the LEAST operational overhead. Which TWO services meet these requirements? (Choose two.)`,correct:[[`Amazon FSx for Windows File Server`,`FSx for Windows File Server provides fully managed Windows file servers backed by a native Windows file system with full SMB support.`],[`Amazon FSx for NetApp ONTAP`,`FSx for NetApp ONTAP supports both NFS and SMB, so Windows clients can use it as shared file storage.`]],wrong:[[`Amazon EFS`,`Using EFS with Windows-based Amazon EC2 instances is not supported, and it is accessed over NFS rather than SMB.`],[`Amazon FSx for Lustre`,`FSx for Lustre is designed for use with Unix/Linux-based file systems, not for Windows SMB file shares.`],[`Amazon EBS`,`EBS provides block volumes attached to instances; it is not a managed shared SMB file service.`]],slots:[0,2],evidence:[`fsx-windows|Amazon FSx for Windows File Server provides fully managed Microsoft Windows file servers, backed by a fully native Windows file system.`,`storage-decision|It provides highly available storage to your Windows applications with full Server Message Block (SMB) support.`,`storage-decision|Amazon FSx for NetApp ONTAP supports both NFS and SMB protocols, including concurrent multi-protocol access to the same data.`,`storage-decision|Amazon FSx for Lustre (for high-performance file systems) is designed for use with Unix/Linux-based file systems.`,`efs-what-is|Using Amazon EFS with Microsoft Windows–based Amazon EC2 instances is not supported.`]}),t({id:`freight-depot-021`,building:`freight-depot`,bullets:[`3.1-K1`,`3.1-S2`],d:2,tags:[`mock-reserve`],stem:`A company's on-premises application uses iSCSI block volumes that grow by about 10 percent each month. The company does not want to keep buying on-premises storage, but the application needs low-latency access to the data it uses most often. Which solution meets these requirements MOST cost-effectively?`,correct:[`Deploy a Volume Gateway with cached volumes that keep data in Amazon S3 and frequently used data locally`,`Cached volumes keep the primary data in S3, retain frequently accessed subsets locally for low latency, and minimize the need to scale on-premises storage.`],wrong:[[`Deploy a Volume Gateway with stored volumes that keep the entire dataset on the premises of the company`,`Stored volumes keep all data locally, so the on-premises storage would still have to grow with the dataset.`],[`Deploy an Amazon S3 File Gateway and move the application from its block volumes to NFS file shares`,`S3 File Gateway provides NFS or SMB file shares, so the application that uses iSCSI block volumes would have to change.`],[`Deploy a Tape Gateway and write the application data to virtual tapes as the volumes grow larger over time`,`Tape Gateway archives backup data on virtual tapes and does not serve block volumes to a running application.`]],slot:0,evidence:[`sgw-volume|Cached volumes offer a substantial cost savings on primary storage and minimize the need to scale your storage on-premises.`,`sgw-volume|first configure your on-premises gateway to store all your data locally.`,`sgw-volume|You also retain low-latency access to your frequently accessed data.`]})],d=[t({id:`grid-planning-office-001`,building:`grid-planning-office`,bullets:[`3.4-K2`,`3.4-S2`],d:1,stem:`A company's production VPC was created with the IPv4 CIDR block 10.0.0.0/24 and is running out of IPv4 addresses for new subnets. The company must add address space to the existing VPC without rebuilding it. Which solution BEST meets this requirement?`,correct:[`Associate an additional IPv4 CIDR block with the existing VPC`,`After a VPC is created, additional IPv4 CIDR blocks can be associated with it, which adds address space without rebuilding.`],wrong:[[`Create a new VPC with a larger CIDR block and migrate every resource into it`,`This is a rebuild of the environment, which the company wants to avoid.`],[`Create a second VPC with its own CIDR block and connect it with a VPC peering connection`,`Existing subnets would still have no free addresses, and the new VPC would have to host and reconnect any new resources.`],[`Associate an IPv6 CIDR block with the existing VPC to gain more addresses`,`Resources in an IPv4-only subnet must communicate over IPv4, so the IPv4 shortage would remain.`]],slot:0,evidence:[`vpc-cidr-blocks|After you've created your VPC, you can associate additional IPv4 CIDR blocks with the VPC.`,`vpc-subnets|Resources in an IPv4-only subnet must communicate over IPv4.`]}),t({id:`grid-planning-office-002`,building:`grid-planning-office`,bullets:[`3.4-K2`],d:2,stem:`A company is creating one subnet for a fleet that will run up to 120 Amazon EC2 instances, and wants the SMALLEST CIDR block that can hold them. Which subnet CIDR block should the network architect choose?`,correct:[`A /25 block: 128 addresses, of which 123 remain after reservations`,`A /25 holds 128 addresses, and after the first four and the last address are reserved, 123 are left, which covers 120 instances.`],wrong:[[`A /28 block, with 16 addresses of which a few are reserved`,`A /28 holds only 16 addresses, far fewer than 120 even before the reserved ones are removed.`],[`A /24 block, with 256 addresses of which 251 remain after the reserved addresses`,`A /24 fits the fleet but is twice the size needed, so it is not the smallest block that works.`],[`A /16 block, with 65,536 addresses of which 65,531 remain after the reserved addresses`,`A /16 fits the fleet but is by far larger than needed, so it is not the smallest block that works.`]],slot:1,evidence:[`vpc-subnet-sizing|The first four IP addresses and the last IP address in each subnet CIDR block are not available for your use, and they cannot be assigned to a resource, such as an EC2 instance.`,`vpc-subnet-sizing|You can break this CIDR block into two subnets, each supporting 128 IP addresses.`,`vpc-cidr-blocks|The allowed block size is between a /16 netmask (65,536 IP addresses) and /28 netmask (16 IP addresses).`]}),e({id:`grid-planning-office-003`,building:`grid-planning-office`,bullets:[`3.4-K2`],d:2,stem:`Application servers in a private subnet must download operating system updates from the internet, but nothing on the internet may be able to start a connection to them. Which TWO actions meet these requirements with the LEAST change to the subnet design? (Choose two.)`,correct:[[`Create a public NAT gateway in a public subnet of the same Availability Zone`,`A NAT gateway lets instances in a private subnet connect to services outside the VPC while external services cannot initiate connections to them.`],[`Add a route for 0.0.0.0/0 to the NAT gateway in the private subnet's route table`,`Each route has a destination and a target, so the default route in the private subnet's route table must point at the NAT gateway to send outbound traffic there.`]],wrong:[[`Add a route for 0.0.0.0/0 to an internet gateway in the private subnet's route table`,`A route to an internet gateway makes the subnet public, which the design is meant to avoid.`],[`Move the servers into the public subnet and give each one a public IPv4 address`,`Resources in a public subnet are reachable from the internet, which defeats the no-inbound requirement.`],[`Create a VPC peering connection to a second VPC and route 0.0.0.0/0 through it`,`Peered VPCs cannot use each other's internet gateway or NAT device, so the traffic would not reach the internet.`]],slots:[0,3],evidence:[`vpc-nat-gateway|You can use a NAT gateway so that instances in a private subnet can connect to services outside your VPC but external services can't initiate a connection with those instances.`,`vpc-route-tables|Each route specifies a destination (CIDR block or prefix list) and a target (such as an internet gateway, NAT gateway, VPC peering connection, or VPN connection).`,`vpc-subnets|Public subnet – The subnet has a direct route to an internet gateway.`,`peering-basics|If VPC A has an NAT device that provides internet access to subnets in VPC A, resources in VPC B can't use the NAT device in VPC A to access the internet.`]}),t({id:`grid-planning-office-004`,building:`grid-planning-office`,bullets:[`3.4-K2`,`3.4-S1`],d:3,tags:[`trap:peering-tgw-privatelink`],stem:`After a merger, two companies each run a VPC that uses the CIDR block 10.0.0.0/16. Applications in one VPC need private access to a single internal API hosted in the other VPC, and neither network may be renumbered. Which solution BEST meets these requirements?`,correct:[`Publish the API as an endpoint service behind a Network Load Balancer and add an interface endpoint in the other VPC`,`PrivateLink works when the VPCs have overlapping IP addresses, needs no renumbering, and exposes only the one service rather than the whole network.`],wrong:[[`Create a VPC peering connection between the two VPCs and add routes to each of the VPC route tables`,`VPC peering cannot be created between VPCs that have matching or overlapping CIDR blocks, and these two match exactly.`],[`Replace the CIDR block of one VPC with a non-overlapping range, re-address its resources and subnets, and then peer the two VPCs`,`This renumbers one of the networks, which the requirements rule out.`],[`Place the API behind an internet-facing load balancer and have the other VPC call it over the public internet`,`The access must be private, and an internet-facing endpoint sends the traffic over the public internet.`]],slot:2,evidence:[`peering-basics|You cannot create a VPC peering connection between VPCs that have matching or overlapping IPv4 or IPv6 CIDR blocks.`,`connectivity-privatelink|Alternatively, AWS PrivateLink is a good solution when the VPCs have overlapped IP addresses.`,`privatelink-service|Endpoint services require either a Network Load Balancer or a Gateway Load Balancer.`]}),t({id:`grid-planning-office-005`,building:`grid-planning-office`,bullets:[`3.4-K2`],d:2,tags:[`mock-reserve`],stem:`A network engineer must send traffic for 10.20.0.0/16 through a VPC peering connection but traffic for the single address 10.20.5.10 through a Site-to-Site VPN connection. Which configuration achieves this?`,correct:[`Add both routes to the route table; the more specific /32 route is used for 10.20.5.10`,`AWS directs traffic using the most specific route that matches, so the /32 host route wins over the broader /16 route.`],wrong:[[`Add both routes and place the VPN route first, because routes are evaluated from the top down`,`Route order is not what decides the path; the most specific matching route is used.`],[`Keep only the /32 VPN route, because it replaces the broader peering route for the whole range`,`The other addresses in 10.20.0.0/16 would then have no route to the peering connection.`],[`Add the /32 rule to the network ACL of the subnet instead of the route table`,`A network ACL allows or denies traffic and does not choose a route target.`]],slot:3,evidence:[`vpc-route-priority|In general, we direct traffic using the most specific route that matches the traffic.`,`vpc-route-priority|Longest prefix (for example, 10.10.2.15/32 has priority over 10.10.2.0/24)`]}),t({id:`grid-planning-office-006`,building:`grid-planning-office`,bullets:[`3.4-S1`],d:1,stem:`A company is designing a three-tier web application across two Availability Zones. Only the web tier must accept connections from the internet, and the application and database tiers must be protected from direct internet access. Which subnet layout BEST meets these requirements?`,correct:[`Web tier in public subnets; application and database tiers in private subnets, one of each type per Availability Zone`,`Resources in a public subnet can access the public internet, while private subnets have no direct route to an internet gateway and protect the other tiers.`],wrong:[[`All three tiers in public subnets, with security groups restricting inbound access to the application and database tiers`,`The application and database tiers would sit in subnets with a direct route to the internet, which AWS recommends avoiding in favor of private subnets.`],[`All three tiers in private subnets, with a NAT gateway providing the connectivity to and from the internet for clients`,`A NAT gateway allows outbound connections only, so external clients could not start connections to the web tier.`],[`Web and application tiers in public subnets, and only the database tier in a private subnet in each Availability Zone`,`The application tier would be exposed to direct internet access, which the requirement rules out.`]],slot:0,evidence:[`vpc-subnets|Public subnet – The subnet has a direct route to an internet gateway.`,`vpc-subnets|To protect your AWS resources, we recommend that you use private subnets.`,`vpc-nat-gateway|You can use a NAT gateway so that instances in a private subnet can connect to services outside your VPC but external services can't initiate a connection with those instances.`]}),t({id:`grid-planning-office-007`,building:`grid-planning-office`,bullets:[`3.4-S1`],d:2,tags:[`trap:peering-tgw-privatelink`],stem:`VPC A is peered with VPC B and with VPC C. A new requirement says VPC B and VPC C must also communicate, and the company expects to add 20 more VPCs this year. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Attach all of the VPCs to an AWS Transit Gateway and route between them through it`,`A transit gateway acts as a hub, so each VPC connects once and new VPCs simply attach, unlike a mesh of peering connections.`],wrong:[[`Route traffic from VPC B to VPC C through VPC A over the existing peering connections`,`VPC peering does not support transitive peering relationships, so traffic cannot pass through VPC A.`],[`Create a peering connection between every pair of VPCs as new ones are added`,`It works for B and C, but each pair needs its own connection, so the number of connections to manage keeps growing with every new VPC.`],[`Create AWS PrivateLink endpoints in each VPC for every other VPC's workloads`,`PrivateLink exposes specific services rather than routing the networks, so it is not general VPC-to-VPC connectivity.`]],slot:1,evidence:[`peering-basics|VPC peering does not support transitive peering relationships.`,`peering-basics|If you want to enable routing of traffic between VPC B and VPC C, you must create a unique VPC peering connection between them.`,`connectivity-tgw|With a large number of VPCs, Transit Gateway provides simpler VPC-to-VPC communication management over VPC Peering, as shown in the following figure.`]}),e({id:`grid-planning-office-008`,building:`grid-planning-office`,bullets:[`3.4-S1`],d:2,tags:[`trap:peering-tgw-privatelink`],stem:`A company wants one central hub that connects 30 VPCs in a Region with its on-premises data center, without building a mesh of individual connections. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create an AWS Transit Gateway and attach each VPC to it`,`A transit gateway is a network transit hub that interconnects VPCs, so each VPC attaches once instead of connecting to every other VPC.`],[`Attach the on-premises network to the same transit gateway with a Site-to-Site VPN connection or a Direct Connect gateway`,`A transit gateway also interconnects on-premises networks, and VPN connections and Direct Connect gateways can be attached to it.`]],wrong:[[`Create a VPC peering connection between each pair of VPCs`,`This is the mesh the company wants to avoid, and peered VPCs cannot reach each other through a third VPC.`],[`Create a separate Site-to-Site VPN connection from the data center to each VPC`,`It would need 30 separate connections instead of one hub attachment for the on-premises network.`],[`Create AWS PrivateLink interface endpoints in all 30 VPCs for every other VPC`,`PrivateLink gives access to specific services and does not interconnect networks in a hub-and-spoke design.`]],slots:[2,4],evidence:[`tgw-what-is|AWS Transit Gateway is a network transit hub used to interconnect virtual private clouds (VPCs) and on-premises networks.`,`tgw-what-is|A VPN connection to a transit gateway`,`tgw-what-is|An AWS Direct Connect gateway`]}),e({id:`grid-planning-office-009`,building:`grid-planning-office`,bullets:[`3.4-S1`],d:3,tags:[`trap:peering-tgw-privatelink`],stem:`A company connects production and non-production VPCs through one AWS Transit Gateway. Production VPCs must reach each other and shared services, but production and non-production VPCs must not be able to communicate with each other. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create separate transit gateway route tables for production and non-production traffic`,`Several route tables within the same transit gateway segment the traffic into separate routing domains.`],[`Associate each attachment with the route table of its own domain and propagate routes only to that table`,`Each attachment is associated with exactly one route table, so the associations and propagations keep the domains from learning each other's routes.`]],wrong:[[`Associate every attachment with the default transit gateway route table`,`By default attachments share the default route table, so production and non-production VPCs could all reach each other.`],[`Create VPC peering connections between every production and non-production VPC pair for monitoring`,`The requirement is that these two groups must not communicate, and peering would create exactly that path.`],[`Create AWS PrivateLink interface endpoints in each VPC to reach shared services`,`PrivateLink provides access to specific services; it does not segment a transit gateway's routing domains.`]],slots:[1,3],evidence:[`connectivity-tgw|You can take advantage of several Transit Gateway route tables, associations, and propagations to segment your traffic within the same Transit Gateway.`,`tgw-what-is|Each attachment is associated with exactly one route table.`,`tgw-what-is|By default, transit gateway attachments are associated with the default transit gateway route table.`]}),t({id:`grid-planning-office-010`,building:`grid-planning-office`,bullets:[`3.4-S1`],d:1,tags:[`trap:peering-tgw-privatelink`,`mock-reserve`],stem:`A company hosts one internal billing service in its own VPC and wants teams in other VPCs and AWS accounts to reach only that service privately, without gaining access to the rest of its network. Which solution provides the LEAST network exposure?`,correct:[`AWS PrivateLink, with the service published as an endpoint service and consumers using VPC endpoints`,`PrivateLink controls the specific services reachable from a VPC and works across VPC and account boundaries without exposing the network.`],wrong:[[`A VPC peering connection between the billing VPC and each consumer VPC in the other accounts`,`Peering routes between the whole VPC address ranges, so consumers could reach far more than the one service.`],[`An AWS Transit Gateway with every consumer VPC and the billing VPC attached as spokes to it`,`A transit gateway interconnects the networks, which gives consumers network-level reach beyond the one service.`],[`Share the billing VPC subnets with each consumer account by using AWS Resource Access Manager`,`Sharing subnets puts consumer resources inside the billing network itself, which gives network-level reach and not access to just the one service.`]],slot:2,evidence:[`privatelink-what-is|Therefore, you control the specific API endpoints, sites, services, and resources that are reachable from your VPC.`,`privatelink-what-is|You can create AWS PrivateLink-based VPC endpoints to access services, resources, and network segments across VPC and account boundaries.`]}),t({id:`grid-planning-office-011`,building:`grid-planning-office`,bullets:[`3.4-S1`,`3.4-S2`],d:3,tags:[`trap:peering-tgw-privatelink`],stem:`A company has 20 VPCs in one Region and 20 in a second Region. All 40 VPCs must communicate privately over the AWS network, and the company does not want to maintain a full mesh of connections. Which solution BEST meets these requirements?`,correct:[`Create a transit gateway in each Region, attach the VPCs, and connect the gateways with a peering attachment`,`Transit gateways can be peered inter-Region, each VPC attaches once, and static routes in the transit gateway route tables point to the peering attachment.`],wrong:[[`Create an inter-Region VPC peering connection between every pair of VPCs that must communicate in the two Regions`,`Peering connections are one-to-one and not transitive, so all pairs would need their own connection, which is the mesh the company wants to avoid.`],[`Create PrivateLink interface endpoints in every VPC for every other VPC's workloads across both Regions`,`PrivateLink provides access to specific services and does not give network-level connectivity between 40 VPCs.`],[`Run software VPN appliances in each VPC and connect every pair of VPCs across the two Regions over the internet`,`Each pair would again need its own tunnel, which is the full mesh the company wants to avoid, and the traffic crosses the internet instead of the AWS network.`]],slot:3,evidence:[`tgw-peering|You can peer both intra-Region and inter-Region transit gateways, and route traffic between them, which includes IPv4 and IPv6 traffic.`,`tgw-peering|To route traffic between the transit gateways, add a static route to the transit gateway route table that points to the transit gateway peering attachment.`,`peering-basics|A VPC peering connection is a one to one relationship between two VPCs.`]}),t({id:`grid-planning-office-012`,building:`grid-planning-office`,bullets:[`3.4-S2`],d:2,stem:`A company is creating a VPC for a platform that is expected to grow from hundreds to many thousands of EC2 instances across public and private subnets in three Availability Zones over several years. The team wants to avoid rework of the address space. Which IPv4 CIDR block size for the VPC is the BEST starting choice?`,correct:[`A /16 block, the largest allowed, with 65,536 addresses`,`A /16 provides 65,536 addresses, the upper end of the allowed range, which leaves the most room to add subnets as the platform grows.`],wrong:[[`A /28 block, the smallest size allowed, with 16 addresses`,`A /28 provides only 16 addresses, which could not hold the subnets the platform needs even at launch.`],[`A /24 block, with 256 addresses`,`A /24 would be exhausted by subnets and reserved addresses long before the platform reaches many thousands of instances.`],[`A /12 block, with a much larger address count`,`The allowed IPv4 block size for a VPC is between /16 and /28, so a /12 block cannot be created.`]],slot:0,evidence:[`vpc-cidr-blocks|The allowed block size is between a /16 netmask (65,536 IP addresses) and /28 netmask (16 IP addresses).`,`vpc-subnet-sizing|The first four IP addresses and the last IP address in each subnet CIDR block are not available for your use, and they cannot be assigned to a resource, such as an EC2 instance.`]}),t({id:`grid-planning-office-013`,building:`grid-planning-office`,bullets:[`3.4-S2`,`3.4-S1`],d:3,stem:`A company attached a VPC that spans three Availability Zones to an AWS Transit Gateway, enabling subnets in only two of the zones. Instances in the third zone cannot reach the other attached networks. What is the SIMPLEST fix?`,correct:[`Enable the third Availability Zone for the attachment by specifying one subnet in it`,`Resources in a zone can reach the transit gateway only if a subnet is enabled in that zone for the attachment.`],wrong:[[`Associate the attachment with an additional transit gateway route table`,`Route table association controls which routes the attachment uses; it does not make the zone reach the transit gateway.`],[`Create a VPC peering connection between the third zone's subnets and the transit gateway`,`Peering connects two VPCs and is not a way to extend a transit gateway attachment to another zone.`],[`Add a route for 0.0.0.0/0 to a NAT gateway in the third zone's route table`,`A NAT gateway provides outbound internet access and does not carry traffic to a transit gateway attachment.`]],slot:1,evidence:[`tgw-how|During attachment creation, resources within a particular Availability Zone can reach a transit gateway only if a subnet is enabled within the same zone.`,`tgw-how|However, only resources that reside in Availability Zones where there is a transit gateway attachment can reach the transit gateway.`,`tgw-how|To enable each Availability Zone, you specify exactly one subnet.`]}),t({id:`grid-planning-office-014`,building:`grid-planning-office`,bullets:[`3.4-S2`,`3.4-K2`],d:2,tags:[`trap:peering-tgw-privatelink`],stem:`A company's VPC uses 10.0.0.0/16. The company plans to peer VPCs with a partner that uses 10.1.0.0/16 and an acquired business that uses 10.2.0.0/16. It is about to create a new VPC that must later be peered with all three. Which CIDR block for the new VPC BEST avoids rework?`,correct:[`10.3.0.0/16`,`It overlaps none of the three existing ranges, so a peering connection can later be created to each of them.`],wrong:[[`10.0.128.0/17`,`It lies inside 10.0.0.0/16, and peering is not possible between VPCs with overlapping CIDR blocks.`],[`10.1.64.0/18`,`It lies inside the partner's 10.1.0.0/16, so a peering connection with the partner could not be created.`],[`10.2.0.0/16`,`It matches the acquired business's range exactly, and VPCs with matching CIDR blocks cannot be peered.`]],slot:2,evidence:[`peering-basics|You cannot create a VPC peering connection between VPCs that have matching or overlapping IPv4 or IPv6 CIDR blocks.`,`peering-basics|If you have multiple IPv4 CIDR blocks, you can't create a VPC peering connection if any of the CIDR blocks overlap, even if you intend to use only the non-overlapping CIDR blocks or only IPv6 CIDR blocks.`]})],f=[t({id:`ingestion-gate-001`,building:`ingestion-gate`,bullets:[`3.5-K5`],d:1,tags:[`trap:gateway-vs-interface-endpoints`],stem:`Producers run on Amazon EC2 instances in private subnets that have no route to an internet gateway or NAT device. They must send records to an Amazon Kinesis data stream without the traffic leaving the Amazon network. Which solution BEST meets these requirements?`,correct:[`Create an interface VPC endpoint for Kinesis Data Streams in the VPC`,`An interface endpoint is powered by AWS PrivateLink and keeps traffic on the Amazon network, with no internet gateway or NAT device needed.`],wrong:[[`Create a gateway VPC endpoint and add it as a target in the private subnets' route tables`,`The gateway endpoint is the route table target described for Amazon S3 traffic, not the endpoint type that Kinesis Data Streams uses.`],[`Place a NAT gateway in a public subnet and route the private subnets' traffic to the stream through it`,`This sends the traffic out through an internet gateway, and the instances have no route to one.`],[`Assign Elastic IP addresses to the instances and let them reach the stream's public endpoint`,`This requires an internet gateway route and sends the traffic over the public internet.`]],slot:0,evidence:[`kinesis-vpc|You can use an interface VPC endpoint to prevent traffic between your Amazon VPC and Kinesis Data Streams from leaving the Amazon network.`,`kinesis-vpc|Interface VPC endpoints don't require an internet gateway, NAT device, VPN connection, or Direct Connect connection.`,`vpce-gateway-s3|After you create the gateway endpoint, you can add it as a target in your route table for traffic destined from your VPC to Amazon S3.`]}),t({id:`ingestion-gate-002`,building:`ingestion-gate`,bullets:[`3.5-K5`],d:3,stem:`A company reaches an Amazon Kinesis data stream through an interface VPC endpoint. The security team wants the payments stream to be writable only through that endpoint, even if a producer role's credentials are used from elsewhere. Which solution BEST meets these requirements?`,correct:[`Attach an IAM policy to the producer roles that restricts access to occur only through the specified VPC endpoint`,`Policies can use additional fields to restrict access to occur only through a specified VPC endpoint, so credentials used elsewhere are denied.`],wrong:[[`Add an outbound rule to the producers' security group that allows HTTPS only to the stream`,`A security group filters by protocol and address, and it cannot name one stream or stop the credentials being used elsewhere.`],[`Add a network ACL rule on the producers' subnet that denies all traffic that is not HTTPS`,`The network ACL applies only to traffic in that subnet, so credentials used from another network are not restricted.`],[`Encrypt the stream with an AWS KMS key whose key policy allows only the producer roles`,`The key policy controls use of the key for encryption, not the network path that API calls to the stream arrive through.`]],slot:1,evidence:[`kinesis-vpc|VPC endpoint policies let you control access by either attaching a policy to a VPC endpoint or by using additional fields in a policy that is attached to an IAM user, group, or role to restrict access to occur only through the specified VPC endpoint.`,`kinesis-vpc|Use these policies to restrict access to specific streams to a specified VPC endpoint when using them together with the IAM policies to grant only access to Kinesis data stream actions through the specified VPC endpoint.`]}),t({id:`ingestion-gate-003`,building:`ingestion-gate`,bullets:[`3.5-K5`],d:2,stem:`Java producers on Amazon EC2 instances send data to an Amazon MSK cluster. The company wants to authenticate each producer with its instance role and to allow or deny Apache Kafka actions with IAM policies, without issuing and rotating client certificates. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Enable IAM access control on the MSK cluster and give each producer an IAM role with Kafka permissions`,`IAM can authenticate clients and allow or deny Apache Kafka actions, so no client certificates are issued.`],wrong:[[`Enable mutual TLS client authentication and issue a client certificate to each producer`,`Mutual TLS needs an AWS Private CA and per-client certificates, which the company does not want to issue and rotate.`],[`Enable SASL/SCRAM client authentication and manage the user credentials for each producer`,`SASL/SCRAM authenticates clients with credentials and uses Kafka ACLs, so the actions are not allowed or denied by IAM policies.`],[`Leave client authentication off and restrict the brokers to the producers' security group`,`Producers would not be authenticated, so IAM policies could not allow or deny Kafka actions per role.`]],slot:2,evidence:[`msk-clientauth|You can use IAM to authenticate clients and to allow or deny Apache Kafka actions.`,`msk-clientauth|Alternatively, you can use TLS or SASL/SCRAM to authenticate clients, and Apache Kafka ACLs to allow or deny actions.`,`msk-mtls|To use client authentication, you need an AWS Private CA.`]}),e({id:`ingestion-gate-004`,building:`ingestion-gate`,bullets:[`3.5-K5`],d:3,stem:`A company creates an Amazon MSK cluster for payment events. Data must be encrypted at rest with an AWS KMS key that the company specifies, and all client-to-broker communication must be encrypted in transit. Which TWO actions BEST meet these requirements? (Choose two.)`,correct:[[`Specify the AWS KMS key for MSK to use for encryption at rest when creating the cluster`,`MSK integrates with AWS KMS, and you can specify the key to encrypt data at rest when you create the cluster.`],[`Set client-broker encryption to allow only TLS encrypted data`,`This setting rejects plaintext communication between clients and brokers, so all of it is encrypted in transit.`]],wrong:[[`Set client-broker encryption to allow both plaintext and TLS encrypted data`,`Clients could still connect over plaintext, so not all client-to-broker traffic is encrypted.`],[`Set client-broker encryption to allow only plaintext data and encrypt the payload in each producer`,`Plaintext communication between clients and brokers is allowed, so the connection is not encrypted in transit.`],[`Configure Apache Kafka ACLs so that only the payment producers may write to the topics`,`ACLs allow or deny Kafka actions and do not encrypt the data in transit or at rest.`]],slots:[0,4],evidence:[`msk-encryption|When you create an MSK cluster, you can specify the AWS KMS key that you want Amazon MSK to use to encrypt your data at rest.`,`msk-encryption|For communication between clients and brokers, you must specify one of the following three settings: Only allow TLS encrypted data.`,`msk-encryption|Allow both plaintext, as well as TLS encrypted data.Only allow plaintext data.`]}),e({id:`ingestion-gate-005`,building:`ingestion-gate`,bullets:[`3.5-K5`,`3.5-S6`],d:2,stem:`A company runs an AWS Transfer Family SFTP server for partners who connect over the internet from known office networks. Partners need fixed server IP addresses for their firewalls, and the company must accept requests only from the partners' allowed addresses. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Host the endpoint in a VPC, make it internet-facing, and associate Elastic IP addresses with it`,`An internet-facing VPC endpoint can have Elastic IP addresses, which gives the partners fixed addresses.`],[`Attach VPC security groups that allow only the partners' address ranges`,`VPC security groups control access to authenticated users whose requests originate only from allowed addresses.`]],wrong:[[`Configure the endpoint for internal access so that it is reachable only by clients using its private IP addresses`,`Internal access makes the endpoint available only through its private IP addresses, so partners on the internet cannot reach it.`],[`Place a Network Load Balancer in front of the server to filter the partners' source addresses`,`AWS advises avoiding Network Load Balancers in front of Transfer Family servers, and they add a component to operate.`],[`Leave the endpoint open to all addresses and rely on SFTP credentials alone for access`,`Requests from addresses outside the partners' networks would still reach the server, which breaks the address restriction.`]],slots:[1,2],evidence:[`transfer-vpc|In addition, if you choose to make your server's endpoint internet-facing, you can associate Elastic IP addresses with your endpoint.`,`transfer-vpc|You can use VPC security groups to control access to authenticated users whose requests originate only from allowed addresses.`,`transfer-vpc|For Access, choose Internal to make your endpoint only accessible to clients using the endpoint's private IP addresses.`,`transfer-ftp|For important considerations about Network Load Balancers, see Avoid placing NLBs and NATs in front of AWS Transfer Family servers.`]}),t({id:`ingestion-gate-006`,building:`ingestion-gate`,bullets:[`3.5-S6`],d:2,stem:`A company is creating an Amazon Data Firehose stream that will deliver JSON events that contain a customer_id field to Amazon S3. Analysts query one customer at a time with Amazon Athena, and the company wants the events grouped into separate S3 prefixes by customer_id as they are delivered, without writing consumer code. Which configuration meets these requirements?`,correct:[`Turn on dynamic partitioning when the delivery stream is created and use customer_id as the partitioning key`,`Dynamic partitioning groups the in-transit data by keys inside the data and delivers it to individual S3 prefixes by key.`],wrong:[[`Increase the buffer size of the delivery stream`,`Larger buffers make bigger objects but do not group the events by customer_id into separate prefixes.`],[`Create a separate delivery stream for each customer and send each customer's events to its own stream`,`This multiplies the streams to create and manage, and the producers would have to route every event.`],[`Set a custom S3 bucket prefix on the delivery stream that is based on the delivery date`,`A date-based prefix groups the events by time and not by customer_id.`]],slot:3,evidence:[`firehose-partition|Dynamic partitioning enables you to continuously partition streaming data in Firehose by using keys within data (for example, customer_id or transaction_id) and then deliver the data grouped by these keys into corresponding Amazon Simple Storage Service (Amazon S3) prefixes.`,`firehose-partition|With dynamic partitioning, Firehose continuously groups in-transit data using dynamically or statically defined data keys, and delivers the data to individual Amazon S3 prefixes by key.`,`firehose-partition-enable|You can enable dynamic partitioning only when you create a new Firehose stream.`]}),t({id:`ingestion-gate-007`,building:`ingestion-gate`,bullets:[`3.5-S6`],d:1,stem:`An Amazon Data Firehose stream delivers application logs to Amazon S3 and creates a very large number of tiny objects. The company wants fewer, larger objects with the LEAST change to the pipeline. What should the company do?`,correct:[`Increase the buffer size and buffer interval of the Firehose stream`,`Firehose buffers incoming data to a certain size or for a certain period of time before delivering it, so larger buffers produce larger objects.`],wrong:[[`Decrease the buffer interval of the Firehose stream to a few seconds`,`A shorter interval delivers data more often, which produces more and smaller objects.`],[`Replace Firehose with a Kinesis data stream and a custom consumer that writes to S3`,`The consumer would be new code to build and run, which is more than the LEAST change to the pipeline.`],[`Enable Amazon S3 Versioning on the destination bucket so that objects are combined`,`Versioning keeps multiple versions of objects and does not combine objects.`]],slot:0,evidence:[`firehose|Amazon Data Firehose buffers incoming streaming data to a certain size or for a certain period of time before delivering it to destinations.`,`firehose|Buffer Size is in MBs and Buffer Interval is in seconds.`]}),t({id:`ingestion-gate-008`,building:`ingestion-gate`,bullets:[`3.5-S6`],d:2,stem:`Thousands of sensors each send a tiny reading as its own record to a provisioned Amazon Kinesis data stream. The bytes written are far below what the shards accept, but the shards are throttled because of the number of records per second. The company wants to stop the throttling without adding shards or changing the sensors. Which configuration meets these requirements?`,correct:[`Have the producer application use the Kinesis Producer Library aggregation to store many readings in each stream record`,`Aggregation stores multiple records in a single Kinesis Data Streams record, which raises the number of records sent per API call and producer throughput.`],wrong:[[`Register the consumers as enhanced fan-out consumers to get dedicated read throughput`,`Enhanced fan-out gives each consumer its own read throughput allotment, so it changes read capacity for consumers and does not change the number of records written per second.`],[`Increase the retention period of the stream to seven days so that throttled records are kept`,`The retention period is the length of time that data records are accessible after they are added to the stream, so it does not reduce the number of records written per second.`],[`Compress each reading with gzip before the producer sends it as its own record`,`Compression shrinks the bytes of each record, but the number of records per second stays the same, and bytes are not the limit.`]],slot:1,evidence:[`kinesis-kpl|The KPL supports two types of batching: Aggregation – Storing multiple records within a single Kinesis Data Streams record.`,`kinesis-kpl|Aggregation allows customers to increase the number of records sent per API call, which effectively increases producer throughput.`,`kinesis-concepts|Each shard can support up to 5 transactions per second for reads, up to a maximum total data read rate of 2 MB per second and up to 1,000 records per second for writes, up to a maximum total data write rate of 1 MB per second (including partition keys).`,`kinesis-consumers|When a consumer uses enhanced fan-out, it gets its own 2 MB/sec allotment of read throughput, allowing multiple consumers to read data from the same stream in parallel, without contending for read throughput with other consumers.`,`kinesis-concepts|The retention period is the length of time that data records are accessible after they are added to the stream.`]}),t({id:`ingestion-gate-009`,building:`ingestion-gate`,bullets:[`3.5-K5`],d:2,tags:[`mock-reserve`],stem:`A healthcare company sends patient events to an Amazon Kinesis data stream. Compliance requires that the data be encrypted at rest inside the stream with AWS KMS keys, and the company wants the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Enable server-side encryption on the Kinesis data stream and select an AWS KMS key`,`Server-side encryption with AWS KMS keys encrypts the data at rest within Kinesis Data Streams, with no application changes.`],wrong:[[`Encrypt each record in the producers with a custom library and store the keys in the application`,`This adds code and key handling to every producer, which is more overhead than a built-in server-side option.`],[`Enable default encryption on the Amazon S3 bucket that receives the data from the stream`,`This encrypts the objects in S3 after delivery and does not encrypt the data at rest inside the stream.`],[`Place the producers in private subnets and use an interface VPC endpoint for the stream`,`The endpoint protects the network path, but it does not encrypt the data at rest within the stream.`]],slot:2,evidence:[`kinesis-sse|Server-side encryption using AWS Key Management Service (AWS KMS) keys makes it easy for you to meet strict data management requirements by encrypting your data at rest within Amazon Kinesis Data Streams.`,`kinesis-vpc|You can use an interface VPC endpoint to prevent traffic between your Amazon VPC and Kinesis Data Streams from leaving the Amazon network.`]})],p=[t({id:`read-replica-annex-001`,building:`read-replica-annex`,bullets:[`3.3-K7`],d:1,tags:[`trap:multi-az-vs-read-replicas`],stem:`A company runs Amazon RDS for MySQL in one Availability Zone. The database must survive the loss of that Availability Zone with automatic failover and no administrator action, and every committed transaction must already exist on the secondary copy. Which solution BEST meets these requirements?`,correct:[`Convert the database to a Multi-AZ DB instance deployment`,`A Multi-AZ deployment keeps a synchronous standby in a different Availability Zone and RDS fails over to it automatically without administrative intervention.`],wrong:[[`Create a read replica in a second Availability Zone and promote it when the primary fails`,`Read replicas are updated asynchronously, so a replica can lag behind committed transactions, and promotion is a step the administrator takes.`],[`Schedule frequent manual DB snapshots and restore the most recent snapshot after a failure`,`A restore takes administrator action and loses every transaction committed after the last snapshot.`],[`Create a read replica in another Region and send the application there when the primary is down`,`Asynchronous replication can lag, so transactions can be lost, and the switch to the replica is a manual promotion rather than an automatic failover.`]],slot:2,evidence:[`rds-multi-az-instance|In a Multi-AZ DB instance deployment, Amazon RDS automatically provisions and maintains a synchronous standby replica in a different Availability Zone.`,`rds-failover|Amazon RDS handles failovers automatically so you can resume database operations as quickly as possible without administrative intervention.`,`rds-read-replicas|When you make updates to the primary DB instance, Amazon RDS copies them asynchronously to the read replica.`]}),t({id:`read-replica-annex-002`,building:`read-replica-annex`,bullets:[`3.3-S1`],d:1,tags:[`trap:multi-az-vs-read-replicas`],stem:`Analysts run long reporting queries on the production Amazon RDS for PostgreSQL primary instance, and the web application slows down while they run. The reports can tolerate data that is a little behind. The company wants to move the reporting load off the primary with the LEAST change. Which solution meets these requirements?`,correct:[`Create a read replica and point the reporting tool at the replica`,`Reporting queries can run against a read replica instead of the production DB instance, which reduces the load on the primary.`],wrong:[[`Convert the database to a Multi-AZ DB instance deployment and point the reporting tool at the standby`,`The standby of a Multi-AZ DB instance deployment cannot serve read traffic, so the reports could not run there.`],[`Place Amazon RDS Proxy in front of the primary and connect the reporting tool through the proxy`,`The proxy pools connections, but every reporting query still runs on the primary, so the load is not moved.`],[`Increase the allocated storage of the primary DB instance so that the reports have more room`,`More storage does not stop the long reporting queries from competing with the application on the primary instance.`]],slot:0,evidence:[`rds-read-replicas|Business reporting or data warehousing scenarios where you might want business reporting queries to run against a read replica, rather than your production DB instance.`,`rds-multi-az-instance|You can't use a standby replica to serve read traffic.`]}),t({id:`read-replica-annex-003`,building:`read-replica-annex`,bullets:[`3.3-K1`],d:2,tags:[`trap:multi-az-vs-read-replicas`],stem:`A company runs Amazon RDS for MySQL in one Region. A new policy requires a way to recover the database if the entire Region becomes unavailable, and the company must stay on RDS for MySQL. Which solution meets this requirement MOST cost-effectively?`,correct:[`Create a cross-Region read replica and promote it if the primary Region fails`,`A read replica can reside in a different Region, and promoting it to a standalone instance is a documented disaster recovery approach.`],wrong:[[`Enable Multi-AZ so that the standby instance takes over when the primary Region fails`,`The Multi-AZ standby lives in a different Availability Zone of the same Region, so a Region-wide outage affects both copies.`],[`Create a read replica in a different Availability Zone of the same Region`,`The replica sits in the same Region as the primary, so it does not protect against the loss of the Region.`],[`Migrate to Amazon Aurora and build an Aurora global database with a secondary Region`,`It protects against Regional loss, but the company must stay on RDS for MySQL, so the engine change is not allowed.`]],slot:3,evidence:[`rds-read-replicas|In some cases, a read replica resides in a different AWS Region from its primary DB instance.`,`rds-read-replicas|You can promote a read replica to a standalone instance as a disaster recovery solution if the primary DB instance fails.`,`rds-multi-az-instance|In a Multi-AZ DB instance deployment, Amazon RDS automatically provisions and maintains a synchronous standby replica in a different Availability Zone.`]}),t({id:`read-replica-annex-004`,building:`read-replica-annex`,bullets:[`3.3-K1`],d:2,stem:`A company runs an Amazon Aurora PostgreSQL cluster in one Region. Users in two other geographies need low-latency reads from a nearby Region, and the company must be able to resume operations in another Region quickly and with little data loss if the primary Region has an outage. Which solution BEST meets these requirements?`,correct:[`Convert the cluster to an Aurora global database with a secondary cluster in each of the two other Regions`,`Aurora synchronizes changes to secondary clusters in other Regions, which serve local reads and shorten recovery from a Region-wide outage.`],wrong:[[`Add Aurora Replicas in other Availability Zones of the primary Region and use the cluster reader endpoint`,`The replicas stay in the primary Region, so distant users get no local reads and a Region outage takes every copy.`],[`Copy automated snapshots of the cluster to the two other Regions every night and restore them after an outage`,`Restoring a nightly snapshot takes longer and loses far more data than continuous replication, and it gives no local reads.`],[`Run AWS DMS ongoing replication from the cluster into a new Aurora cluster in each of the other Regions`,`The company would build and operate the replication itself, and it does not give the faster recovery that built-in global replication provides.`]],slot:1,evidence:[`aurora-global|Aurora automatically synchronizes all changes made in the primary DB cluster to one or more secondary clusters.`,`aurora-global|Having a full copy of all your data in multiple geographic locations also enables low-latency read operations for applications that connect from widely separated locations around the world.`,`aurora-global|The secondary clusters allow you to make an Aurora Global Database available in a new primary AWS Region more quickly (lower RTO) and with less data loss (lower RPO) than traditional replication solutions.`]}),t({id:`read-replica-annex-005`,building:`read-replica-annex`,bullets:[`3.3-K7`,`3.3-S1`],d:1,stem:`An Amazon Aurora MySQL cluster has one writer and three Aurora Replicas. Reporting sessions connect to the instance endpoint of a single replica, which is overloaded while the other replicas are idle. The company wants read connections spread across all the replicas automatically. Which solution meets this requirement?`,correct:[`Connect the reporting sessions to the reader endpoint of the cluster`,`The reader endpoint performs connection-balancing among all the Aurora Replicas, so no single replica carries all the sessions.`],wrong:[[`Connect the reporting sessions to the cluster endpoint of the Aurora cluster`,`The cluster endpoint connects to the primary instance, so the reports would compete with the writes instead of using the replicas.`],[`Connect the reporting sessions to the instance endpoint of the largest replica in the cluster`,`An instance endpoint points at one specific DB instance, so the sessions would still not be spread across the replicas.`],[`Connect the reporting sessions to the writer endpoint of an Aurora global database`,`The global database writer endpoint always points to the primary DB cluster's writer, which is not a pool of replicas.`]],slot:2,evidence:[`aurora-endpoints|To perform queries, you can connect to the reader endpoint, with Aurora automatically performing connection-balancing among all the Aurora Replicas.`,`aurora-endpoints|Cluster endpoint Connect to the primary instance of your cluster to develop and test applications, and perform transformations like INSERT statements and DDL, DML, and ETL operations.`,`aurora-endpoints|Instance endpoint Examine details about a specific DB instance for diagnosis or tuning.`]}),t({id:`read-replica-annex-006`,building:`read-replica-annex`,bullets:[`3.3-S1`],d:3,stem:`A company runs Amazon RDS for MySQL with several read replicas that the operations team creates and deletes by hand as read traffic changes through the day. The company does not want to pay for idle replicas and can move to another engine in the Aurora family. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Migrate to Amazon Aurora MySQL and use an Aurora Auto Scaling policy for the Aurora Replicas, with the application using the reader endpoint`,`Aurora Auto Scaling adds and removes Aurora Replicas as the workload changes, and the reader endpoint spreads read connections across them.`],wrong:[[`Keep RDS for MySQL and turn on storage autoscaling so that capacity follows the read traffic`,`Storage autoscaling grows allocated storage and does not add or remove read replicas as read demand changes.`],[`Keep RDS for MySQL, convert it to Multi-AZ and let the standby instance absorb the extra read traffic`,`The standby of a Multi-AZ DB instance deployment cannot serve read traffic, so it absorbs none of the reads.`],[`Keep RDS for MySQL and leave enough read replicas running at all times to cover the busiest hour`,`The replicas sit idle outside the busy hour, which breaks the requirement not to pay for idle replicas.`]],slot:0,evidence:[`rds-read-replicas|RDS doesn't support autoscaling of read replicas, which is the automatic add or removing of read replicas as read demand changes.`,`aurora-autoscaling|To meet your connectivity and workload requirements, Aurora Auto Scaling dynamically adjusts the number of Aurora Replicas (reader DB instances) provisioned for an Aurora DB cluster.`,`aurora-autoscaling|When the connectivity or workload decreases, Aurora Auto Scaling removes unnecessary Aurora Replicas so that you don't pay for unused provisioned DB instances.`]}),e({id:`read-replica-annex-007`,building:`read-replica-annex`,bullets:[`3.3-S1`],d:2,tags:[`trap:multi-az-vs-read-replicas`],stem:`A company runs Amazon RDS for PostgreSQL in one Region. The database must fail over automatically to another Availability Zone without administrator action, and nightly reporting queries must stop slowing the production workload. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Enable a Multi-AZ DB instance deployment for the database`,`RDS fails over to the synchronous standby in another Availability Zone automatically without administrative intervention.`],[`Create a read replica and run the reporting queries against it`,`A read replica can be added alongside a Multi-AZ standby and takes the reporting queries off the primary.`]],wrong:[[`Create a read replica in a second Availability Zone and rely on it for the automatic failover`,`Promoting a read replica is a step the administrator takes, so it does not provide automatic failover.`],[`Send the nightly reporting queries to the Multi-AZ standby instance`,`A standby replica cannot serve read traffic, so the reports cannot run there.`],[`Increase the allocated storage of the primary DB instance`,`It neither adds a failover target nor takes the reporting queries off the primary.`]],slots:[1,3],evidence:[`rds-failover|Amazon RDS handles failovers automatically so you can resume database operations as quickly as possible without administrative intervention.`,`rds-read-replicas|You can configure a read replica for a DB instance that also has a standby replica configured for high availability in a Multi-AZ deployment.`,`rds-read-replicas|Unlike a read replica, a standby replica can't serve read traffic.`,`rds-promote|Implementing failure recovery – You can use read replica promotion as a data recovery scheme if the primary DB instance fails.`]}),e({id:`read-replica-annex-008`,building:`read-replica-annex`,bullets:[`3.3-K1`],d:3,stem:`A company runs Amazon Aurora MySQL in one Region with a single writer instance and no replicas. The database must keep running through the loss of one Availability Zone, and it must be recoverable quickly with little data loss if the whole Region becomes unavailable. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Add an Aurora Replica in a different Availability Zone from the writer`,`If the writer becomes unavailable, Aurora promotes a reader in another Availability Zone as the new writer.`],[`Add a secondary cluster in a second Region by using an Aurora global database`,`Changes are synchronized to the secondary Region, which gives fast recovery from an outage that affects the whole Region.`]],wrong:[[`Add a second Aurora Replica in the same Availability Zone as the writer`,`An outage of that Availability Zone removes the writer and both replicas at once.`],[`Take a manual snapshot once a week and copy it to a second Region`,`Restoring a weekly snapshot is slow and loses up to a week of data, which is not quick recovery with little data loss.`],[`Resize the writer to a larger DB instance class in the same Availability Zone`,`A larger instance does not remove the single writer or the single Availability Zone, so neither outage is covered.`]],slots:[0,4],evidence:[`aurora-replication|If the writer instance in a cluster becomes unavailable, Aurora automatically promotes one of the reader instances to take its place as the new writer.`,`aurora-replication|These should be of the same DB instance class as the primary instance and in different Availability Zones for your Aurora DB cluster.`,`aurora-global|This multi-Region configuration provides fast recovery from the rare outage that might affect an entire AWS Region.`]}),t({id:`read-replica-annex-009`,building:`read-replica-annex`,bullets:[`3.3-K7`],d:3,tags:[`trap:multi-az-vs-read-replicas`],stem:`An order-tracking website sends its writes to an Amazon RDS primary DB instance and all of its reads to read replicas. Right after a customer places an order, the confirmation page sometimes does not show the new order. The confirmation page must always show the order, and all other reads should stay on the replicas with the LEAST change. Which solution meets these requirements?`,correct:[`Send the confirmation page's reads to the primary DB instance`,`Updates reach a read replica asynchronously, so the replica can lag, while the primary always holds the newest order.`],wrong:[[`Convert to a Multi-AZ DB instance deployment and read the confirmation page from the standby`,`The standby cannot serve read traffic, so the confirmation page could not be read from it.`],[`Add more read replicas in other Availability Zones so that one of them is always current`,`Every replica is updated asynchronously, so each one can lag, and extra replicas do not remove the delay.`],[`Place an Amazon ElastiCache cache in front of the read replicas for the confirmation page`,`A cache fills from the replicas, so it can return the same old data and gives no guarantee that the new order is shown.`]],slot:3,evidence:[`rds-read-replicas|Amazon RDS then uses the asynchronous replication method for the DB engine to update the read replica whenever there is a change to the primary DB instance.`,`rds-read-replicas|Clients have read/write access to the primary DB instance and read-only access to the replica.`,`rds-multi-az-instance|You can't use a standby replica to serve read traffic.`]}),t({id:`read-replica-annex-010`,building:`read-replica-annex`,bullets:[`3.3-K1`,`3.3-S1`],d:2,stem:`A company runs Amazon RDS for MySQL in us-east-1. Customers in Europe read product data and report slow page loads. Product updates come only from an admin tool in the United States and may reach Europe a little late. The company wants to cut read latency for European users and keep using RDS for MySQL. Which solution BEST meets these requirements?`,correct:[`Create a cross-Region read replica in a European Region and point the European application servers at it for reads`,`A read replica can sit in a different Region from its primary and takes read-only connections, so European reads stay local.`],wrong:[[`Enable Multi-AZ and place the standby instance in a European Region`,`A Multi-AZ standby is placed in a different Availability Zone of the same Region, and it cannot serve reads either way.`],[`Create a read replica in a second Availability Zone of us-east-1 and use it for the European reads`,`The replica is still in the United States, so European users keep the same distance and latency.`],[`Increase the DB instance class of the primary in us-east-1 so that it answers queries faster`,`A larger instance speeds up processing but cannot remove the network distance to the European users.`]],slot:1,evidence:[`rds-read-replicas|In some cases, a read replica resides in a different AWS Region from its primary DB instance.`,`rds-read-replicas|The read replica operates as a DB instance that allows only read-only connections.`,`rds-multi-az-instance|In a Multi-AZ DB instance deployment, Amazon RDS automatically provisions and maintains a synchronous standby replica in a different Availability Zone.`]}),t({id:`read-replica-annex-011`,building:`read-replica-annex`,bullets:[`3.3-K7`],d:2,tags:[`trap:multi-az-vs-read-replicas`],stem:`A company runs Amazon RDS for MySQL in one Region and needs automatic failover to another Availability Zone. It also wants to send read-only queries to the standby copies of the data, without creating and managing separate read replica instances. Which solution BEST meets these requirements?`,correct:[`Use a Multi-AZ DB cluster deployment with two readable standby DB instances`,`A Multi-AZ DB cluster has standby DB instances that provide failover support and can also serve read traffic.`],wrong:[[`Use a Multi-AZ DB instance deployment and send the read-only queries to its standby`,`The single standby of a Multi-AZ DB instance deployment provides failover only and does not serve read traffic.`],[`Use a Multi-AZ DB instance deployment together with a separate cross-Region read replica for the queries`,`It needs a separate read replica instance that the company would have to create and manage, which it wants to avoid.`],[`Use a Single-AZ DB instance with Provisioned IOPS storage and a larger instance class`,`There is no standby copy in another Availability Zone, so there is no automatic failover and no standby to read from.`]],slot:2,evidence:[`rds-multi-az|A Multi-AZ DB cluster deployment has standby DB instances that provide failover support and can also serve read traffic.`,`rds-multi-az|A Multi-AZ DB instance deployment has one standby DB instance that provides failover support, but doesn't serve read traffic.`]}),e({id:`read-replica-annex-012`,building:`read-replica-annex`,bullets:[`3.3-S1`],d:2,tags:[`mock-reserve`,`trap:multi-az-vs-read-replicas`],stem:`The primary Amazon RDS for MySQL DB instance in us-east-1 is unavailable during a Regional outage. The company had created a cross-Region read replica in us-west-2 for disaster recovery. Which THREE actions restore service from the replica? (Choose three.)`,correct:[[`Promote the read replica to a standalone DB instance`,`Promoting the replica makes it a standalone instance, which is the documented recovery step when the primary fails.`],[`Direct database traffic to the promoted DB instance`,`The application must be pointed at the promoted instance, because nothing switches the traffic for you.`],[`Create a replacement read replica that uses the promoted DB instance as its source`,`It restores a replica for reads and recovery after the promotion.`]],wrong:[[`Wait for RDS to fail the Multi-AZ standby over to us-west-2 automatically`,`A Multi-AZ standby is in another Availability Zone of the same Region, not in us-west-2.`],[`Restore the latest automated backup of the primary into us-east-1`,`The Region of the primary is unavailable, so a restore there cannot complete, and the replica already holds the data.`],[`Reboot the primary DB instance with the failover option to move to the standby`,`The primary is unavailable, and a Multi-AZ failover only moves within the unavailable Region.`]],slots:[0,2,5],evidence:[`rds-promote|Implementing failure recovery – You can use read replica promotion as a data recovery scheme if the primary DB instance fails.`,`rds-promote|Promote the read replica.`,`rds-promote|Direct database traffic to the promoted DB instance.`,`rds-promote|Create a replacement read replica with the promoted DB instance as its source.`]}),t({id:`read-replica-annex-013`,building:`read-replica-annex`,bullets:[`3.3-K1`],d:3,tags:[`mock-reserve`],stem:`A company runs an Amazon Aurora global database with its primary cluster in us-east-1 and a secondary cluster in eu-west-1. A reporting application in Europe runs read-only queries and must read from a nearby Region with low latency. Replication lag from the primary Region is acceptable if it is typically under a second. Which approach meets these requirements?`,correct:[`Connect the reporting application to the reader endpoint of the secondary cluster in eu-west-1`,`A secondary cluster is a read-only copy kept up to date by Aurora replication, so reads stay in the nearby Region.`],wrong:[[`Connect the reporting application to the writer endpoint of the primary cluster in us-east-1`,`Every query would cross the Atlantic, which defeats the low-latency requirement and loads the primary cluster.`],[`Restore a new Aurora cluster in eu-west-1 from a snapshot every night and query it`,`A restored snapshot misses everything written after it was taken and adds a nightly restore to operate.`],[`Add Aurora Replicas to the primary cluster in us-east-1 and query them from Europe`,`The replicas are still in us-east-1, so reads from Europe keep the cross-Region latency.`]],slot:0,evidence:[`aurora-global|An Aurora global database consists of one primary AWS Region where your data is written, and up to 10 read-only secondary AWS Regions.`,`aurora-global|After any write operation, Aurora replicates data to the secondary AWS Regions using dedicated infrastructure, with latency typically under a second.`,`aurora-global|Having a full copy of all your data in multiple geographic locations also enables low-latency read operations for applications that connect from widely separated locations around the world.`]})],m=[t({id:`refinery-001`,building:`refinery`,bullets:[`3.5-K4`],d:1,stem:`A data engineering team wants to build extract, transform and load (ETL) pipelines for a data lake by composing the transformation steps in a graphical interface instead of writing Spark code. The jobs must run without servers to manage. Which solution meets these requirements with the LEAST operational effort?`,correct:[`AWS Glue Studio, to visually create jobs that run on the serverless Apache Spark-based ETL engine in AWS Glue`,`Glue Studio is a graphical interface for creating, running and monitoring Glue jobs, which run on a serverless ETL engine.`],wrong:[[`An Amazon EMR cluster with Apache Spark jobs that the team writes and submits as scripts`,`The team would write Spark code and operate a cluster, and it wants a graphical interface with no servers.`],[`AWS Lambda functions that the team writes for each transformation step and chains together`,`The team would write code for every step, and Lambda has no graphical interface for composing ETL pipelines.`],[`AWS Batch jobs that run containers with the transformation code that the team writes`,`The team would write and package the code itself, and Batch is not a graphical ETL authoring tool.`]],slot:0,evidence:[`glue-what-is|AWS Glue Studio – Provides a graphical interface for you to create and edit your AWS Glue jobs visually.`,`glue-what-is|You can visually compose data transformation workflows and seamlessly run them on the Apache Spark–based serverless ETL engine in AWS Glue.`]}),t({id:`refinery-002`,building:`refinery`,bullets:[`3.5-K4`],d:2,stem:`A retailer publishes clickstream events to an Amazon Kinesis data stream. The company must continuously clean and transform the events and load them into Amazon S3 for analytics, and wants NO clusters or servers to manage. Which solution BEST meets these requirements?`,correct:[`Create an AWS Glue streaming ETL job that reads from the Kinesis data stream and writes the cleaned records to Amazon S3`,`Glue streaming ETL uses continuously running serverless jobs that can ingest from Kinesis Data Streams and load into S3.`],wrong:[[`Run an Apache Spark Structured Streaming application on an Amazon EMR cluster that reads from the stream`,`This can transform the stream, but the company would configure and operate the cluster it wants to avoid.`],[`Schedule Amazon Athena queries every few minutes that read the stream and write the cleaned records to Amazon S3 buckets`,`Athena is a SQL query service over data in S3, and it does not run continuous jobs against a Kinesis stream.`],[`Run an AWS Batch job on a schedule that drains the stream and writes batches of records to Amazon S3`,`Batch runs queued batch workloads, not continuously running stream transformations, so the pipeline would not be continuous.`]],slot:1,evidence:[`glue-components|AWS Glue enables you to perform ETL operations on streaming data using continuously-running jobs.`,`glue-components|AWS Glue streaming ETL is built on the Apache Spark Structured Streaming engine, and can ingest streams from Amazon Kinesis Data Streams, Apache Kafka, and Amazon Managed Streaming for Apache Kafka (Amazon MSK).`,`glue-what-is|It's also serverless, which means there's no infrastructure to manage.`]}),e({id:`refinery-003`,building:`refinery`,bullets:[`3.5-K4`],d:2,stem:`A company runs a nightly ETL job that cleans sales data and writes new files to Amazon S3. Analysts must be able to query the new data with Amazon Athena the next morning, and the company wants NO infrastructure to manage. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create an AWS Glue ETL job and invoke it on a nightly schedule`,`Glue jobs can be invoked on a schedule and run without infrastructure to manage.`],[`Start an AWS Glue crawler from a trigger so that the Data Catalog tables stay current`,`A trigger can start crawlers, and crawlers update the Data Catalog that Athena queries.`]],wrong:[[`Run the transformation on a persistent Amazon EMR cluster that stays up around the clock`,`The cluster is infrastructure that the company must configure and operate, which it wants to avoid.`],[`Ask the analysts to re-create the Athena tables by hand each morning from the new files`,`Manual table creation each day is the operational effort the company is avoiding, and the analysts may miss changes.`],[`Run the job as a standard AWS Lambda function with a 20-minute processing step for each large input file`,`A standard Lambda function times out at 15 minutes at most, so a 20-minute step would time out.`]],slots:[0,3],evidence:[`glue-what-is|Invoke AWS Glue jobs on a schedule, on demand, or based on an event.`,`glue-components|Schedule when crawlers run.`,`glue-triggers|When fired, a trigger can start specified jobs and crawlers.`,`glue-catalog|You can populate the Data Catalog using a crawler, which automatically scans your data sources and extracts metadata.`,`lambda-quotas|Function timeout 900 seconds (15 minutes).`]}),t({id:`refinery-004`,building:`refinery`,bullets:[`3.5-K4`],d:3,stem:`A company loads customer records from several sources into an Amazon S3 data lake. The same customer often appears with slightly different spellings, and the data engineers want built-in deduplication of imperfect matches plus detection of sensitive data in the same serverless pipeline, with the LEAST custom code. Which service BEST meets these requirements?`,correct:[`AWS Glue, using FindMatches for deduplication and sensitive data detection in its ETL jobs`,`Glue provides FindMatches to find records that are imperfect matches and sensitive data detection in the pipeline, in a serverless service.`],wrong:[[`Amazon Athena, using CREATE TABLE AS SELECT queries with SQL string functions to compare similar names`,`CTAS rewrites query results, but the matching logic would be custom SQL written and maintained by the engineers.`],[`AWS Batch, with a containerized job that implements its own matching and scanning logic`,`Batch runs the containers, but the engineers would write all of the matching and detection code themselves.`],[`Amazon EMR, with an Apache Spark application that implements its own matching and scanning logic`,`EMR provides the Spark framework on a managed cluster, but the matching and detection code would be custom and the cluster is something to operate.`]],slot:2,evidence:[`glue-what-is|Deduplicate and cleanse data with built-in machine learning – Clean and prepare your data for analysis without becoming a machine learning expert by using the FindMatches feature.`,`glue-what-is|AWS Glue sensitive data detection lets you define, identify, and process sensitive data in your data pipeline and in your data lake.`]}),t({id:`refinery-005`,building:`refinery`,bullets:[`3.5-S5`],d:2,stem:`A company runs Apache Spark and Apache Hive applications a few times a week on bursts of data. The jobs need very different amounts of capacity each time, and the company does not want to configure, size or operate clusters. Which compute option meets these requirements with the LEAST operational overhead?`,correct:[`Amazon EMR Serverless applications that run the Spark and Hive jobs`,`EMR Serverless provides a runtime for Spark and Hive and determines the resources each job needs, with no clusters to configure or operate.`],wrong:[[`An Amazon EMR cluster on Amazon EC2 instances sized for the largest job and kept running between runs`,`The cluster must be configured, sized and operated, and capacity sized for the largest job sits unused between runs.`],[`AWS Lambda functions that each run a slice of the Spark job and are chained together`,`Lambda is not a Spark or Hive runtime, and a single standard Lambda invocation can run for only up to 15 minutes.`],[`AWS Batch with a compute environment that runs the jobs as containers across Amazon EC2 instances`,`Batch runs containerized batch workloads, not the Spark and Hive frameworks themselves, and its compute environments are infrastructure to define and manage.`]],slot:3,evidence:[`emr-serverless|With EMR Serverless, you don’t have to configure, optimize, secure, or operate clusters to run applications with these frameworks.`,`emr-serverless|EMR Serverless automatically determines the resources that the application needs, gets these resources to process your jobs, and releases the resources when the jobs finish.`,`lambda-quotas|Code can run for up to 15 minutes in a single invocation`]}),t({id:`refinery-006`,building:`refinery`,bullets:[`3.5-S5`],d:2,stem:`A company has a containerized Python program that converts large input files, and each run takes about 45 minutes. Hundreds of files arrive nightly and the program does not use Apache Spark. The company wants managed compute that queues the jobs and provisions resources for them, with the LEAST change to the program. Which solution meets these requirements?`,correct:[`Submit each file as a job to AWS Batch, which runs the container on managed compute`,`Batch runs batch workloads on managed container orchestration and provisions resources in response to submitted jobs, with no change to the program.`],wrong:[[`Invoke a standard AWS Lambda function for each file that runs the conversion program as the function code`,`A standard Lambda function times out at 15 minutes at most, which is shorter than the 45-minute runs.`],[`Rewrite the program as a query and run it with Amazon Athena against the files in Amazon S3`,`Athena runs SQL queries over data in S3, so the Python program would have to be rewritten.`],[`Create an Amazon EMR cluster and port the program to Apache Hadoop MapReduce jobs on the cluster`,`EMR runs big data frameworks such as Hadoop and Spark, so the program would be rewritten and a cluster operated.`]],slot:0,evidence:[`batch-what-is|AWS Batch provides all of the necessary functionality to run high-scale, compute-intensive workloads on top of AWS managed container orchestration services, Amazon ECS and Amazon EKS.`,`batch-what-is|This service can efficiently provision resources in response to jobs submitted in order to eliminate capacity constraints, reduce compute costs, and deliver results quickly.`,`lambda-quotas|Code can run for up to 15 minutes in a single invocation`,`lambda-quotas|Function timeout 900 seconds (15 minutes).`]}),t({id:`refinery-007`,building:`refinery`,bullets:[`3.5-S5`],d:3,stem:`Data scientists run interactive Apache Spark analysis on data in Amazon S3 and need each request to respond within seconds. Usage is sporadic, and the company will not operate clusters. Which solution BEST meets these requirements?`,correct:[`Create an Amazon EMR Serverless application and pre-initialize the resources that it needs`,`EMR Serverless needs no cluster operations, and pre-initialized resources let applications respond within seconds for interactive analysis.`],wrong:[[`Create an Amazon EMR Serverless application without pre-initialized resources and let it start each job from nothing`,`Without pre-initialized resources, each interactive request waits for the application to get its resources, so seconds-level responses are not assured.`],[`Keep an Amazon EMR cluster on Amazon EC2 running around the clock so that the Spark session is always warm`,`A cluster would respond quickly, but it is a cluster the company would configure and operate, and it runs even when usage is sporadic.`],[`Run each request as an AWS Batch job that provisions compute in response to the submitted job`,`Batch provisions resources as jobs are submitted, which suits queued batch work rather than seconds-level interactive responses.`]],slot:1,evidence:[`emr-serverless|For use cases where applications need a response within seconds, such as interactive data analysis, you can pre-initialize the resources that the application needs when you create the application.`,`emr-serverless|With EMR Serverless, you don’t have to configure, optimize, secure, or operate clusters to run applications with these frameworks.`]}),t({id:`refinery-008`,building:`refinery`,bullets:[`3.5-K4`,`3.5-S5`],d:2,stem:`A company needs to move and transform data between Amazon S3 and Amazon DynamoDB using Apache Spark code that its engineers already wrote. The jobs process vast amounts of data and the engineers want a managed platform for the Spark framework. Which service BEST meets these requirements?`,correct:[`Amazon EMR, running the Spark code on a managed cluster platform`,`EMR is a managed cluster platform for frameworks such as Apache Spark that can transform and move large amounts of data into and out of S3 and DynamoDB.`],wrong:[[`Amazon Athena, rewriting the Spark transformations as a set of SQL queries`,`Athena runs the Spark code that is submitted to it, so the code does not need rewriting, but Athena is built to analyze data directly in Amazon S3 rather than to be the managed cluster platform for moving data between S3 and DynamoDB.`],[`AWS Lambda, splitting the Spark transformations across many short functions`,`Lambda is not a Spark platform, and a standard Lambda function can run for up to 15 minutes in a single invocation.`],[`AWS Batch, running the Spark code as a single container on a queue for each dataset`,`Batch runs containerized batch jobs, but it is not the managed Spark framework platform the engineers want.`]],slot:2,evidence:[`emr-what-is|Amazon EMR, which was previously called Amazon Elastic MapReduce, is a managed cluster platform that simplifies running big data frameworks, such as Apache Hadoop and Apache Spark, on AWS to process and analyze vast amounts of data.`,`emr-what-is|Amazon EMR also lets you transform and move large amounts of data into and out of other AWS data stores and databases, such as Amazon Simple Storage Service (Amazon S3) and Amazon DynamoDB.`,`athena-what-is|When you run Apache Spark applications on Athena, you submit Spark code for processing and receive the results directly.`,`athena-what-is|Amazon Athena is an interactive query service that makes it easy to analyze data directly in Amazon Simple Storage Service (Amazon S3) using standard SQL.`,`lambda-quotas|Code can run for up to 15 minutes in a single invocation`,`lambda-quotas|Function timeout 900 seconds (15 minutes).`]}),t({id:`refinery-009`,building:`refinery`,bullets:[`3.5-S7`],d:1,stem:`A company queries 5 TB of CSV files in Amazon S3 with Amazon Athena. Each query reads only a few of the 60 columns, but every query is slow because it reads whole rows. The company wants the BEST way to improve performance by reading less data. What should the company do?`,correct:[`Convert the CSV files to Apache Parquet, a columnar format`,`Columnar formats compress by column and let Athena fetch only the blocks it needs, which improves query performance.`],wrong:[[`Move the CSV files to the Amazon S3 Standard-IA storage class to reduce the cost per gigabyte`,`A storage class changes the price of storing the objects, not how much of each row Athena reads.`],[`Convert the CSV files to JSON, which includes the column names with each record`,`JSON is also a row-based text format, so Athena still reads whole records instead of only the needed columns.`],[`Split the CSV files into many smaller files with the same columns in the same row-based layout`,`The layout is unchanged, so every query still reads whole rows across all 60 columns.`]],slot:3,evidence:[`athena-columnar|Apache Parquet and ORC are columnar storage formats that are optimized for fast retrieval of data and used in AWS analytical applications.`,`athena-columnar|Predicate pushdown in Parquet and ORC enables Athena queries to fetch only the blocks it needs, improving query performance.`]}),t({id:`refinery-010`,building:`refinery`,bullets:[`3.5-S7`],d:2,stem:`A company delivers JSON events to Amazon S3 with Amazon Data Firehose, and analysts query them with Amazon Athena. The company wants the delivered files stored in a columnar format, without adding a separate scheduled job or any servers. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Enable record format conversion in the Firehose delivery stream to convert the JSON to Apache Parquet before delivery`,`Firehose can convert JSON input to Parquet or ORC before it stores the data in Amazon S3, and columnar formats enable faster queries.`],wrong:[[`Run a nightly Athena CTAS query that rewrites the delivered JSON files as Parquet`,`This works, but it adds a separate scheduled step and the JSON files are stored first, which the company wants to avoid.`],[`Run an Amazon EMR cluster that converts each delivered JSON file to Parquet`,`The cluster is a server resource to configure and operate, and the conversion happens after delivery.`],[`Turn on S3 Intelligent-Tiering for the destination bucket so the delivered files are stored in a columnar format`,`A storage class changes how the objects are priced, not the format of the data inside them.`]],slot:0,evidence:[`firehose-format|Amazon Data Firehose can convert the format of your input data from JSON to Apache Parquet or Apache ORC before storing the data in Amazon S3.`,`firehose-format|Parquet and ORC are columnar data formats that save space and enable faster queries compared to row-oriented formats like JSON.`]}),e({id:`refinery-011`,building:`refinery`,bullets:[`3.5-S7`],d:2,stem:`A nightly AWS Glue job writes Parquet files to Amazon S3, and analysts query them with Amazon Athena by day. The company wants each query to scan only the days it filters on, and wants new days to be added to the Athena table with a single command. Which TWO actions BEST meet these requirements? (Choose two.)`,correct:[[`Write the output under Hive-style prefixes that contain key value pairs, such as year=2025/month=01/day=26`,`Hive-style partition paths include both the partition key names and values, and a query that filters on the partition scans only that data.`],[`Run MSCK REPAIR TABLE after each load to add the new Hive-style partitions`,`MSCK REPAIR TABLE loads new Hive partitions into a partitioned table, but it works only with Hive-style partitions.`]],wrong:[[`Write each day under plain prefixes such as data/2025/01/26 and run MSCK REPAIR TABLE to load them`,`MSCK REPAIR TABLE works only with Hive-style partitions, so plain date prefixes would need manual ALTER TABLE ADD PARTITION statements.`],[`Write all of the files under one prefix and rely on the WHERE clause to skip the other days`,`Without partitions, a WHERE clause on a date column cannot let Athena skip whole days of files.`],[`Enable S3 Intelligent-Tiering on the bucket so that old days move to cheaper access tiers`,`Storage tiers change the storage price and have no effect on how much data a query scans.`]],slots:[1,2],evidence:[`athena-partitions|By partitioning your data, you can restrict the amount of data scanned by each query, thus improving performance and reducing cost.`,`athena-partitions|To load new Hive partitions into a partitioned table, you can use the MSCK REPAIR TABLE command, which works only with Hive-style partitions.`,`athena-partitions|If you query a partitioned table and specify the partition in the WHERE clause, Athena scans the data only from that partition.`]}),t({id:`refinery-012`,building:`refinery`,bullets:[`3.5-S7`,`3.5-K4`],d:3,stem:`New CSV files land in an Amazon S3 raw bucket every hour. The company's Apache Spark conversion of each file to Parquet takes about 40 minutes, and the Parquet files must be written to a curated bucket on a schedule. The company wants no servers or clusters to manage and the LEAST operational overhead. Which solution meets these requirements?`,correct:[`Schedule an AWS Glue ETL job that reads the CSV files and writes Parquet to the curated bucket`,`Glue jobs run Spark on a serverless ETL engine, can be invoked on a schedule, and can write Parquet files to Amazon S3.`],wrong:[[`Run an Amazon EMR cluster continuously with a Spark job that converts each new file to Parquet`,`The always-on cluster is infrastructure to configure and operate, which conflicts with the requirement for no clusters.`],[`Invoke a standard AWS Lambda function for each CSV file to run the conversion`,`A standard Lambda function can run for at most 900 seconds (15 minutes), so a 40-minute conversion would time out.`],[`Use Amazon Athena to read the CSV files in place and never convert them`,`The requirement is to write Parquet files to the curated bucket on a schedule, and querying the CSV files in place writes none.`]],slot:1,evidence:[`glue-parquet|You can use AWS Glue to read Parquet files from Amazon S3 and from streaming sources as well as write Parquet files to Amazon S3.`,`glue-what-is|Invoke AWS Glue jobs on a schedule, on demand, or based on an event.`,`lambda-quotas|Function timeout 900 seconds (15 minutes).`]}),t({id:`refinery-013`,building:`refinery`,bullets:[`3.5-K4`],d:1,tags:[`mock-reserve`],stem:`A company runs analytics with Amazon Athena and Amazon EMR on data in Amazon S3. It wants one central repository of table locations, schemas and metadata that both services can read, with the LEAST management. Which solution meets this requirement?`,correct:[`Use the AWS Glue Data Catalog as the shared metadata repository`,`The Data Catalog stores metadata about data sources and integrates with Athena, EMR and other AWS analytics services.`],wrong:[[`Keep the schemas in an Amazon DynamoDB table and read it from both services`,`Athena and EMR keep and read table metadata through the Data Catalog, so a DynamoDB table would leave engineers to build that integration themselves.`],[`Keep the schemas as JSON files in an Amazon S3 bucket and read them from both services`,`Athena and EMR read table definitions from the Data Catalog, not from JSON files in Amazon S3, so the schemas would need custom integration work.`],[`Create a separate Hive metastore on an Amazon EC2 instance and maintain it for each service`,`The company would run and maintain the metastore, which conflicts with the LEAST management requirement.`]],slot:2,evidence:[`glue-catalog|The AWS Glue Data Catalog is a centralized repository that stores metadata about your organization's data sets.`,`glue-catalog|Amazon EMR – Access data sources defined in the Data Catalog for big data processing.`,`glue-catalog|Amazon Athena – Store and query table metadata in the Data Catalog for the Amazon S3 data using SQL.`]}),e({id:`refinery-014`,building:`refinery`,bullets:[`3.5-K4`,`3.5-S5`],d:3,tags:[`mock-reserve`],stem:`A company streams telemetry into Apache Kafka topics on Amazon Managed Streaming for Apache Kafka (Amazon MSK). Engineers want a serverless, continuously running Apache Spark Structured Streaming job that cleans the records and loads them into Amazon S3, with no clusters to operate. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create an AWS Glue streaming ETL job that reads from the MSK topic and loads the cleaned records into S3`,`Glue streaming ETL is built on Spark Structured Streaming, can ingest from Amazon MSK and can load into S3, without infrastructure to manage.`],[`Create an AWS Glue connection to the MSK cluster for the streaming job to use`,`For an Apache Kafka streaming source, a Glue streaming ETL job needs a connection to the Kafka source or the Amazon MSK cluster.`]],wrong:[[`Run an Amazon EMR cluster on Amazon EC2 instances and submit the streaming job to it`,`The cluster is something the engineers would configure and operate.`],[`Invoke an AWS Lambda function on a schedule that reads the topic and writes each batch to S3`,`A scheduled Lambda function is not a continuously running Spark Structured Streaming job, and each standard Lambda invocation can run for only up to 15 minutes.`],[`Schedule an AWS Batch job each hour that reads the topic and writes the results to S3`,`An hourly batch job is neither continuously running nor a Spark Structured Streaming job.`]],slots:[3,4],evidence:[`glue-components|AWS Glue streaming ETL is built on the Apache Spark Structured Streaming engine, and can ingest streams from Amazon Kinesis Data Streams, Apache Kafka, and Amazon Managed Streaming for Apache Kafka (Amazon MSK).`,`glue-components|Streaming ETL can clean and transform streaming data and load it into Amazon S3 or JDBC data stores.`,`glue-streaming|Creating a streaming ETL job involves the following steps: For an Apache Kafka streaming source, create an AWS Glue connection to the Kafka source or the Amazon MSK cluster.`,`lambda-quotas|Code can run for up to 15 minutes in a single invocation`]})],h=[t({id:`streaming-canal-001`,building:`streaming-canal`,bullets:[`3.5-K2`],d:1,stem:`Thousands of delivery vehicles send location and engine readings every second. The operations team must see alerts within seconds of a reading, and the data keeps arriving continuously all day. Which ingestion pattern BEST meets these requirements?`,correct:[`Stream the readings into Amazon Kinesis Data Streams and process them with a consumer as they arrive`,`The data is emitted continuously and needs low-latency processing, which is what a stream with real-time consumers provides.`],wrong:[[`Upload the readings as one file per hour to Amazon S3 and query the files with Amazon Athena`,`Hourly files add up to an hour of delay before the data can be queried, so alerts would not arrive within seconds.`],[`Run an AWS DataSync task every night to copy the readings from the vehicles into Amazon S3`,`A nightly copy is a batch transfer that makes the data available a day late, not within seconds.`],[`Export the readings from a database snapshot every morning and load them into a data lake`,`A daily snapshot export delivers the data once a day, which cannot support alerts within seconds.`]],slot:0,evidence:[`what-is-streaming-data|Streaming data is data that is emitted at high volume in a continuous, incremental manner, often requiring low-latency processing.`,`kinesis-streams|You can use Amazon Kinesis Data Streams to collect and process large streams of data records in real time.`]}),t({id:`streaming-canal-002`,building:`streaming-canal`,bullets:[`3.5-K2`],d:2,tags:[`trap:kds-vs-firehose`],stem:`Web servers produce application logs continuously. The company wants the logs stored in Amazon S3 as objects roughly every five minutes for later analysis. A delay of a few minutes is acceptable, and the company does not want to write or run any consumer code. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Send the logs to Amazon Data Firehose with S3 as the destination and a buffer interval of five minutes`,`Firehose buffers incoming data by size or time, here five minutes, and delivers it to S3 with no applications to write.`],wrong:[[`Send the logs to Amazon Kinesis Data Streams and run a consumer application on Amazon EC2 that writes files to S3`,`It works, but the company would write and operate the consumer, which it wants to avoid.`],[`Send the logs to an Amazon MSK cluster and write a Kafka consumer that stores the records in S3 every five minutes`,`A Kafka cluster and a custom consumer must both be run, which is far more than a managed delivery service.`],[`Invoke an AWS Lambda function for every log line that writes the line to S3 as its own object`,`Every line becomes a separate object and the function is code to maintain, instead of buffered delivery in batches.`]],slot:1,evidence:[`firehose|Amazon Data Firehose buffers incoming streaming data to a certain size or for a certain period of time before delivering it to destinations.`,`firehose|With Amazon Data Firehose, you don't need to write applications or manage resources.`,`firehose-faqs|The frequency of data delivery to Amazon S3 is determined by the S3 buffer size and buffer interval value you configured for your Firehose stream.`]}),t({id:`streaming-canal-003`,building:`streaming-canal`,bullets:[`3.5-K2`,`3.5-K7`],d:2,stem:`A consumer application of an Amazon Kinesis data stream was down for two days after a bad deployment. The stream uses its default settings, and the company lost records it never processed. To be able to reprocess records after outages of up to a week, the company wants the LEAST change. Which solution meets these requirements?`,correct:[`Increase the retention period of the data stream to cover at least a week`,`The retention period defaults to 24 hours and can be raised, so unprocessed records stay available to read after a longer outage.`],wrong:[[`Add shards to the data stream so that consumers can read the records faster`,`More shards raise capacity, but records still expire after the default retention period, so a two-day outage still loses data.`],[`Switch the consumers to enhanced fan-out so that each one gets dedicated read throughput`,`Enhanced fan-out changes read throughput, not how long the records remain in the stream.`],[`Replace the stream with an Amazon Data Firehose stream that delivers the records to the same consumers`,`Firehose delivers to destinations and is not a store that consumers can read from again after an outage.`]],slot:2,evidence:[`kinesis-concepts|A stream’s retention period is set to a default of 24 hours after creation.`,`kinesis-concepts|You can increase the retention period up to 8760 hours (365 days) using the IncreaseStreamRetentionPeriod operation`]}),t({id:`streaming-canal-004`,building:`streaming-canal`,bullets:[`3.5-K7`],d:1,stem:`A startup ingests game events into Amazon Kinesis Data Streams. Traffic is unpredictable and can jump tenfold during a promotion, and the team does not want to plan or adjust the number of shards. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create the data stream in on-demand capacity mode so that shards are managed automatically`,`In on-demand mode Kinesis Data Streams manages the shards to provide the necessary throughput as workloads ramp up or down.`],wrong:[[`Create the data stream in provisioned mode with enough shards for the largest expected promotion`,`In provisioned mode the team must specify the number of shards, which is the planning the team wants to avoid.`],[`Create the data stream in provisioned mode with one shard and add shards by hand when alarms fire`,`The team would still specify and change the number of shards itself, which is the work it wants to avoid.`],[`Replace the stream with an Amazon MSK Provisioned cluster with a fixed number of broker nodes`,`A provisioned Kafka cluster means choosing and scaling broker capacity, so the capacity planning remains.`]],slot:3,evidence:[`kinesis-concepts|With the on-demand mode, Kinesis Data Streams automatically manages the shards in order to provide the necessary throughput.`,`kinesis-concepts|With the provisioned mode, you must specify the number of shards for the data stream.`]}),t({id:`streaming-canal-005`,building:`streaming-canal`,bullets:[`3.5-K7`],d:3,stem:`Seven applications read from the same Amazon Kinesis data stream. They share the read throughput of each shard, and during busy periods some of them fall behind. The company does not want to change the number of shards or rewrite the producers. Which solution BEST meets these requirements?`,correct:[`Register the consumers as enhanced fan-out consumers so each receives dedicated throughput per shard`,`Enhanced fan-out gives each consumer dedicated throughput of up to 2 MB per second per shard, so consumers no longer contend.`],wrong:[[`Increase the retention period of the data stream so that slower consumers have more time to catch up`,`Retention controls how long records stay in the stream and does not raise the read throughput that the consumers share.`],[`Make each consumer poll the stream more often so that it reads its records sooner`,`The consumers still share the same read throughput per shard, so extra polls only compete for it.`],[`Move the stream to on-demand capacity mode so the consumers read from automatically managed shards`,`The capacity mode decides how shards are managed, and the consumers would still share the read throughput of each shard.`]],slot:0,evidence:[`kinesis-efo|This feature lets consumers receive records from a stream with throughput of up to 2 MB of data per second per shard.`,`kinesis-efo|This throughput is dedicated, which means that consumers that use enhanced fan-out don't have to contend with other consumers that are receiving data from the stream.`]}),t({id:`streaming-canal-006`,building:`streaming-canal`,bullets:[`3.5-K7`],d:2,stem:`A company runs Apache Kafka on its own servers. Dozens of applications use Kafka client libraries and open-source Kafka tooling. The company wants to move to a managed service on AWS without changing application code. Which service BEST meets these requirements?`,correct:[`Amazon MSK, which runs open-source Apache Kafka`,`MSK supports existing applications, tooling and plugins from the Kafka community without requiring changes to application code.`],wrong:[[`Amazon Kinesis Data Streams, with the applications moved to the Kinesis producer and consumer interfaces`,`The applications would have to be rewritten for Kinesis interfaces, so changes to application code are needed.`],[`Amazon Data Firehose, with the producers pointed at a delivery stream for each topic`,`Firehose delivers streaming data to destinations and is not a Kafka-compatible service for existing clients.`],[`Amazon SQS standard queues, with one queue created for each Kafka topic`,`SQS is a queue service with its own API, so the Kafka applications and tooling would have to be rewritten.`]],slot:1,evidence:[`msk-what-is|It runs open-source versions of Apache Kafka.`,`msk-what-is|This means existing applications, tooling, and plugins from partners and the Apache Kafka community are supported without requiring changes to application code.`]}),t({id:`streaming-canal-007`,building:`streaming-canal`,bullets:[`3.5-K7`],d:2,stem:`A team must keep using Apache Kafka APIs for a new event pipeline whose load is uneven and hard to predict. The team does not want to choose broker instance types or manage cluster capacity. Which solution BEST meets these requirements?`,correct:[`Amazon MSK Serverless`,`MSK Serverless runs Apache Kafka without managing and scaling cluster capacity.`],wrong:[[`Amazon MSK Provisioned with brokers sized for the peak load`,`MSK Provisioned lets you choose broker instance types, storage and the number of brokers, which is the capacity management the team avoids.`],[`Apache Kafka installed on a fleet of Amazon EC2 instances in an Auto Scaling group`,`The team would install, patch and scale Kafka itself, so cluster capacity remains its job.`],[`Amazon Kinesis Data Streams with the producers rewritten to use the Kinesis API`,`It is a different API, so the team could no longer keep using Apache Kafka APIs.`]],slot:2,evidence:[`msk-what-is|Run Apache Kafka without having to manage and scale cluster capacity with MSK Serverless.`,`msk-provisioned|MSK Provisioned is an MSK cluster deployment option that allows you to manually configure and scale your Apache Kafka clusters.`]}),t({id:`streaming-canal-008`,building:`streaming-canal`,bullets:[`3.5-K7`],d:1,tags:[`trap:kds-vs-firehose`],stem:`Application events must be loaded continuously into Amazon OpenSearch Service for search. The company does not want to write consumer applications or manage servers for the load. Which service meets these requirements with the LEAST operational overhead?`,correct:[`Amazon Data Firehose with OpenSearch Service as the destination`,`Firehose delivers streaming data to destinations such as OpenSearch Service, with no applications to write or resources to manage.`],wrong:[[`Amazon Kinesis Data Streams with a consumer application that indexes the records`,`The company would write and run the consumer application that indexes the records, which it wants to avoid.`],[`Amazon MSK with a self-managed connector that indexes the records into OpenSearch Service`,`A Kafka cluster and a connector must be set up and run, which adds servers and configuration to manage.`],[`An Amazon EC2 instance that polls the producers and sends each event to OpenSearch Service`,`The company would manage the instance and its polling code, so servers and code remain.`]],slot:3,evidence:[`firehose|Amazon Data Firehose is a fully managed service for delivering real-time streaming data to destinations such as Amazon Simple Storage Service (Amazon S3), Amazon Redshift, Amazon OpenSearch Service`,`firehose|With Amazon Data Firehose, you don't need to write applications or manage resources.`]}),e({id:`streaming-canal-009`,building:`streaming-canal`,bullets:[`3.5-S2`],d:3,tags:[`trap:kds-vs-firehose`],stem:`An online retailer collects clickstream records. A fraud team needs custom code to examine each record within seconds, and the company also needs every raw record archived in an Amazon S3 data lake. The company wants the LEAST custom code for the archive. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Ingest the records into Amazon Kinesis Data Streams and process them with an AWS Lambda consumer`,`The stream lets custom consumers such as Lambda process records in real time.`],[`Configure an Amazon Data Firehose stream to read from the data stream and deliver to S3`,`Firehose can read from an existing Kinesis data stream and load the data into S3 with no code.`]],wrong:[[`Send the records only to Amazon S3 and run the fraud checks in a nightly batch job over the stored files`,`A nightly batch job checks each record hours after it arrives, so the requirement to examine each record within seconds is not met.`],[`Write the records to Amazon SQS and have one worker both check for fraud and write files to S3`,`It puts custom code in charge of the archive too, which is more code than letting Firehose do the delivery.`],[`Ingest into an Amazon MSK cluster and run a consumer on Amazon EC2 that writes every record to S3`,`It needs a Kafka cluster and a consumer fleet to operate, and the archive is custom code instead of managed delivery.`]],slots:[0,3],evidence:[`kinesis-consumers|You can also develop consumers using other AWS services such as AWS Lambda, Amazon Managed Service for Apache Flink, and Amazon Data Firehose.`,`firehose|You can also configure your Firehose stream to automatically read data from an existing Kinesis data stream, and load it into destinations.`]}),e({id:`streaming-canal-010`,building:`streaming-canal`,bullets:[`3.5-S2`],d:3,stem:`A telemetry platform writes about 5 MB of records per second to a provisioned Amazon Kinesis data stream with 4 shards, using the customer ID as the partition key. Each shard accepts up to 1 MB per second of writes. One large customer produces most of the records, so one shard is throttled while the others are almost idle, and even a perfectly even spread would exceed what 4 shards accept. The company wants the writes to stop being throttled. Which TWO actions should the company take? (Choose two.)`,correct:[[`Change the partition key to a value with many distinct values, such as the device ID`,`The partition key determines the shard of each record, so many distinct values spread records across shards.`],[`Increase the number of shards so that the total write capacity is above 5 MB per second`,`Stream capacity is a function of the number of shards, and 4 shards at 1 MB per second cannot take 5 MB per second even when the load is even.`]],wrong:[[`Increase the retention period of the stream to 7 days`,`Retention controls how long records stay in the stream and does not change which shard receives a record.`],[`Register the consumers as enhanced fan-out consumers`,`Enhanced fan-out gives consumers dedicated read throughput and does not relieve a shard that is throttled on writes.`],[`Have the large customer's producers retry each write until it succeeds`,`Retries keep sending the same hot key to the same shard, so the shard stays throttled.`]],slots:[1,2],evidence:[`kinesis-concepts|It uses the partition key that is associated with each data record to determine which shard a given data record belongs to.`,`kinesis-concepts|The data capacity of your stream is a function of the number of shards that you specify for the stream.`,`kinesis-retries|to handle any resulting throttling determined as excessive by expanding the capacity of the stream and implementing an appropriate partition key strategy.`]}),t({id:`streaming-canal-011`,building:`streaming-canal`,bullets:[`3.5-S2`],d:2,stem:`Producers write about 6 MB of data per second in total, spread evenly across many partition keys, to a provisioned Amazon Kinesis data stream with 2 shards, and writes are throttled. Each shard supports a write rate of up to 1 MB per second. The company wants writes to stop being throttled. Which solution meets these requirements?`,correct:[`Increase the number of shards so the total write capacity is above 6 MB per second`,`Stream capacity is the sum of its shards, so at least six shards are needed to accept 6 MB per second at 1 MB per shard.`],wrong:[[`Register the consumers as enhanced fan-out consumers to give each one dedicated throughput`,`Enhanced fan-out raises read throughput for consumers and does nothing for the write limit of the shards.`],[`Increase the retention period of the stream so that throttled records are kept longer`,`Retention does not raise the write rate of a shard, and throttled writes are not accepted by the stream.`],[`Place an Amazon Data Firehose stream in front of the data stream to buffer the writes`,`Firehose buffers data on its way to destinations and does not raise the write capacity of the shards of the data stream.`]],slot:0,evidence:[`kinesis-concepts|up to 1,000 records per second for writes, up to a maximum total data write rate of 1 MB per second (including partition keys).`,`kinesis-concepts|The total capacity of a data stream is the sum of the capacities of its shards.`]}),t({id:`streaming-canal-012`,building:`streaming-canal`,bullets:[`3.5-S2`],d:2,tags:[`trap:kds-vs-firehose`],stem:`A company streams IoT readings and wants analysts to run ad-hoc SQL queries on them within minutes of arrival. The readings need no custom per-record processing. The company wants the architecture with the LEAST operational overhead. Which design meets these requirements?`,correct:[`Send the readings to Amazon Data Firehose that delivers to Amazon S3, and query the objects with Amazon Athena`,`Firehose lands the data in S3 with no code, and Athena queries it in place with SQL.`],wrong:[[`Send the readings to Amazon Kinesis Data Streams and run consumer servers that write to an Amazon RDS database`,`Consumer servers and a database must be operated, and no custom processing is needed to justify them.`],[`Send the readings to an Amazon MSK cluster and run a Kafka consumer that loads an Amazon EMR cluster`,`Kafka brokers, a consumer and a cluster must all be run, which is more overhead than needed.`],[`Send the readings to an Amazon SQS queue and load them each night into Amazon Redshift`,`A nightly load means the analysts wait until the next day, not minutes, and a warehouse must be managed.`]],slot:1,evidence:[`firehose-faqs|It can capture, transform, and load streaming data into Amazon S3, Amazon Redshift, Amazon OpenSearch Service, Snowflake, Apache Iceberg tables and Splunk, enabling near real-time analytics with existing business intelligence tools and dashboards you’re already using today.`,`athena-what-is|Amazon Athena is an interactive query service that makes it easy to analyze data directly in Amazon Simple Storage Service (Amazon S3) using standard SQL.`]}),e({id:`streaming-canal-013`,building:`streaming-canal`,bullets:[`3.5-S2`],d:3,tags:[`mock-reserve`],stem:`A company runs Apache Kafka producers and consumers on premises and is moving them to AWS without changing application code. The records must also be streamed continuously into Amazon S3, and the company wants as little infrastructure to run as possible. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Create an Amazon MSK cluster for the Kafka producers and consumers`,`MSK runs open-source Apache Kafka, so existing applications work without code changes.`],[`Use MSK Connect to stream data from the Kafka cluster to Amazon S3`,`MSK Connect streams data to and from an Apache Kafka cluster as a managed capability.`]],wrong:[[`Create an Amazon Kinesis data stream and rewrite the applications to use the Kinesis API`,`The applications would need code changes, which the company wants to avoid.`],[`Install Apache Kafka on Amazon EC2 instances and write a custom consumer that copies records to S3`,`The company would run the brokers and the copy code itself, which is the infrastructure it wants to minimize.`],[`Create an Amazon SQS queue for each topic and poll the queues with AWS Lambda functions`,`It requires rewriting the Kafka clients for a different API and adds polling code.`]],slots:[0,4],evidence:[`msk-what-is|This means existing applications, tooling, and plugins from partners and the Apache Kafka community are supported without requiring changes to application code.`,`msk-what-is|Use MSK Connect to stream data to and from your Apache Kafka cluster.`]}),t({id:`streaming-canal-014`,building:`streaming-canal`,bullets:[`3.5-K2`],d:2,tags:[`mock-reserve`,`trap:kds-vs-firehose`],stem:`An Amazon Data Firehose stream delivers events to Amazon S3. Analysts report that the stream writes a very large number of tiny objects, which slows their queries. The company wants larger objects with the LEAST change and no new code. Which action meets these requirements?`,correct:[`Increase the S3 buffer size and buffer interval values on the Firehose stream`,`The frequency of delivery to S3 is determined by the buffer size and buffer interval, so larger values produce fewer, larger objects with no new code.`],wrong:[[`Decrease the S3 buffer size and buffer interval values on the Firehose stream`,`Smaller values trigger delivery more often, which produces even more small objects.`],[`Add shards to the Firehose stream to raise its capacity`,`Firehose needs no resources to manage, so there are no shards to add, and capacity does not control object size.`],[`Replace Firehose with Amazon Kinesis Data Streams and an EC2 consumer that batches records into files`,`It needs a consumer application that the company must write and operate, which is much more than changing a setting.`]],slot:2,evidence:[`firehose-faqs|The frequency of data delivery to Amazon S3 is determined by the S3 buffer size and buffer interval value you configured for your Firehose stream.`,`firehose|With Amazon Data Firehose, you don't need to write applications or manage resources.`]})],g=[t({id:`transfer-dock-001`,building:`transfer-dock`,bullets:[`3.5-K3`],d:1,stem:`A company shares files from an on-premises Windows file server over SMB. It is moving the data to Amazon FSx for Windows File Server and wants to copy the existing files now and keep both locations in sync until cutover, with the LEAST custom tooling. Which solution meets these requirements?`,correct:[`Deploy an AWS DataSync agent on premises and create a recurring task from the SMB share to the FSx file system`,`DataSync supports SMB sources and FSx for Windows File Server destinations, and a recurring task copies only the data that has changed.`],wrong:[[`Create an AWS Transfer Family server with SFTP enabled and have the file server push its files to the FSx file system`,`Transfer Family stores files in Amazon S3 or Amazon EFS, so it cannot write into an FSx file system.`],[`Deploy an Amazon S3 File Gateway on premises and copy the files to its SMB file share each night to reach FSx`,`S3 File Gateway stores the files as objects in Amazon S3, so copying them to its SMB file share does not put them into the FSx for Windows File Server file system.`],[`Order an AWS Direct Connect connection with a private virtual interface and drag the files across the new link`,`Direct Connect only establishes a dedicated network connection, so the files would still need custom tooling to copy and keep in sync.`]],slot:1,evidence:[`datasync-what-is|DataSync works with the following on-premises storage systems: Network File System (NFS) Server Message Block (SMB) Hadoop Distributed File Systems (HDFS) Object storage`,`datasync-what-is|DataSync works with the following AWS storage services: Amazon S3 Amazon EFS Amazon FSx for Windows File Server Amazon FSx for Lustre Amazon FSx for OpenZFS Amazon FSx for NetApp ONTAP`,`datasync-how|Transferring only the data that's changed since the previous task execution.`,`transfer-what-is|Amazon Elastic File System (Amazon EFS) Network File System (NFS) file systems.`,`sgw-file-s3|Amazon S3 File Gateway supports a file interface into Amazon Simple Storage Service (Amazon S3)`,`sgw-file-s3|By using this combination, you can store and retrieve objects in Amazon S3 using industry-standard file protocols such as Network File System (NFS) and Server Message Block (SMB).`,`connectivity-dx|AWS Direct Connect makes it easy to establish a dedicated connection from an on-premises network to one or more VPCs.`]}),e({id:`transfer-dock-002`,building:`transfer-dock`,bullets:[`3.5-K3`],d:2,stem:`A logistics company receives shipment files from trading partners. Some partners upload with SFTP clients and others exchange business-to-business messages over AS2, and the partners cannot change their client software. All files must land in Amazon S3, and the company wants NO servers to manage. Which TWO actions meet these requirements with the LEAST operational overhead? (Choose two.)`,correct:[[`Create an AWS Transfer Family server that enables SFTP and stores the files in Amazon S3`,`Transfer Family provides fully managed SFTP servers that write directly into S3, so the partners keep their existing clients and no servers are managed.`],[`Use AWS Transfer Family to set up AS2 for the partners that exchange business-to-business messages`,`Transfer Family supports AS2 for business-to-business transfers into AWS storage, with no server infrastructure to run.`]],wrong:[[`Run an OpenSSH-based SFTP server on Amazon EC2 instances that sync uploaded files to Amazon S3`,`This works for SFTP, but the company would have to patch, scale and operate the instances, and AS2 is still unsupported.`],[`Deploy an AWS DataSync agent at each partner site and schedule tasks that copy files to Amazon S3`,`Partners cannot change their client software, so they cannot install agents, and DataSync does not accept SFTP or AS2 uploads.`],[`Deploy an Amazon S3 File Gateway and give each partner an NFS file share to upload into`,`S3 File Gateway serves NFS and SMB shares, not SFTP or AS2, so the partners would have to change their clients.`]],slots:[0,3],evidence:[`transfer-what-is|AWS Transfer Family offers fully managed support for the transfer of files over SFTP, AS2, FTPS, FTP, and web browser-based transfers directly into and out of AWS storage services.`,`transfer-what-is|With Transfer Family, you get access to a file transfer protocol-enabled server in AWS (or a managed file transfer web interface), without the need to run any server infrastructure.`,`transfer-what-is|You can use this service to migrate your file transfer-based workflows to AWS while maintaining your end users' clients and configurations as is.`]}),t({id:`transfer-dock-003`,postGuide:[`vpn-large-bandwidth-tunnel`],building:`transfer-dock`,bullets:[`3.5-K6`],d:2,tags:[`trap:direct-connect-vs-vpn`],stem:`A media company must send about 8 Gbps of sustained traffic from its data center to a VPC every night for several months. The traffic must use a private, consistent network path and must not depend on the public internet. Which connectivity option BEST meets these requirements?`,correct:[`Provision an AWS Direct Connect dedicated connection with a 10 Gbps port and create a private virtual interface`,`A dedicated 10 Gbps port gives the required capacity over a private path that bypasses internet service providers, with a more consistent experience than internet-based connections.`],wrong:[[`Create an AWS Site-to-Site VPN connection with standard tunnels and spread the nightly traffic across them`,`Standard VPN tunnels carry up to 1.25 Gbps each and run over the internet, so neither the capacity nor the private path is met.`],[`Order an AWS Direct Connect hosted connection of 500 Mbps from an AWS Direct Connect Partner`,`A 500 Mbps hosted connection is far below the 8 Gbps of sustained traffic that the nightly transfers need.`],[`Provision an AWS Direct Connect dedicated connection with a 1 Gbps port and create a private virtual interface`,`The path is private, but a 1 Gbps port cannot carry 8 Gbps, so the nightly transfers would not fit.`]],slot:2,evidence:[`dx-dedicated|Port speed The possible values are 1 Gbps, 10 Gbps, 100 Gbps, and 400 Gbps.`,`vpn-tunnels|Standard bandwidth: Up to 1.25 Gbps per tunnel (default)`,`dx-what-is|bypassing internet service providers in your network path.`,`connectivity-dx|Direct Connect can reduce network costs, increase bandwidth throughput, and provide a more consistent network experience than internet-based connections.`]}),t({id:`transfer-dock-004`,building:`transfer-dock`,bullets:[`3.5-K6`,`3.5-S3`],d:3,stem:`A company must copy a dataset of about 20 million small files from an on-premises NFS server to Amazon S3 and then keep the copy current, with the LEAST operational effort. The files must be encrypted in transit and verified on arrival. The company has chosen AWS DataSync for the copy. Which DataSync configuration meets these requirements?`,correct:[`A Basic mode task that uses an agent deployed on premises to read from the NFS server`,`Basic mode transfers files between AWS storage and other supported locations such as on-premises NFS through an agent, with built-in encryption and integrity validation, and about 20 million files is under its per-task quota.`],wrong:[[`A task that reads the NFS server through an AWS Transfer Family SFTP endpoint without an agent`,`Transfer Family is a separate file transfer service, and it is not a DataSync source location, so the copy would not run as a DataSync task.`],[`A task that reads the NFS server directly from AWS with no agent, because DataSync can reach any NFS server over the internet`,`A DataSync agent is needed to copy data from an on-premises storage system, so a task with no agent cannot read the server.`],[`An Amazon S3 File Gateway on premises, with the files copied to its NFS share by a nightly script`,`The gateway needs a custom copy script and does not provide DataSync task scheduling, verification or incremental transfers.`]],slot:3,evidence:[`datasync-modes|Basic mode – Transfer files or objects between AWS storage and all other supported DataSync locations.`,`datasync-how|The diagram illustrates a common DataSync use case: A DataSync agent copying data from an on-premises storage system.`,`datasync-limits|storage services For more information, see How DataSync transfers files, objects, and directories 50 million`,`datasync-what-is|DataSync includes automatic encryption and data integrity validation to help make sure that your data arrives securely, intact, and ready to use.`]}),t({id:`transfer-dock-005`,building:`transfer-dock`,bullets:[`3.5-S3`],d:2,stem:`A company has a legacy payroll application that uploads files with a plain FTP client that cannot be changed. The application runs in the corporate network, which connects to a VPC. The files must land in Amazon S3 and must not cross the public internet. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create an AWS Transfer Family server that enables FTP, hosts its endpoint in the VPC, and uses Amazon S3 as storage`,`Transfer Family supports FTP, and an FTP server must use the VPC-hosted endpoint with internal access, so the files stay off the public network.`],wrong:[[`Create an AWS Transfer Family server that enables FTP with a publicly accessible endpoint and Amazon S3 storage`,`Publicly accessible endpoints are not supported for FTP servers, and the transfer would cross the public network.`],[`Create an AWS Transfer Family server that enables only SFTP and tell the payroll team to switch its client to SFTP`,`This needs a client change, but the legacy FTP client software cannot be changed.`],[`Deploy an AWS DataSync agent in the corporate network and configure the payroll application to send FTP files to it`,`DataSync reads from NFS, SMB, HDFS or object storage and does not accept FTP uploads, so the application could not deliver files to it.`]],slot:0,evidence:[`transfer-ftp|When you enable FTP, you must choose the internal access option for the VPC-hosted endpoint.`,`transfer-ftp|Publicly accessible endpoints are not supported.`,`transfer-ftp|FTP uses clear text and does not support encryption of traffic.`,`datasync-what-is|DataSync works with the following on-premises storage systems: Network File System (NFS) Server Message Block (SMB) Hadoop Distributed File Systems (HDFS) Object storage`]}),e({id:`transfer-dock-006`,building:`transfer-dock`,bullets:[`3.5-K3`],d:2,stem:`A company stores 200 TB in an on-premises Hadoop Distributed File System (HDFS) cluster and is moving the data to Amazon S3 over its network. The company wants a managed transfer service rather than custom copy scripts. Which TWO actions are required? (Choose two.)`,correct:[[`Deploy an AWS DataSync agent on premises where it can read from the HDFS cluster`,`The agent is the appliance DataSync uses to read from and write to storage during a transfer.`],[`Create a DataSync task with the HDFS cluster as the source location and an S3 bucket as the destination location`,`Every DataSync transfer is a task with a source and a destination location, and DataSync supports both HDFS and S3.`]],wrong:[[`Deploy an Amazon S3 File Gateway and mount the HDFS data through an NFS file share`,`S3 File Gateway exposes NFS and SMB file shares for applications, not an HDFS source for a bulk migration.`],[`Create an AWS Transfer Family server and have the cluster push its blocks to it over SFTP`,`Transfer Family accepts file uploads over SFTP and similar protocols but does not read from an HDFS cluster.`],[`Create an AWS Storage Gateway Tape Gateway and copy the HDFS data to virtual tapes`,`Tape Gateway provides virtual tapes for backup applications and does not move the HDFS data into S3 objects for analytics.`]],slots:[1,4],evidence:[`datasync-what-is|DataSync works with the following on-premises storage systems: Network File System (NFS) Server Message Block (SMB) Hadoop Distributed File Systems (HDFS) Object storage`,`datasync-how|An agent is a virtual machine (VM) appliance that DataSync uses to read from and write to storage during a transfer.`,`datasync-how|Each DataSync transfer (also known as a task) has a source and destination location.`]}),t({id:`transfer-dock-007`,building:`transfer-dock`,bullets:[`3.5-S3`],d:1,stem:`A company wants to copy objects from an Amazon S3 bucket to an Amazon EFS file system on a schedule. Both resources are in the same account and the same AWS Region. The company wants the LEAST infrastructure to deploy and operate. Which solution meets these requirements?`,correct:[`Create an AWS DataSync task from the S3 location to the EFS location and run it on a schedule without an agent`,`Between AWS storage services in the same account no agent is required, and the task can run on a schedule.`],wrong:[[`Deploy a DataSync agent on an Amazon EC2 instance in the VPC and use it for the S3-to-EFS task`,`The agent is not needed between AWS storage services in the same account, so the instance is extra infrastructure to run.`],[`Deploy an Amazon S3 File Gateway on an EC2 instance and copy the objects to EFS from its file share`,`The gateway instance and the copy job are extra components to operate when no agent is needed for this transfer.`],[`Create an AWS Transfer Family server that uses EFS storage and have the bucket push its objects to it over SFTP`,`An S3 bucket cannot push objects over SFTP, so a client and scripts would still be needed, along with the server.`]],slot:1,evidence:[`datasync-how|When transferring between AWS storage services in the same account (whether in the same AWS Region or across AWS Regions in the same partition), no agent is required.`,`datasync-how|Scheduling when your task executes.`]}),t({id:`transfer-dock-008`,postGuide:[`transfer-family-web-app`],postGuideKey:[`transfer-family-web-app`],building:`transfer-dock`,bullets:[`3.5-K3`],d:2,stem:`A company wants its business analysts to upload and download files in an Amazon S3 bucket through a web browser. The company does not want to build a custom portal, and it wants the LEAST server management. Which solution meets these requirements?`,correct:[`Use an AWS Transfer Family web app to give the analysts browser-based access to the S3 data`,`Transfer Family supports browser-based transfers and web apps that simplify access to S3 data for business users, with no servers to run.`],wrong:[[`Deploy an Amazon S3 File Gateway and ask the analysts to browse the bucket by mounting its SMB file share`,`The gateway is a file share for mounted clients and does not provide the browser-based transfers that the analysts need.`],[`Host a custom file upload portal on Amazon EC2 instances behind an Application Load Balancer`,`This is exactly the custom portal and the server management that the company wants to avoid.`],[`Create an AWS DataSync task and have the analysts start it each time they need to move a file`,`DataSync is a service for bulk transfers between storage systems and has no browser interface for business users.`]],slot:2,evidence:[`transfer-what-is|AWS Transfer Family offers fully managed support for the transfer of files over SFTP, AS2, FTPS, FTP, and web browser-based transfers directly into and out of AWS storage services.`,`transfer-what-is|Simplified access to data in Amazon S3 to a wider and diverse range of business users`]}),t({id:`transfer-dock-009`,building:`transfer-dock`,bullets:[`3.5-K6`],d:2,stem:`A company must move 20 TB of data every night from its data center to a VPC through a private connection, and each transfer must finish within a 4-hour window. That needs more than 11 Gbps of sustained throughput. The company wants the AWS Direct Connect capacity managed as one logical connection at a single Direct Connect location. Which option BEST meets these requirements?`,correct:[`A link aggregation group (LAG) of two 10 Gbps dedicated connections`,`A LAG aggregates multiple connections at one endpoint and treats them as a single managed connection, giving 20 Gbps, which covers the required throughput.`],wrong:[[`A single 10 Gbps dedicated connection`,`A 10 Gbps connection carries about 18 TB in 4 hours at full line rate, so 20 TB does not fit even before any overhead.`],[`A hosted connection of 5 Gbps provisioned by an AWS Direct Connect Partner`,`A 5 Gbps hosted connection carries about 9 TB in 4 hours, below the throughput the window requires.`],[`A single 1 Gbps dedicated connection`,`A 1 Gbps connection carries about 1.8 TB in 4 hours, far below the 20 TB needed.`]],slot:0,evidence:[`dx-lags|A link aggregation group (LAG) is a logical interface that uses the Link Aggregation Control Protocol (LACP) to aggregate multiple connections at a single Direct Connect endpoint, allowing you to treat them as a single, managed connection.`,`dx-lags|You can use multiple connections to increase available bandwidth.`]}),e({id:`transfer-dock-010`,building:`transfer-dock`,bullets:[`3.5-S3`],d:3,stem:`A company has an AWS Direct Connect connection from its data center to a VPC. It will use AWS DataSync to copy files from an on-premises NFS server to Amazon S3. Security policy requires that the transfer traffic does not traverse the public internet. Which TWO actions meet this requirement? (Choose two.)`,correct:[[`Create a private virtual interface on the Direct Connect connection to reach the VPC with private IP addresses`,`A private virtual interface is used to access a VPC using private IP addresses, so the path avoids the public internet.`],[`Use a DataSync VPC endpoint so the agent sends data to the service through the VPC`,`DataSync supports VPC endpoints, which let you transfer data without traversing the public internet.`]],wrong:[[`Activate the agent with the public service endpoint and route its traffic through a NAT gateway`,`Traffic leaves through the NAT gateway to public service endpoints, which is the public internet path the policy forbids.`],[`Create an AWS Site-to-Site VPN connection over the internet and send the DataSync traffic through its tunnels`,`The VPN tunnels run over the internet, so the transfer still traverses the public internet.`],[`Enable Amazon S3 Transfer Acceleration on the destination bucket and point the task at the accelerated endpoint`,`Transfer Acceleration routes uploads through the public edge network, so it does not keep the traffic off the public internet.`]],slots:[2,3],evidence:[`datasync-what-is|It also supports virtual private cloud (VPC) endpoints, giving you the option to transfer data without traversing the public internet and further increasing the security of data copied online.`,`dx-what-is|A private virtual interface enables access to your VPC.`,`dx-what-is|This type of interface is used to access an Amazon Virtual Private Cloud (VPC) using private IP addresses.`]}),t({id:`transfer-dock-011`,postGuide:[`vpn-large-bandwidth-tunnel`],postGuideKey:[`vpn-large-bandwidth-tunnel`],building:`transfer-dock`,bullets:[`3.5-K6`],d:3,tags:[`trap:direct-connect-vs-vpn`],stem:`A company connects its data center to a transit gateway with an AWS Site-to-Site VPN connection and must replicate data at about 4 Gbps through a single tunnel while it waits for a dedicated circuit. The company wants to keep the VPN and avoid configuring ECMP across tunnels. Which solution BEST meets these requirements?`,correct:[`Configure the VPN connection attached to the transit gateway with a Large Bandwidth Tunnel`,`Large Bandwidth Tunnels support up to 5 Gbps per tunnel on VPN connections attached to a transit gateway, with no ECMP needed.`],wrong:[[`Keep the standard tunnels on the transit gateway attachment and add a second customer gateway device`,`Each standard tunnel is limited to 1.25 Gbps, and a single tunnel therefore cannot carry 4 Gbps of replication traffic.`],[`Move the VPN connection to a virtual private gateway and configure a Large Bandwidth Tunnel there`,`Large Bandwidth Tunnels are not supported for virtual private gateway attachments, only for transit gateway or Cloud WAN.`],[`Replace the VPN with an AWS Direct Connect hosted connection of 500 Mbps from a Partner`,`This gives up the VPN the company wants to keep, and a 500 Mbps hosted connection is well below 4 Gbps.`]],slot:0,evidence:[`vpn-tunnels|Standard bandwidth: Up to 1.25 Gbps per tunnel (default) Large Bandwidth Tunnel (LBT): Up to 5 Gbps per tunnel Large Bandwidth Tunnels are available only for VPN connections attached to Transit Gateway or Cloud WAN.`,`vpn-tunnels|Not supported for Virtual Private Gateway attachments.`,`vpn-tunnels|This eliminates or reduces the need to deploy complex protocols such as ECMP (Equal Cost Multi Path) to achieve higher bandwidth`]}),t({id:`transfer-dock-012`,building:`transfer-dock`,bullets:[`3.5-K3`,`3.5-S3`],d:2,stem:`A company keeps 30 TB of files in a self-managed object storage system in its data center and wants to copy them to Amazon S3 for analytics, with the LEAST custom code. The files should be encrypted in transit and checked for integrity when they arrive. Which solution meets these requirements?`,correct:[`Deploy an AWS DataSync agent on premises and create a task with the object storage location as the source and the S3 bucket as the destination`,`DataSync works with on-premises object storage and Amazon S3, and provides encryption and integrity validation without custom code.`],wrong:[[`Create an AWS Transfer Family server with SFTP enabled and write a script that reads each object and uploads it`,`Transfer Family accepts file uploads, but it cannot read from the on-premises object store, so the company must script the reads.`],[`Deploy an Amazon S3 File Gateway and write a script that mounts the object storage and copies files to its share`,`The gateway serves file shares to clients, and it does not pull from the object store, so the company must script the copying.`],[`Order an AWS Direct Connect connection and copy the objects across it with a custom script on an EC2 instance`,`Direct Connect provides a network link only, and the company would still write and run the copy code itself.`]],slot:1,evidence:[`datasync-what-is|DataSync works with the following on-premises storage systems: Network File System (NFS) Server Message Block (SMB) Hadoop Distributed File Systems (HDFS) Object storage`,`datasync-what-is|DataSync includes automatic encryption and data integrity validation to help make sure that your data arrives securely, intact, and ready to use.`]}),t({id:`transfer-dock-013`,building:`transfer-dock`,bullets:[`3.5-K3`,`3.5-S3`],d:2,tags:[`mock-reserve`],stem:`A publishing company runs Linux web servers on Amazon EC2 that read content from a shared Amazon EFS file system. Freelance editors upload new content with SFTP clients that they cannot change, and the company wants the uploads to land directly in EFS with the LEAST server management. Which solution meets these requirements?`,correct:[`Create an AWS Transfer Family server that enables SFTP and uses Amazon EFS as its storage`,`Transfer Family supports SFTP into Amazon EFS file systems as a managed service, so the editors keep their clients and no servers are run.`],wrong:[[`Deploy an Amazon S3 File Gateway and have the editors upload to its share so that the files reach EFS`,`The gateway stores the files as S3 objects, not in the EFS file system that the web servers read.`],[`Run an SFTP daemon on an Amazon EC2 instance that mounts the EFS file system and accepts the editors' uploads`,`This works, but the company would patch and operate the instance, which conflicts with the LEAST server management.`],[`Create an AWS DataSync task from the editors' laptops to the EFS file system on a nightly schedule`,`DataSync needs an agent to read from the editors' own storage and does not accept SFTP uploads from the clients they already use.`]],slot:2,evidence:[`transfer-what-is|Amazon Elastic File System (Amazon EFS) Network File System (NFS) file systems.`,`transfer-what-is|The following are some common use cases for using Transfer Family with Amazon EFS: Data distribution Supply chain Content management Web serving applications`,`transfer-what-is|You can use this service to migrate your file transfer-based workflows to AWS while maintaining your end users' clients and configurations as is.`]}),t({id:`transfer-dock-014`,building:`transfer-dock`,bullets:[`3.5-S3`],d:3,tags:[`mock-reserve`],stem:`An office keeps working files on an on-premises Windows file share over SMB. The company wants the files stored in Amazon S3 so that cloud analytics can read them, but staff must keep opening recently used files quickly, with no change to their applications and no daily copy job to run. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Deploy an Amazon S3 File Gateway on premises and have the staff use its SMB file share`,`The gateway exposes S3 objects as SMB file shares and keeps recently used data in a local cache for low-latency access.`],wrong:[[`Run a nightly AWS DataSync task that copies the share to S3 and keep the files on the existing server`,`This is the daily copy job the company wants to avoid, and the S3 copy lags behind the file share until the next run.`],[`Create an AWS Transfer Family server with SFTP enabled and ask the staff to upload their files to it`,`Transfer Family offers SFTP uploads, not an SMB share, so applications would have to change.`],[`Deploy an AWS Storage Gateway Tape Gateway and have the staff save their files to virtual tapes`,`Tape Gateway provides virtual tapes for backup software, not an SMB share for working files.`]],slot:3,evidence:[`sgw-file-s3|You can store and retrieve files directly using the SMB file system version, 2 and 3 protocol.`,`sgw-file-s3|It also provides low-latency access to data through transparent local caching.`,`sgw-tape|Tape Gateway provides cloud-backed virtual tape storage.`]})],_=[t({id:`tuning-bay-001`,building:`tuning-bay`,bullets:[`3.3-K4`],d:1,tags:[`placement-eligible`],stem:`A company's Amazon DynamoDB table runs in provisioned mode with auto scaling. A campaign now sends write traffic that jumps within seconds at unpredictable times, and writes are throttled before auto scaling adds capacity. The team wants the throttling to stop without forecasting the spikes. Which change meets these requirements with the LEAST operational overhead?`,correct:[`Switch the table to on-demand capacity mode`,`On-demand mode needs no capacity planning, monitoring of usage or scaling policies, so the table adapts to the spikes without a forecast.`],wrong:[[`Raise the maximum capacity of the auto scaling policy to a much higher value`,`Auto scaling still triggers only after consumed capacity breaches the target utilization for two consecutive minutes, so a higher maximum does not make it react sooner.`],[`Add a DAX cluster in front of the table`,`DAX accelerates reads from its item cache and writes still go through to the table, so the write throttling remains.`],[`Raise the provisioned write capacity by hand before each campaign`,`The spikes arrive at unpredictable times, so the team would have to forecast them and adjust capacity by hand.`]],slot:0,evidence:[`dynamodb-capacity|DynamoDB on-demand enables you to create a table without worrying about capacity planning, monitoring usage, and configuring scaling policies.`,`dynamodb-provisioned|Auto scaling triggers when your consumed capacity breaches the configured target utilization for two consecutive minutes.`]}),t({id:`tuning-bay-002`,building:`tuning-bay`,bullets:[`3.3-K4`],d:2,tags:[`placement-eligible`],stem:`A company runs an Amazon DynamoDB table in provisioned mode with a global secondary index that uses a different partition key. Write requests to the table are throttled during busy hours, yet the metrics show that the base table's provisioned write capacity is far from fully used. The index was created with a small write capacity. Which change BEST stops the throttling?`,correct:[`Increase the provisioned write capacity of the global secondary index`,`An index has provisioned throughput settings separate from the base table, and writes to the table are throttled when the index has insufficient write capacity.`],wrong:[[`Increase the provisioned write capacity of the base table`,`The base table is not the constraint, because its provisioned write capacity is far from fully used.`],[`Increase the provisioned read capacity of the global secondary index`,`The throttled requests are writes, and read capacity does not change the write capacity of the index.`],[`Add a DAX cluster in front of the table to absorb the write requests`,`DAX serves cached reads and writes still go through to the table and its index, so the index remains the constraint.`]],slot:1,evidence:[`dynamodb-gsi|The provisioned throughput settings of a global secondary index are separate from those of its base table.`,`dynamodb-gsi|If you perform heavy write activity on the table, but a global secondary index on that table has insufficient write capacity, the write activity on the table will be throttled.`]}),t({id:`tuning-bay-003`,building:`tuning-bay`,bullets:[`3.3-K3`],d:2,tags:[`placement-eligible`],stem:`A company stores application events in an Amazon DynamoDB table whose partition key is the event's status code, which has only five possible values. Writes are throttled even though the table's provisioned capacity is far from fully used. Which change is the SIMPLEST way to stop the throttling without raising the provisioned capacity?`,correct:[`Redesign the key schema around a partition key with many distinct values, such as a user ID`,`Requests then spread across many partitions instead of piling onto a few heavily requested key values, so the existing capacity is used efficiently.`],wrong:[[`Raise the table's write capacity units until the throttling stops`,`This raises the provisioned capacity, which the company ruled out, and each partition still has its own maximum.`],[`Switch the table to on-demand capacity mode so DynamoDB manages the capacity`,`Capacity mode does not change the key design, and every partition is still designed to deliver only a fixed maximum of write units per second.`],[`Add a sort key made from the event timestamp to the existing key schema`,`The partition key determines the logical partitions, so the five status-code values would still receive all of the writes.`]],slot:2,evidence:[`dynamodb-pk-uniform|A partition key design that doesn't distribute I/O requests effectively can create "hot" partitions that result in throttling and use your provisioned I/O capacity inefficiently.`,`dynamodb-pk-uniform|It does mean that the more distinct partition key values that your workload accesses, the more those requests will be spread across the partitioned space.`,`dynamodb-partition-keys|Every partition in a DynamoDB table is designed to deliver a maximum capacity of 3,000 read units per second and 1,000 write units per second.`]}),t({id:`tuning-bay-004`,building:`tuning-bay`,bullets:[`3.3-K3`],d:3,tags:[`placement-eligible`],stem:`An ad platform records click events in an Amazon DynamoDB table. The partition key is the date rounded to the day and the sort key is an event ID, so nearly all writes during a campaign hit the current day's key and are throttled. A daily report must still retrieve every event for one day. Which solution BEST stops the write throttling while keeping the report workable?`,correct:[`Append a random number suffix to the date in the partition key, then query every suffix and merge the results`,`The random suffix spreads the day's writes across many partition key values, and the report reads all suffixes and merges them.`],wrong:[[`Use a randomly generated unique ID as the whole partition key and have the report scan the table for one day`,`Writes would spread, but the report could no longer query a single day by key and would have to read the whole table.`],[`Keep the date as the partition key and add the event timestamp as the sort key to order the day's items`,`All of a day's writes would still go to one partition key value, so the hot key and the throttling remain.`],[`Switch the table to on-demand capacity mode so DynamoDB absorbs the burst of writes on the current day's key`,`Capacity mode does not remove the hot key: a single partition is still designed to deliver only a fixed maximum of write units per second.`]],slot:3,evidence:[`dynamodb-write-sharding|You can add a random number to the partition key values to distribute the items among partitions.`,`dynamodb-write-sharding|However, to read all the items for a given day, you would have to query the items for all the suffixes and then merge the results.`,`dynamodb-partition-keys|Every partition in a DynamoDB table is designed to deliver a maximum capacity of 3,000 read units per second and 1,000 write units per second.`]}),t({id:`tuning-bay-005`,building:`tuning-bay`,bullets:[`3.3-K4`],d:2,tags:[`placement-eligible`],stem:`A product catalog service uses an Amazon DynamoDB table in provisioned mode. It performs 600 eventually consistent reads per second on 8 KB items and 300 writes per second of 2 KB items. Which provisioned capacity avoids throttling with the LEAST over-provisioning?`,correct:[`600 read capacity units and 600 write capacity units`,`An 8 KB eventually consistent read needs 1 read unit and a 2 KB write needs 2 write units, so 600 reads and 300 writes per second need 600 and 600.`],wrong:[[`600 read capacity units and 300 write capacity units`,`Write sizes are rounded up to 1 KB multiples, so each 2 KB write needs 2 write units and 300 would throttle the writes.`],[`1,200 read capacity units and 600 write capacity units`,`This sizes reads as strongly consistent (2 units for an 8 KB item); the eventually consistent reads need only 1 unit each, so it over-provisions.`],[`300 read capacity units and 300 write capacity units`,`It halves both figures: an 8 KB eventually consistent read still needs a full read unit, and a 2 KB write needs 2 write units, so it would throttle.`]],slot:0,evidence:[`dynamodb-rw-ops|You'll require 1 read unit if you choose eventually consistent reads or 4 read units for a transactional read request.`,`dynamodb-rw-ops|For example, if your item size is 2 KB, you require 2 write units to sustain one write request or 4 write units for a transactional write request.`,`dynamodb-rw-ops|Item sizes for writes are rounded up to the next 1 KB multiple.`]}),t({id:`tuning-bay-006`,postGuide:[`rds-gp3-storage`],building:`tuning-bay`,bullets:[`3.3-K4`],d:1,stem:`A company runs a production OLTP database on Amazon RDS for PostgreSQL. During checkout peaks the database must deliver low I/O latency and consistent I/O throughput. Which storage type BEST meets these requirements?`,correct:[`Provisioned IOPS SSD storage, with the IOPS rate specified when the DB instance is created`,`Provisioned IOPS storage is designed for I/O-intensive database workloads that need low I/O latency and consistent I/O throughput.`],wrong:[[`General Purpose SSD gp3 storage left at its baseline storage performance`,`General Purpose storage suits workloads that are not latency sensitive, and such instances can see much longer latency than Provisioned IOPS ones.`],[`General Purpose SSD gp2 storage on a larger volume so that the baseline IOPS rises with the volume size`,`gp2 is the previous generation and some workloads exhaust its burst credit balance, so it cannot promise consistent I/O at the peaks.`],[`General Purpose SSD gp3 storage with storage autoscaling enabled to cope with the checkout peaks`,`Storage autoscaling adds free space when it runs low; it does not provide low latency or consistent throughput.`]],slot:1,evidence:[`rds-storage|Provisioned IOPS storage is designed to meet the needs of I/O-intensive workloads, particularly database workloads, that require low I/O latency and consistent I/O throughput.`,`rds-storage|DB instances that use General Purpose storage can experience much longer latency than instances that use Provisioned IOPS storage.`,`rds-storage-autoscaling|With storage autoscaling enabled, when Amazon RDS detects that you are running out of free database space it automatically scales up your storage.`]}),t({id:`tuning-bay-007`,building:`tuning-bay`,bullets:[`3.3-K4`,`3.3-K3`],d:2,tags:[`placement-eligible`],stem:`An ecommerce company runs a read-intensive product catalog on an Amazon DynamoDB table in provisioned mode. Product pages tolerate data that is a moment out of date. The company wants to cut the read capacity the table needs without changing the items or the key schema. Which change reduces the required read capacity by the MOST?`,correct:[`Use eventually consistent reads in the application`,`One read capacity unit covers two eventually consistent reads of an item up to 4 KB, versus one strongly consistent read.`],wrong:[[`Use transactional reads for every product page request`,`A transactional read of an item up to 4 KB requires two read units, so this doubles the capacity needed.`],[`Keep strongly consistent reads and raise the provisioned read capacity ahead of the peaks`,`Strongly consistent reads consume twice as many database resources as eventually consistent reads, so this raises rather than cuts the capacity.`],[`Move the table to on-demand mode and keep strongly consistent reads`,`On-demand still counts one strongly consistent read as a full read request unit, twice the cost of an eventually consistent read.`]],slot:2,evidence:[`dynamodb-provisioned|For an item up to 4 KB, one read capacity unit (RCU) represents one strongly consistent read operation per second, or two eventually consistent read operations per second.`,`dynamodb-rw-ops|A transactional read request of an item up to 4 KB requires two read units.`,`dynamodb-provisioned|Read consistency requirements — Read capacity units are based on strongly consistent read operations, which consume twice as many database resources as eventually consistent reads.`]}),t({id:`tuning-bay-008`,building:`tuning-bay`,bullets:[`3.3-K3`],d:2,tags:[`trap:multi-az-vs-read-replicas`],stem:`A company's order application runs on Amazon RDS for MySQL. The product-detail page looks up the same few thousand product rows thousands of times per minute. The rows change only a few times a day, and database CPU is high because of these repeated reads. The company wants the repeated reads taken off the database and will change the application to check a cache first. Which solution BEST meets these requirements?`,correct:[`Add an Amazon ElastiCache cache and load a product row into it when the application first misses`,`A cache sits between the application and the database, and lazy loading puts data in the cache only when necessary, so repeated lookups are served from memory.`],wrong:[[`Convert the DB instance to a Multi-AZ DB instance deployment and point the lookups at the standby`,`The standby of a Multi-AZ DB instance deployment provides failover support but does not serve read traffic.`],[`Create a read replica and send the product lookups to it`,`Every repeated lookup still runs as a query on a database instance, so the repeated reads are not taken off the database layer.`],[`Put an Amazon RDS Proxy in front of the DB instance and send the lookups through the proxy`,`The proxy pools and shares connections and does not cache results, so the queries still run on the DB instance.`]],slot:3,evidence:[`elasticache-strategies|Amazon ElastiCache is an in-memory key-value store that sits between your application and the data store (database) that it accesses.`,`elasticache-strategies|Lazy loading As the name implies, lazy loading is a caching strategy that loads data into the cache only when necessary.`,`rds-multi-az|A Multi-AZ DB instance deployment has one standby DB instance that provides failover support, but doesn't serve read traffic.`]}),e({id:`tuning-bay-009`,building:`tuning-bay`,bullets:[`3.3-K3`,`3.3-K4`],d:3,tags:[`trap:multi-az-vs-read-replicas`],stem:`A production Amazon RDS for PostgreSQL DB instance is saturated by a write-intensive order-ingestion workload: compute and write I/O are at their limits while read traffic is light. Adding read replicas did not reduce the write latency. Which TWO changes BEST address the bottleneck? (Choose two.)`,correct:[[`Modify the DB instance to a larger DB instance class with more compute and memory`,`The instance class determines the computation and memory capacity of the DB instance that receives every write.`],[`Move the storage to Provisioned IOPS SSD with an IOPS rate sized for the ingestion load`,`Provisioned IOPS storage is optimized for OLTP workloads that need consistent performance.`]],wrong:[[`Add more read replicas and send the ingestion writes to them`,`A read replica allows only read-only connections, so it cannot take the writes.`],[`Enable a Multi-AZ DB instance deployment so that the standby shares the write load`,`The standby provides failover support and does not serve traffic, so the primary still takes every write.`],[`Place an Amazon ElastiCache cluster in front of the database to absorb the ingestion writes`,`ElastiCache sits between the application and the database, and writes still reach the database, so its saturated write path is not relieved.`]],slots:[0,3],evidence:[`rds-instance-class|The DB instance class determines the computation and memory capacity of an Amazon RDS DB instance.`,`rds-storage|Provisioned IOPS storage is optimized for online transaction processing (OLTP) workloads that require consistent performance.`,`rds-read-replicas|The read replica operates as a DB instance that allows only read-only connections.`,`elasticache-strategies|Amazon ElastiCache is an in-memory key-value store that sits between your application and the data store (database) that it accesses.`,`elasticache-strategies|The write-through strategy adds data or updates data in the cache whenever data is written to the database.`]}),t({id:`tuning-bay-010`,building:`tuning-bay`,bullets:[`3.3-K5`],d:1,stem:`A company's AWS Lambda functions connect to an Amazon RDS for MySQL database. During traffic spikes the database reports "too many connections" errors because every invocation opens its own connection. The company wants to reduce the number of connections the functions open, with the LEAST change to the function code. Which solution meets this requirement?`,correct:[`Create an Amazon RDS Proxy for the database and point the functions at the proxy endpoint`,`Lambda functions make frequent short database connections that benefit from the connection pooling RDS Proxy provides.`],wrong:[[`Add a read replica and point the functions at the replica endpoint`,`A read replica allows only read-only connections, and each invocation would still open its own connection.`],[`Convert the DB instance to a Multi-AZ DB instance deployment with a standby`,`The standby provides failover support but does not serve traffic, so it adds no capacity for connections.`],[`Scale the DB instance up to a larger DB instance class and keep the direct connections`,`Every invocation would still open its own connection, spending database memory and CPU on connection overhead, so the number of connections the functions open does not fall.`]],slot:0,evidence:[`rds-proxy-planning|Any DB instance that encounters "too many connections" errors is a good candidate for associating with a proxy.`,`rds-proxy-planning|These functions make frequent short database connections that benefit from connection pooling offered by RDS Proxy.`,`rds-proxy|This approach avoids the memory and CPU overhead of opening a new database connection each time.`]}),t({id:`tuning-bay-011`,building:`tuning-bay`,bullets:[`3.3-K5`],d:2,stem:`A software-as-a-service application keeps thousands of long-lived connections open to an Amazon RDS for PostgreSQL DB instance on a small T3 DB instance class. The instance runs short of memory when connection counts climb, and the application cannot be rewritten. Which solution BEST reduces the connection load on the database?`,correct:[`Create an Amazon RDS Proxy and have the application connect to the proxy endpoint`,`The proxy lets the application open many client connections while it keeps a smaller number of long-lived connections to the DB instance, avoiding out-of-memory conditions.`],wrong:[[`Create a read replica and spread the application's connections across the primary and the replica`,`The replica allows only read-only connections, so the application's write connections still all go to the primary.`],[`Raise the provisioned IOPS on the DB instance's storage volume`,`IOPS governs storage I/O, not the memory that each open connection consumes on the DB instance.`],[`Convert to a Multi-AZ DB instance deployment so the standby accepts half of the connections`,`The standby provides failover support but does not serve traffic, so it accepts none of the connections.`]],slot:1,evidence:[`rds-proxy-planning|For DB instances that use smaller AWS instance classes, such as T2 or T3, using a proxy can help avoid out-of-memory conditions.`,`rds-proxy-planning|The proxy enables applications to open many client connections, while the proxy manages a smaller number of long-lived connections to the DB instance .`,`rds-proxy|You can enable RDS Proxy for most applications with no code changes.`]}),e({id:`tuning-bay-012`,building:`tuning-bay`,bullets:[`3.3-K5`],d:3,stem:`A company will connect AWS Lambda functions to its production Amazon RDS for PostgreSQL Multi-AZ DB instance. The company wants connections to survive a database failover with less disruption and wants the functions to avoid storing database passwords in their code. Which TWO actions meet these requirements with the LEAST operational overhead? (Choose two.)`,correct:[[`Create an RDS Proxy for the DB instance and have the functions connect to the proxy endpoint`,`The proxy automatically connects to the standby DB instance after a failure while preserving application connections.`],[`Configure the proxy to require IAM authentication from clients and to use credentials stored in AWS Secrets Manager`,`The proxy can enforce IAM authentication for clients and connect to the database with credentials kept in Secrets Manager, so no passwords sit in the function code.`]],wrong:[[`Raise the functions' reserved concurrency so that more invocations connect in parallel`,`More parallel invocations open more connections, which makes connection pressure worse and does nothing for failover or passwords.`],[`Associate the proxy with a read replica of the database instead of the writer DB instance`,`In replication configurations a proxy can be associated only with the writer DB instance, not a read replica.`],[`Make the DB instance publicly accessible so the functions can reach it without a proxy`,`This neither pools connections nor removes passwords from the code, and it exposes the production database.`]],slots:[1,4],evidence:[`rds-proxy|RDS Proxy makes applications more resilient to database failures by automatically connecting to a standby DB instance while preserving application connections.`,`rds-proxy|By using RDS Proxy, you can enforce AWS Identity and Access Management (IAM) authentication for clients connecting to the proxy, and the proxy can connect to databases using either IAM database authentication or credentials stored in AWS Secrets Manager.`,`rds-proxy|For RDS DB instances in replication configurations, you can associate a proxy only with the writer DB instance, not a read replica.`]}),e({id:`tuning-bay-013`,building:`tuning-bay`,bullets:[`3.3-S2`,`3.3-K5`],d:3,tags:[`trap:multi-az-vs-read-replicas`],stem:`A company runs a read-heavy ecommerce catalog on Amazon RDS for MySQL. Connection spikes from AWS Lambda functions, reporting queries that slow the primary, and the need to survive the loss of an Availability Zone are the three problems to solve. Which THREE actions together meet these requirements? (Choose three.)`,correct:[[`Deploy the database as a Multi-AZ DB instance deployment`,`The standby DB instance in another Availability Zone provides failover support if the primary fails.`],[`Create read replicas and direct the reporting queries to them`,`Read replicas scale beyond a single instance for read-heavy workloads and take reporting queries off the primary.`],[`Create an RDS Proxy for the writer DB instance and connect the functions through it`,`Lambda functions benefit from the connection pooling a proxy provides, and the proxy attaches to the writer.`]],wrong:[[`Send the reporting queries to the Multi-AZ standby DB instance`,`The standby of a Multi-AZ DB instance deployment does not serve read traffic.`],[`Associate an RDS Proxy with each read replica instead of the writer`,`A proxy can be associated only with the writer DB instance, not a read replica.`],[`Enable storage autoscaling to absorb the connection spikes`,`Storage autoscaling adds free storage space; it does not pool connections.`]],slots:[0,2,5],evidence:[`rds-multi-az|A Multi-AZ DB instance deployment has one standby DB instance that provides failover support, but doesn't serve read traffic.`,`rds-read-replicas|Scaling beyond the compute or I/O capacity of a single DB instance for read-heavy database workloads.`,`rds-proxy-planning|These functions make frequent short database connections that benefit from connection pooling offered by RDS Proxy.`]}),t({id:`tuning-bay-014`,building:`tuning-bay`,bullets:[`3.3-S2`,`3.3-K3`],d:2,tags:[`placement-eligible`],stem:`A gaming company needs a session store for millions of simultaneous players. Each session is read and written by player ID, and the store must deliver single-digit millisecond latency at any scale without the company managing database servers. Which solution BEST meets these requirements?`,correct:[`An Amazon DynamoDB table with the player ID as the partition key`,`A key-value database suits session stores and scales to extremely high request throughput for millions of simultaneous users with no servers to manage.`],wrong:[[`Amazon RDS for MySQL in a Multi-AZ deployment on a memory-optimized DB instance class`,`It is a database server the company would size and manage, and a single writer instance does not scale out to millions of simultaneous users.`],[`Amazon RDS for PostgreSQL with several read replicas and Provisioned IOPS storage`,`Read replicas allow only read-only connections, so the session writes still funnel into one primary DB instance.`],[`An Amazon Redshift data warehouse that stores each session and answers queries over it`,`Redshift is a petabyte-scale data warehouse for analytic queries over large data sets, not a store for single-digit millisecond reads and writes of each player session by player ID.`]],slot:2,evidence:[`database-decision|Amazon DynamoDB Key-value Use for workloads such as session stores or shopping carts.`,`database-decision|Key-value databases can scale to large amounts of data and extremely high throughput of requests, while servicing millions of simultaneous users through distributed processing and storage.`,`database-decision|Optimized to provide a serverless, NoSQL, fully managed database with single-digit millisecond performance at any scale.`,`redshift-what-is|Amazon Redshift is a fully managed, petabyte-scale data warehouse service in the cloud.`]}),t({id:`tuning-bay-015`,building:`tuning-bay`,bullets:[`3.3-K4`,`3.3-S2`],d:3,tags:[`placement-eligible`],stem:`A company stores seven years of order history in an Amazon DynamoDB table that holds many terabytes and keeps growing. The table is read only occasionally, its throughput needs are small, and storage is by far the largest part of the table's cost. The application must keep using the same table without changes. Which change lowers the cost of the table the MOST?`,correct:[`Change the table class of the table to DynamoDB Standard-IA`,`The Standard-IA table class is optimized for tables where storage is the dominant cost, and it needs no change to the table or the application.`],wrong:[[`Switch the table to provisioned mode with a small amount of provisioned capacity`,`The capacity mode changes how throughput is billed and does not reduce the storage cost that dominates this table.`],[`Enable DynamoDB time to live (TTL) so that all items expire after one year`,`The company must keep seven years of history, and expiring the items would delete data it needs.`],[`Export the table to Amazon S3 and have the application read the exported files`,`The application must keep using the same table, and this change would force it to be rewritten.`]],slot:3,evidence:[`dynamodb-table-classes|The DynamoDB Standard-Infrequent Access (DynamoDB Standard-IA) table class is optimized for tables where storage is the dominant cost.`,`dynamodb-table-classes|The DynamoDB Standard-IA table class offers lower storage costs than DynamoDB Standard, and is the most cost-effective option for tables where storage is the dominant cost.`]}),t({id:`tuning-bay-016`,building:`tuning-bay`,bullets:[`3.3-K4`],d:2,tags:[`mock-reserve`],stem:`An Amazon RDS for MySQL DB instance on a general-purpose DB instance class shows heavy swapping and frequent reads from storage because the working set of a memory-intensive analytics workload no longer fits in memory. Compute and storage IOPS are not saturated. Which change BEST addresses the bottleneck?`,correct:[`Modify the DB instance to a memory-optimized DB instance class`,`Memory-optimized classes are meant for memory-intensive workloads in open-source databases such as MySQL, so more of the working set stays in memory.`],wrong:[[`Modify the DB instance to a compute-optimized DB instance class`,`Compute-optimized classes target compute-intensive workloads, but the bottleneck here is memory, not compute.`],[`Move the storage to Provisioned IOPS SSD with a higher IOPS rate`,`Storage IOPS are not saturated, so more IOPS leaves the memory shortage and the swapping unchanged.`],[`Enable storage autoscaling with a higher maximum storage threshold`,`Autoscaling adds free storage space and does nothing for the memory available to the database.`]],slot:0,evidence:[`rds-instance-class-types|These instance classes are ideal for running memory-intensive workloads in open-source databases such as MySQL and PostgreSQL.`,`rds-instance-class-types|db.c6gd – Instance classes that are ideal for running advanced compute-intensive workloads.`,`rds-instance-class|The DB instance class determines the computation and memory capacity of an Amazon RDS DB instance.`]}),t({id:`tuning-bay-017`,building:`tuning-bay`,bullets:[`3.3-K4`],d:3,tags:[`mock-reserve`],stem:`A retailer's Amazon DynamoDB table runs in on-demand mode and normally peaks at about 2,000 reads per second. A planned flash sale is expected to drive about 25,000 reads per second within minutes of starting, and the retailer must avoid throttling. The expected peak is known from load tests. What should a solutions architect do BEFORE the sale to give the HIGHEST chance of avoiding throttling?`,correct:[`Switch the table to provisioned capacity mode and set the read capacity units for the expected peak before the sale`,`In provisioned mode the table has the throughput that you specify from the start, so the jump does not depend on gradual scaling.`],wrong:[[`Keep on-demand mode and rely on it alone to serve any traffic level`,`On-demand accommodates up to double the previous peak, and throttling can occur if traffic exceeds that within 30 minutes.`],[`Switch to provisioned mode with auto scaling at a low initial capacity and let it follow the sale traffic`,`Auto scaling reacts only after consumed capacity breaches the target utilization for two consecutive minutes, so a sudden jump of more than tenfold can still throttle.`],[`Add a global secondary index on the table's partition key`,`An index adds another copy of the data to maintain and does not raise the base table's ability to absorb the read spike.`]],slot:1,evidence:[`dynamodb-ondemand|However, throttling can occur if you exceed double your previous peak within 30 minutes.`,`dynamodb-provisioned|Auto scaling triggers when your consumed capacity breaches the configured target utilization for two consecutive minutes.`,`dynamodb-provisioned|You can switch tables from on-demand mode to provisioned capacity mode at any time.`,`dynamodb-provisioned|When you create a new provisioned table in DynamoDB, you must specify its provisioned throughput capacity.`]})],v=[t({id:`turbine-hall-001`,building:`turbine-hall`,bullets:[`3.2-K2`],d:1,tags:[`trap:cloudfront-vs-global-accelerator`],stem:`A company serves product images and JavaScript files from an Amazon S3 bucket in a single Region. Customers on other continents report slow page loads. The company wants to lower latency for these static files with the LEAST operational overhead. Which solution BEST meets these requirements?`,correct:[`Create an Amazon CloudFront distribution that uses the S3 bucket as its origin`,`CloudFront routes each request to the edge location with the lowest latency and serves cached copies from there.`],wrong:[[`Create an AWS Global Accelerator accelerator that uses the S3 bucket as an endpoint`,`A standard accelerator accepts load balancers, EC2 instances or Elastic IP addresses as endpoints, not an S3 bucket.`],[`Move the web tier to a larger Amazon EC2 instance type in the same Region as the bucket`,`A bigger instance does not shorten the network distance between distant users and the Region.`],[`Copy the files into an S3 bucket in every Region and change the application to pick one`,`This adds replication and Region-selection code to maintain, which the company wants to avoid.`]],slot:0,evidence:[`cloudfront-what-is|CloudFront delivers your content through a worldwide network of data centers called edge locations.`,`cloudfront-what-is|Users get lower latency—the time it takes to load the first byte of the file—and higher data transfer rates.`,`ga-how|For standard accelerators, the endpoints are Network Load Balancers, Application Load Balancers, Amazon EC2 instances, or Elastic IP addresses.`]}),t({id:`turbine-hall-002`,building:`turbine-hall`,bullets:[`3.2-K2`],d:2,stem:`A company delivers a web site through Amazon CloudFront. Every viewer request must have its URI rewritten to append a default document name. The rewrite is a few lines of JavaScript, and traffic reaches millions of requests per second. The company wants the LOWEST latency added to each request. Which solution meets these requirements?`,correct:[`Attach a CloudFront Function to the viewer request event of the distribution`,`CloudFront Functions are built for high-scale, latency-sensitive customisations with submillisecond startup.`],wrong:[[`Attach a Lambda@Edge function to the viewer request event of the distribution`,`Lambda@Edge is aimed at complex functions and full application logic, not the lightest, fastest-starting rewrites.`],[`Send requests to an AWS Lambda function in one Region through Amazon API Gateway`,`This runs the code in a single Region instead of near viewers and adds a network hop to every request.`],[`Run a fleet of Amazon EC2 proxy instances that rewrite the URI before CloudFront`,`This adds servers to manage and an extra hop, and does not run at the edge close to viewers.`]],slot:1,evidence:[`cf-edge-functions|The CloudFront Functions runtime environment offers submillisecond startup times, scales immediately to handle millions of requests per second, and is highly secure.`,`cf-edge-functions|Lambda@Edge is an extension of AWS Lambda that offers powerful and flexible computing for complex functions and full application logic closer to your viewers`]}),e({id:`turbine-hall-003`,building:`turbine-hall`,bullets:[`3.2-K2`],d:2,stem:`A company runs its web tier on Amazon EC2 instances in one Availability Zone of a Region. An outage in that zone would take the application offline. The company wants to distribute the compute tier so that it keeps serving traffic if one Availability Zone fails. Which TWO actions meet these requirements? (Choose two.)`,correct:[[`Configure the Auto Scaling group to launch instances in subnets of at least two Availability Zones`,`If one zone becomes unavailable, Amazon EC2 Auto Scaling can launch instances in another one to compensate.`],[`Place an Application Load Balancer in front of the instances across those zones`,`A load balancer reroutes traffic to available instances when an Availability Zone is impaired.`]],wrong:[[`Replace the instances with a single larger instance type in the original zone`,`Capacity grows, but one zone still holds all the compute, so a zone failure takes it offline.`],[`Attach an Elastic IP address to each instance in the original zone`,`A fixed address does not move compute out of the failed zone.`],[`Take daily snapshots of each Amazon EBS volume in the original zone`,`Snapshots protect data but do not keep compute running while the zone is down.`]],slots:[1,3],evidence:[`waf-multi-location|All compute associated with your workload should be distributed among multiple Availability Zones.`,`asg-benefits|If one Availability Zone becomes unavailable, Amazon EC2 Auto Scaling can launch instances in another one to compensate.`,`waf-multi-location|AWS load balancers can reroute traffic to available instances in the event of an Availability Zone impairment.`]}),t({id:`turbine-hall-004`,building:`turbine-hall`,bullets:[`3.2-K4`],d:1,stem:`A payroll application runs in an Amazon EC2 Auto Scaling group. Load rises sharply at the same time every Friday morning and falls on Saturday. The pattern never changes, and capacity must already be in place when the load arrives. Which scaling approach is the SIMPLEST way to meet these requirements?`,correct:[`Create scheduled actions that raise and lower the desired capacity at set times`,`Scheduled scaling changes capacity at specific times based on predictable load changes.`],wrong:[[`Create a step scaling policy that adds instances when a CloudWatch alarm on CPU is breached`,`Alarm-driven policies are reactive, so capacity arrives only after the load has already started.`],[`Create a target tracking policy on the average CPU utilization of the group`,`A target tracking policy responds after CPU moves away from the target value, not before the surge.`],[`Ask an operator to change the desired capacity by hand before each Friday morning`,`A manual change depends on a person every week, where a schedule would run automatically.`]],slot:2,evidence:[`asg-scheduled|With scheduled scaling, you can set up automatic scaling for your application based on predictable load changes.`,`asg-predictive|Predictive scaling can help you scale faster by launching capacity in advance of forecasted load, compared to using only dynamic scaling, which is reactive in nature.`]}),t({id:`turbine-hall-005`,building:`turbine-hall`,bullets:[`3.2-K4`],d:2,stem:`A company runs a reporting site on Amazon EC2 Auto Scaling. Traffic is high in business hours and low overnight and on weekends, but the size of each peak changes from week to week. The company wants capacity added ahead of each daily peak without anyone reviewing load patterns or writing schedules. Which solution meets these requirements with the LEAST effort?`,correct:[`Enable predictive scaling on the Auto Scaling group`,`Predictive scaling analyses historical load to detect daily or weekly patterns and forecasts future capacity needs.`],wrong:[[`Create scheduled actions that set the desired capacity for each hour of the week`,`Someone must review the load patterns and keep the schedule current as the weekly peaks change.`],[`Create a simple scaling policy with a single adjustment and a cooldown period`,`It is a reactive policy that acts only after an alarm is breached, so capacity is not in place ahead of the peak.`],[`Raise the minimum size of the group to the largest peak seen so far`,`The group would hold peak capacity all night and on weekends, which wastes money.`]],slot:3,evidence:[`asg-predictive|Predictive scaling works by analyzing historical load data to detect daily or weekly patterns in traffic flows.`,`asg-predictive|You also don't have to spend time reviewing your application's load patterns and trying to schedule the right amount of capacity using scheduled scaling.`]}),t({id:`turbine-hall-006`,building:`turbine-hall`,bullets:[`3.2-K4`],d:2,stem:`A company runs an Amazon ECS service and an Amazon DynamoDB table. The company wants both resources to scale automatically with load, using a single scaling service and no custom scaling code. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Define target tracking scaling policies on the ECS service and on the DynamoDB table`,`One scaling service (Application Auto Scaling) scales resources of individual AWS services beyond EC2, including ECS services and DynamoDB tables.`],wrong:[[`Define scaling policies for both resources in an Amazon EC2 Auto Scaling group`,`EC2 Auto Scaling manages groups of EC2 instances, so it cannot scale a DynamoDB table or an ECS service.`],[`Create Amazon CloudWatch alarms that email an administrator through Amazon SNS`,`A notification needs a person to change capacity, so the scaling is not automatic.`],[`Invoke an AWS Lambda function every minute that updates the table and the service`,`This is custom scaling code that the company must write, test and maintain.`]],slot:0,evidence:[`appas-what-is|Application Auto Scaling is a web service for developers and system administrators who need a solution for automatically scaling their scalable resources for individual AWS services beyond Amazon EC2 Auto Scaling.`,`appas-what-is|Aurora replicas Amazon Comprehend document classification and entity recognizer endpoints DynamoDB tables and global secondary indexes Amazon ECS services`]}),t({id:`turbine-hall-007`,building:`turbine-hall`,bullets:[`3.2-K4`],d:3,stem:`An application on an Amazon EC2 Auto Scaling group needs several minutes after launch to write a large data set to disk before an instance can serve traffic. During unpredictable spikes users see slow responses while new instances boot. The company does not want to pay to run extra instances at all times. Which solution BEST meets these requirements?`,correct:[`Add a warm pool of pre-initialised instances kept in the Stopped state`,`Instances in the pool are ready to start serving quickly on scale out, and stopped instances keep costs low.`],wrong:[[`Raise the minimum capacity of the group so that spare running instances are always available`,`Keeping spare instances running at all times is the over-provisioning the company wants to avoid.`],[`Create scheduled actions that add instances every hour in case of a spike`,`The spikes are unpredictable, so a fixed hourly schedule would pay for capacity that is often not needed.`],[`Lower the CloudWatch alarm threshold of a step scaling policy so that it scales out earlier`,`Earlier scale-out still waits for every new instance to boot, and it adds instances more often.`]],slot:1,evidence:[`asg-warm-pools|A warm pool gives you the ability to decrease latency for your applications that have exceptionally long boot times, for example, because instances need to write massive amounts of data to disk.`,`asg-warm-pools|With warm pools, you no longer have to over-provision your Auto Scaling groups to manage latency in order to improve application performance.`,`asg-warm-pools|Keeping instances in a Stopped state is an effective way to minimize costs.`]}),e({id:`turbine-hall-008`,building:`turbine-hall`,bullets:[`3.2-K4`,`3.2-S2`],d:3,stem:`A ticketing company runs a web fleet in an Amazon EC2 Auto Scaling group. A sale starts at exactly 09:00 every day and needs extra capacity ready beforehand. Unplanned bursts of traffic also occur at other times. The company wants to avoid idle capacity at other hours. Which TWO actions together meet these requirements? (Choose two.)`,correct:[[`Create a scheduled action that raises the desired capacity shortly before 09:00 each day`,`Scheduled scaling puts capacity in place at a known time based on a predictable load change.`],[`Add a target tracking policy on average CPU utilization to handle the unplanned bursts`,`The policy keeps the metric near its target by scaling out and in as load changes, and it can work alongside the scheduled action.`]],wrong:[[`Set the minimum capacity permanently to the size needed for the 09:00 sale`,`The fleet would hold sale-sized capacity at every hour, which is the idle capacity the company wants to avoid.`],[`Rely on a step scaling policy alone, with no scheduled action`,`The policy reacts only after an alarm is breached, so capacity is not ready at the start of the sale.`],[`Suspend all scaling policies during the sale and add instances by hand`,`Manual changes during the sale cannot react quickly to the unplanned bursts.`]],slots:[0,2],evidence:[`asg-scheduled|You can use scheduled scaling and scaling policies together to get the benefits of both approaches to scaling.`,`asg-scheduled|After a scheduled scaling action runs, the scaling policy can continue to make decisions about whether to further scale capacity.`,`asg-target-tracking|It will scale in, or decrease capacity, when CPU drops below 50 percent to optimize costs during periods of low utilization.`]}),t({id:`turbine-hall-009`,building:`turbine-hall`,bullets:[`3.2-S2`],d:1,stem:`A web application runs in an Amazon EC2 Auto Scaling group. The company wants the average CPU utilization of the group to stay near 50 percent as load rises and falls, and wants to manage as few CloudWatch alarms as possible. Which solution meets these requirements with the LEAST operational overhead?`,correct:[`Create a target tracking policy on ASGAverageCPUUtilization with a target of 50`,`Auto Scaling creates and manages the CloudWatch alarms and holds the metric near the target, like a thermostat.`],wrong:[[`Create a step scaling policy with one alarm for scale out and a second alarm for scale in`,`With step scaling you create and manage the CloudWatch alarms yourself, which adds overhead.`],[`Create a scheduled action that sets the desired capacity to a fixed number for each day`,`A fixed schedule does not follow the CPU utilization of the group as load changes.`],[`Create an Amazon CloudWatch alarm that sends an email when CPU utilization passes 50 percent`,`An email requires a person to change capacity, so the group is not scaled automatically.`]],slot:3,evidence:[`asg-target-tracking|ASGAverageCPUUtilization—Average CPU utilization of the Auto Scaling group.`,`asg-target-tracking|Amazon EC2 Auto Scaling creates and manages the CloudWatch alarms that invoke scaling events when the metric deviates from the target.`,`asg-step|With step scaling and simple scaling, you create and manage the CloudWatch alarms that invoke the scaling process.`]}),t({id:`turbine-hall-010`,building:`turbine-hall`,bullets:[`3.2-S2`],d:2,stem:`Worker instances in an Amazon EC2 Auto Scaling group process messages from an Amazon SQS queue. Each message takes a different time to process, and the company wants a target tracking policy that scales the workers in proportion to the work waiting. Which metric should the policy use to scale MOST effectively?`,correct:[`A custom backlog-per-instance metric: queue messages divided by running instances`,`The backlog per instance changes as the group grows or shrinks, so it can drive proportional scaling.`],wrong:[[`The ApproximateNumberOfMessagesVisible metric of the queue, used directly`,`The queue length does not change proportionally to the size of the group, so it is not a valid target tracking metric.`],[`The ASGAverageNetworkOut metric of the Auto Scaling group`,`Network bytes sent by the workers say little about how many messages are waiting for them.`],[`The RequestCount metric of an Application Load Balancer in front of the queue producers`,`Load balancer request counts do not change with the size of the worker group and do not measure the queue.`]],slot:0,evidence:[`asg-sqs|To scale your Auto Scaling group in proportion to the work waiting in your queue, use a backlog per instance metric.`,`asg-sqs|A policy that targets only the number of messages in the queue does not account for the number of instances available.`,`asg-target-tracking|The metric value must increase or decrease proportionally to the number of instances in the Auto Scaling group.`]}),t({id:`turbine-hall-011`,building:`turbine-hall`,bullets:[`3.2-S2`],d:2,stem:`An Amazon EC2 Auto Scaling group sometimes sees CPU utilization jump far above normal. The company wants to add a small number of instances when CPU is moderately high and a much larger number when CPU is extremely high, based on the size of the breach of a CloudWatch alarm. Which scaling policy BEST meets these requirements?`,correct:[`A step scaling policy with step adjustments for different sizes of alarm breach`,`Step scaling applies different adjustments depending on how far the metric is beyond the alarm threshold.`],wrong:[[`A target tracking scaling policy with a target of 60 percent average CPU utilization`,`Target tracking works out the capacity change itself, so the company cannot define its own increments for each breach size.`],[`A simple scaling policy with one scaling adjustment and a cooldown period`,`A simple policy applies a single adjustment however large the breach is.`],[`A scheduled action that adds the larger number of instances at a fixed time`,`The jumps are unplanned, so a fixed time does not match the breach.`]],slot:2,evidence:[`asg-step|You can define different step adjustments based on the breach size of the alarm.`,`asg-step|Simple scaling policies are similar to step scaling policies, except they're based on a single scaling adjustment, with a cooldown period between each scaling activity.`,`asg-target-tracking|If you want greater control, a step scaling policy might be the better option.`]}),e({id:`turbine-hall-012`,building:`turbine-hall`,bullets:[`3.2-S2`],d:2,tags:[`mock-reserve`],stem:`A web application runs in an Amazon EC2 Auto Scaling group behind an Application Load Balancer. The company wants a target tracking scaling policy whose metric rises and falls in proportion to the number of instances in the group. Which TWO metrics are suitable for this policy? (Choose two.)`,correct:[[`ALBRequestCountPerTarget`,`It is the average Application Load Balancer request count per target, which changes as instances are added or removed.`],[`ASGAverageCPUUtilization`,`It is the average CPU utilization of the group, which falls as load spreads over more instances.`]],wrong:[[`The Elastic Load Balancing RequestCount metric for the load balancer`,`Total requests received by the load balancer do not change with the utilization of the Auto Scaling group.`],[`The Elastic Load Balancing Latency metric for the load balancer`,`Latency can rise with utilization but does not necessarily change in proportion to group size.`],[`The ApproximateNumberOfMessagesVisible metric of an unrelated Amazon SQS queue`,`A queue length does not change in proportion to the size of the group, and this queue is not part of the web path.`]],slots:[2,4],evidence:[`asg-target-tracking|The metric value must increase or decrease proportionally to the number of instances in the Auto Scaling group.`,`asg-target-tracking|ALBRequestCountPerTarget—Average Application Load Balancer request count per target for your Auto Scaling group.`,`asg-target-tracking|The number of requests received by the load balancer doesn't change based on the utilization of the Auto Scaling group.`,`asg-target-tracking|Request latency can increase based on increasing utilization, but doesn't necessarily change proportionally.`]}),t({id:`turbine-hall-013`,building:`turbine-hall`,bullets:[`3.2-K2`],d:3,tags:[`mock-reserve`,`trap:cloudfront-vs-global-accelerator`],stem:`A studio runs a multiplayer game backend on Network Load Balancers in two Regions. Players around the world connect over UDP, and the studio wants them to enter through fixed addresses on the AWS global network and be moved to the other Region if one becomes unhealthy. Which solution BEST meets these requirements?`,correct:[`Use AWS Global Accelerator with a UDP listener and both load balancers as endpoints`,`Static anycast addresses are single fixed entry points, listeners support UDP, and routing follows endpoint health.`],wrong:[[`Create an Amazon CloudFront distribution that uses both load balancers as origins`,`CloudFront speeds up delivery of web content cached at edge locations, and it does not provide UDP game-traffic entry points.`],[`Create Amazon Route 53 latency records that point players at each load balancer`,`DNS answers can be cached by clients, so routing is not independent of DNS and players do not get fixed entry addresses.`],[`Place Amazon EC2 relay instances with Elastic IP addresses in each Region`,`This adds servers to patch and scale, and players still reach the relays over the internet.`]],slot:3,evidence:[`ga-listeners|Listeners support TCP and UDP protocols.`,`ga-how|The static IP addresses provided by AWS Global Accelerator serve as single fixed entry points for your clients.`,`ga-what-is|For standard accelerators, Global Accelerator uses the AWS global network to route traffic to the optimal regional endpoint based on health, client location, and policies that you configure, which increases the availability of your applications.`]})],y=Object.values(Object.assign({"../../content/questions/express/cache-pavilion.ts":n,"../../content/questions/express/container-yard.ts":r,"../../content/questions/express/data-lake-reservoir.ts":i,"../../content/questions/express/database-registry.ts":a,"../../content/questions/express/edge-link-terminal.ts":o,"../../content/questions/express/engine-works.ts":s,"../../content/questions/express/express-interchange.ts":c,"../../content/questions/express/express-rail-hub.ts":l,"../../content/questions/express/freight-depot.ts":u,"../../content/questions/express/grid-planning-office.ts":d,"../../content/questions/express/ingestion-gate.ts":f,"../../content/questions/express/read-replica-annex.ts":p,"../../content/questions/express/refinery.ts":m,"../../content/questions/express/streaming-canal.ts":h,"../../content/questions/express/transfer-dock.ts":g,"../../content/questions/express/tuning-bay.ts":_,"../../content/questions/express/turbine-hall.ts":v})).flat();export{y as questions};